"""One-click installer: recreates the whole youtube-automation-agents project.

Run from inside the youtube-automation-agents folder:
    python setup_project.py

Existing files are overwritten with the versions embedded below.
"""
import os

FILES = {
    '.gitignore': "# Never upload secrets or tokens to GitHub\n.env\nclient_secret*.json\ntoken_*.json\n\n# Ignore media files & virtual environments\n*.mp4\n*.mp3\n*.wav\n# ...except WonderSprout's intro and outro, which every GitHub run needs\n!assets/wondersprout/*.mp4\n!assets/audio/**\nGDrive_Mount/\n__pycache__/\nvenv/\n.DS_Store\n",
    '.env.example': 'YOUTUBE_API_KEY="AIzaSyYourYouTubeAPIKeyHere"\nGEMINI_API_KEY="AIzaSyYourGeminiAPIKeyHere"\nPIXABAY_API_KEY="YourPixabayAPIKeyHere"\n# Free backup AI used when Gemini\'s daily quota runs out (console.groq.com)\nGROQ_API_KEY=gsk_YourGroqAPIKeyHere\n# Optional alternative stock footage source\nPEXELS_API_KEY="YourPexelsAPIKeyHere"\nTELEGRAM_BOT_TOKEN="7123456789:AAHYourBotTokenHere"\nTELEGRAM_CHANNEL_ID="-100YourChannelIDHere"\n# Optional, kept for possible future use (not used by the pipeline today)\nHF_TOKEN="hf_YourHuggingFaceTokenHere"\n',
    'requirements.txt': 'pyyaml>=6.0.2\npython-dotenv==1.0.1\nrequests>=2.31.0\nyt-dlp>=2025.1.1\nmoviepy==1.0.3\nedge-tts>=7.3.1\ntzdata>=2024.1\ngoogle-genai>=1.0.0\ngoogle-api-python-client>=2.150.0\ngoogle-auth-oauthlib>=1.2.1\ngoogle-auth-httplib2>=0.2.0\n',
    'BRAIN.md': '# MASTER BRAIN & MULTI-AGENT CONFIGURATION\nGlobal rules shared by every channel. Modify the YAML block or the Agent Instructions below to change how all agents behave.\nChannels are listed on the channel page: `execution/channels.yaml`. How to run everything: `execution/execution.md`.\n\n```yaml\n# Gemini models for scripts and titles, tried in order (a busy or retired model falls through to the next)\nai_models: ["gemini-3.8-flash", "gemini-3.7-flash", "gemini-3.5-flash", "gemini-flash-latest"]\n# Free backups used when every Gemini model is out of quota or busy, tried in order. A provider whose key isn\'t set\n# (GROQ_API_KEY, OPENROUTER_API_KEY in .env and GitHub secrets) is skipped. Groq\'s free tier: about 1,000 requests a\n# day per model. Add {provider: "openrouter", models: ["<model>:free"]} for a second backup.\nai_fallbacks:\n  - provider: "groq"\n    models: ["openai/gpt-oss-120b", "qwen/qwen3.8-27b"]\n\n# GitHub starts scheduled runs late (4 to 5 hours in October 2026). The GitHub schedule fires this many minutes\n# BEFORE each fetch_time, so runs actually start near fetch_time. 0 = no shift. The Telegram start message says how\n# early or late each run started; adjust this if they drift.\ngithub_schedule_lead_minutes: 265\n# true when the GitHub repository is public (unlimited Actions minutes, so --check skips the minutes warning)\ngithub_repo_public: true\n\nstorage_paths:\n  base_dir: "./GDrive_Mount/YouTube_Automation"\n  tokens_dir: "./GDrive_Mount/YouTube_Automation/00_tokens"\n  branding_dir: "./GDrive_Mount/YouTube_Automation/00_branding"   # cached channel logos for the end card\n  manifest_file: "./GDrive_Mount/YouTube_Automation/01_manifests/trends.json"\n  raw_downloads: "./GDrive_Mount/YouTube_Automation/02_raw_videos"\n  audio_renders: "./GDrive_Mount/YouTube_Automation/02_audio_voiceovers"\n  processed_videos: "./GDrive_Mount/YouTube_Automation/03_edited_videos"\n  archive_dir: "./GDrive_Mount/YouTube_Automation/04_published_archive"\n\n# Runs on your laptop or IDE put video files here instead, one folder per day:\n#   YouTube_Auto/<YYYY-MM-DD>/download  (source videos)  and  /upload  (narration + final videos)\n# Day folders older than keep_days are deleted automatically. GitHub runs keep using storage_paths above.\nlocal_media:\n  enabled: true\n  root: "H:/My Drive/YouTube_Auto"   # your Google Drive (Drive for Desktop); "~/YouTube_Auto" = your user folder instead\n  keep_days: 2\n\n# Where each video\'s pictures come from:\n#   "stock"   = free stock clips matching the topic (works everywhere, including GitHub)\n#   "youtube" = re-use the trending video itself (laptop only: YouTube blocks downloads from cloud servers)\nfootage:\n  source: "stock"\n  provider: "auto"        # "pixabay" | "pexels" | "auto" (whichever key is set: PIXABAY_API_KEY, then PEXELS_API_KEY)\n  clips_per_video: 6            # scenes per Short (a new clip about every 5 to 6 seconds)\n  long_scene_seconds: 8         # long videos change clip about this often (was 15: too slow to hold attention)\n\nediting_rules:\n  zoom_factor: 1.06\n  original_audio_volume: 0      # 0 = only the AI voice is heard; 0.05 = original sound faintly underneath\n  watermark_fontsize: 36\n  watermark_color: "white"\n  watermark_opacity: 0.75\n  audio_mastering:              # Audio leveling standards calibrated 2026-10-31\n    target_mean_loudness_db: -20.0 # the level the values below were tuned to (FFmpeg volumedetect); not read by the code\n    hero_volume_factor: 0.28    # Attenuate raw 0 dBFS (-9.1 dB) intro/outro hero clips to match narration\n    voiceover_volume: 1.15      # Narration speech track boost in amix (yields -20.5 dB speech mean)\n    amix_normalize: 0           # MUST be 0 to prevent amix dividing speech volume by input count\n    bgm_volume: 0.12            # Ducked background music under narration (1.5s fade-in, 2.0s fade-out)\n    sfx_volume: 0.35            # cartoon sound effects (assets/audio/kids_sfx) at the script\'s [BOING] / [TADA] tags\n  mascot:                       # the WonderSprout superhero host, for channels with mascot: "wondersprout" (channels.yaml)\n    intro_long: true            # long videos open with her flying in and saying intro_line (about 5 s)\n    intro_shorts: true          # Shorts: her intro video (intro_short.mp4 or intro.mp4, ~7.6 s) plays first; false = she swoops into her corner instead\n    host: true                  # in a corner throughout, expressions following the script, mouth moving with the voice\n    outro: true                 # she says outro_line, waves and flies away before the LIKE / SUBSCRIBE card (about 5 s)\n    intro_line: "Hey kids! This is Wonder Sprout, your fun and learning superhero!"\n    outro_line: "Wonder Sprout signing off, kids! We\'ll meet next time!"\n  end_card:                     # closing card on every video: channel name, LIKE first, then SUBSCRIBE\n    enabled: true\n    seconds: 3\n    show_logo: false            # true = also show the channel\'s logo above the name\n    like_text: "LIKE"\n    subscribe_text: "SUBSCRIBE"\n\nupload_rules:\n  privacy_status: "public" # Default when a channel has no privacy_status of its own\n  synthetic_media_disclosure: true\n\ncleanup_rules:                  # GitHub runs; laptop runs keep files in YouTube_Auto day folders instead\n  delete_raw_after_publish: true\n  delete_voiceover_after_publish: true\n  delete_edited_after_publish: true\n  delete_edited_from_previous_dates: true\n```\n\n## PIPELINE ARCHITECTURE\n(Reference for people. This section is NOT sent to the AI; only the AGENT INSTRUCTIONS below are.)\n\n### Where everything is decided\n| File | Decides |\n|---|---|\n| `execution/channels.yaml` | Who each channel is: name, link, made for kids, watermark, category |\n| `execution/questions.yaml` | What and when each channel posts: genre, searches, language, voice, Shorts schedule, long videos, footage style |\n| `execution/view_techniques.md` | What gets views: its ACTIVE RULES are added to the AI instructions below for every video; it also logs every analysed source video (`--learn` or a link posted in Telegram) |\n| `execution/video_requests.json` | Videos the owner asked for in Telegram (a shared example or a topic); written by the Telegram inbox (`agents/inbox.py`), made by each channel\'s next run |\n| `BRAIN.md` (this file) | Rules shared by all channels: AI models and the free backup AI (`ai_fallbacks`, Groq), storage, footage source, editing and end card, upload and cleanup, AI writing instructions |\n| `.github/workflows/daily_youtube_agents.yml` | When GitHub runs (generated from each channel\'s `fetch_time` by `execution.py --check`, firing `github_schedule_lead_minutes` early because GitHub starts scheduled runs hours late) |\n| `.github/workflows/telegram_inbox.yml` | Hourly: reads the owner\'s Telegram posts (`execution.py --inbox`) and commits adopted rules and queued requests |\n| `execution/execution.py` | The only entry point; reads the three files above and runs the agents |\n\n### What one run does, in order\n1. **Choose channels**: a scheduled run picks the channels whose `fetch_time` (one time or a list) matches; a manual run uses the channel typed in. With several fetch times a day, each run makes only the videos whose go-live times fall before the channel\'s next run.\n2. **Clear lost work**: unfinished videos whose files are gone (an interrupted earlier run) are marked `expired`.\n3. **Long videos first, then Shorts.** For each format:\n   1. **Agent 1, Scout**: searches YouTube for trending videos on the channel\'s search phrases (Shorts topics from Shorts, long topics from 4 to 20 minute videos), ranks them by views per hour, skips other-language sources, uses the best-performing phrases first (from Agent 8) and rotates source channels. The owner\'s Telegram requests for this channel and format are made first (in normal slots), and their search phrases are searched first for 7 days. It also collects the search phrases people type (YouTube autocomplete, rising videos\' keyword tags).\n   2. **Agent 3, Script & Voice**: Gemini (or, when every Gemini model is out of quota or busy, the backup AI: Groq) writes an original script for the topic (following the owner\'s notes for a requested video), and in the same request the main search keyword (from the real search phrases; it leads the title and the first description sentence) and related phrases, the upload title, description, hashtags and footage terms (hook first; long videos get 3 to 5 parts and a recap). The voice narrates it sentence by sentence with varied pitch, speed and volume (`voice_expression`: lively for kids, measured for news; `agents/expressive_voice.py`), sentence timings are recorded, and if the narration runs longer than allowed the script is shortened and narrated again. The narration is split into scenes (about `clips_per_video` per Short, one every `long_scene_seconds` in long videos).\n   3. **Agent 2, Footage**: a specific and a backup search term for each scene (for Shorts, written in the script request; for long videos, the AI reads each scene\'s words in a second request); with `footage_style: "real"` (Frontline) the specific term is first looked up as real footage of the actual people and events on Wikimedia Commons (public domain, CC0 or CC BY only; only the needed seconds are fetched), then as a real photo of them (shown whole with a slow zoom), otherwise one stock clip per scene comes from Pixabay (or Pexels), keeping only clips whose tags match the scene\'s subject (style words like "cartoon" don\'t count); on kids channels a matching Pixabay cartoon illustration (slow zoom) is used when no video matches.\n   4. **Agent 4, Editor**: on channels with `mascot: "wondersprout"`, adds the superhero host (`agents/mascot.py`; her art in `assets/wondersprout/` replaces the drawn version): a voiced flying intro for long videos (`intro_line`), the host in a corner with expressions following the sentence timings and her mouth following the voice, and a voiced fly-off outro (`outro_line`) before the end card; kids channels also get quiet background music and the script\'s `[SOUND]` tags as cartoon sound effects, with the intro and outro levelled to the narration (`audio_mastering`). FFmpeg cuts each clip to its scene\'s narration time, fits it to 1080x1920 (Short) or 1920x1080 (long; real footage in Shorts is shown whole on a blurred copy of itself), joins them, adds the watermark and narration (no original audio), and appends the LIKE then SUBSCRIBE end card.\n   5. **Agent 5, Publisher**: confirms the YouTube login is the right channel, uses the title and description written with the script (the source video\'s title if no AI was available), adds up to 12 hashtags (first the niche\'s currently trending hashtags from the Scout\'s rising videos and the strongest topic hashtag, then `#shorts`, the AI\'s topic hashtags and the source video\'s; also used as search tags), hidden search tags led by the video\'s search keyword and real search phrases that fit it, and the credits for real Commons footage (author, licence and link; no Pixabay or music credits), and uploads in resumable chunks with its go-live time (Shorts: `short_post_times`, or `first_post_time` then every `post_frequency`; long: `long_post_times`; a time already passed goes live soon after upload). It uploads only as many videos as the run has go-live times; extra finished videos wait for the next run.\n4. **Agent 6, Cleanup**: deletes files no longer needed (GitHub) or day folders older than `keep_days` (laptop).\n5. **Agent 7, Telegram**: a "run started" message (with how early or late GitHub started it), then one message per channel with each uploaded video\'s title, link, go-live time, search keyword and hashtags (📌 for a requested video), and how many failed.\n6. **Agent 8, Analyst** (after all channels): saves each recent upload\'s views, scores search phrases by views after 48 hours, and sends a daily Telegram report.\n7. **Between runs, Telegram inbox** (hourly workflow): the owner\'s posts in the alerts channel. A YouTube link is watched by Gemini: advice becomes proposed rules (`approve S5` adds them to ACTIVE RULES), a liked video is queued for a video like it; typed requests are queued too.\n8. **Result**: the log ends with each channel\'s uploads out of planned. A channel that uploaded nothing marks the GitHub run failed (red); one that uploaded some but not all adds a yellow warning to a green run.\n\n### Video status flow (in the manifest, `01_manifests/trends.json`)\n`discovered` → `voiced` → `ready_to_edit` → `edited` → `published`\n(`download_failed` or `expired` when a step can\'t be completed; re-used trending videos use `discovered` → `downloaded` → `voiced` → `edited` → `published`.)\n\n## AGENT INSTRUCTIONS\n* **Agent 1 (Scout):** Prioritize high-velocity Short videos. Store clean metadata in human-readable JSON.\n* **Agent 3 (Script & Voice):** Write a transformative commentary script on the trending topic, sized to the channel\'s `target_duration_seconds`, in the channel\'s language and tone. Short, clear sentences that read naturally aloud. **Open with a hook in the first sentence (first 3 seconds)**: a surprising fact, a bold question, or a "you won\'t believe" moment that makes the viewer keep watching, then pay it off before the end. For news and war channels, strictly avoid graphic or violent terms so the video remains advertiser-friendly; use strategic terminology ("escalating tensions", "frontline shifts", "defense posture"). Name the countries, places and public figures involved (heads of state, ministers and other government representatives), describing their public actions and statements factually, without insults or unproven claims. For kids channels (ages 4 to 9), write as an enthusiastic, joyful game-show host (WonderSprout, "I") talking straight to the kids watching, making it FUN first, highly interactive and educational:\n  - **Hook in the first sentence:** A mysterious or mind-blowing challenge ("Whoa! Can you guess which crazy animal can sleep for THREE whole years?", "Whoa! Look at this creature with giant glowing eyes!"). Never a dry "Today we will learn".\n  - **Sound Effect Cue Tags:** You MUST include sound effect cues in square brackets in the script: `[BOING]`, `[POP]`, `[DING]`, `[CHEER]`, `[TICK]`, `[TADA]`, `[WHOOSH]`, `[SPLASH]` right where the action or sound occurs. These trigger real cartoon sound effects; use only these tags, and never write any other words in square brackets.\n  - **Visual Realism (CRITICAL FOR FOOTAGE MATCHING):** Never write about imaginary cartoon animals wearing human clothes or doing human jobs (no bunnies wearing diamond hats, no pigs at beauty salons). Always describe REAL creatures, real animal habits, real habitats, ocean giants, dinosaurs, and amazing animal superpowers (e.g. cheetah sprinting fast, chameleon changing color, baby elephant splashing in mud, octopus squirting ink, eagle soaring high). Real subjects are what stock footage can actually show. Everything is original: never Peppa Pig, Disney or other copyrighted characters, shows or songs.\n  - **Long Videos (5 to 7 minutes - The 5-Round Game Show Format):** Long videos must NEVER be a single slow monologue. Structure every 5 to 7 minute video into **5 Fast-Paced Interactive Rounds** (~60 to 75 seconds each):\n    - *Intro (15s):* WonderSprout announces the challenge: "Hey kids! Welcome to the Mega Animal Mystery Show! We have 5 wild rounds today! Can you get all 5? Let\'s find out! Round 1!"\n    - *Round 1 to Round 5:* Each round gives 2 exciting clues, prompts the viewer to shout their guess ("What is it? Guess in 3... 2... 1... [TICK] [TICK] [TICK]!"), reveals the answer with celebration ("It\'s the mighty blue whale! [TADA] [CHEER]"), and shares one mind-blowing superpower fact with a sound cue (`[DING]`).\n    - *Transition between rounds:* Quick energetic bridge ("Awesome job! Give yourself a high-five! Are you ready for Round 2? Here we go! [WHOOSH]").\n    - *Outro (20s):* Celebration `[CHEER]`, high-fives, and asking them to comment their final score ("How many rounds did you guess right? Tell me in the comments below!").\n  - **Shorts (the channel\'s Short length):** A single rapid-fire mystery or crazy superpower with a 3-second countdown ("Guess what animal has BLUE blood! 3.. 2.. 1.. [TICK] [TADA] It\'s an octopus!").\n  - Simple, punchy words, sentences of 5 to 10 words, lots of "!" and "?" so the expressive voice jumps with excitement.\n* **Agent 4 (Editor):** Apply a 1.06x crop zoom, remove the original audio completely (original_audio_volume 0), keep the volume even across intro, narration and outro (`audio_mastering`), overlay the channel watermark in the bottom-right corner, and end every video with the end card (channel name, LIKE first, then SUBSCRIBE).\n* **Agent 5 (Publisher):** Generate a high-CTR title under 65 characters for Shorts (70 for long videos) that matches what the script actually says, with no clickbait the video doesn\'t pay off. Keep the description to the requested sentences with no credits, links or source names: the pipeline adds the Commons footage credit itself. Hashtags have no spaces, never use the `@` symbol, and never name other YouTube channels.\n',
    'orchestrator.py': '"""Runs agents 1 to 7 in order for one channel. Started by execution/execution.py, not run directly."""\nimport copy\nimport json\nimport os\nimport sys\n\nif hasattr(sys.stdout, "reconfigure"):\n    try:\n        sys.stdout.reconfigure(encoding="utf-8", errors="replace")\n    except Exception:\n        pass\n\nfrom agents.agent_1_scout import TrendScoutAgent\nfrom agents.agent_2_downloader import DownloaderAgent\nfrom agents.agent_3_voiceover import VoiceoverAgent, stock_mode\nfrom agents.agent_4_editor import VideoEditorAgent\nfrom agents.agent_5_publisher import PublisherAgent\nfrom agents.agent_6_cleanup import CleanupAgent, expire_missing_files\nfrom agents.agent_7_notifier import TelegramNotifierAgent\nfrom brain import item_matches\n\n# Footage can\'t always be found (no matching stock clips, or a restricted video), so look again a few times\nFIND_ATTEMPTS = 3\n# Long videos are prepared first, so they are certainly ready well before their go-live times\nFORMATS = ("long", "short")\n\n\ndef format_profile(profile, fmt):\n    """The channel\'s settings for one format: Shorts as answered, or the long-video answers (Q22 to Q24)."""\n    settings = copy.deepcopy(profile)\n    settings["format"] = fmt\n    if fmt == "long":\n        settings["max_videos_per_run"] = profile["long"]["count"]\n        settings["publish_plan"] = profile.get("long_publish_plan")\n    return settings\n\n\nclass OrchestratorAgent:\n    def __init__(self, config, instructions):\n        self.config = config\n        self.instructions = instructions\n        self.setup_directories()\n\n    def setup_directories(self):\n        paths = self.config["storage_paths"]\n        os.makedirs(os.path.dirname(paths["manifest_file"]), exist_ok=True)\n        os.makedirs(paths["raw_downloads"], exist_ok=True)\n        os.makedirs(paths["audio_renders"], exist_ok=True)\n        os.makedirs(paths["processed_videos"], exist_ok=True)\n        os.makedirs(paths["archive_dir"], exist_ok=True)\n        os.makedirs(paths["tokens_dir"], exist_ok=True)\n\n    def manifest_items(self, channel_key, profile=None):\n        path = self.config["storage_paths"]["manifest_file"]\n        if not os.path.exists(path):\n            return []\n        with open(path, "r", encoding="utf-8") as f:\n            items = json.load(f)\n        if profile is None:\n            return [item for item in items if item.get("profile") == channel_key]\n        return [item for item in items if item_matches(item, channel_key, profile)]\n\n    def expire_unfinishable(self, channel_key):\n        """Before counting today\'s videos, drop half-finished ones whose files were lost (e.g. a fresh GitHub run)."""\n        path = self.config["storage_paths"]["manifest_file"]\n        if not os.path.exists(path):\n            return\n        with open(path, "r", encoding="utf-8") as f:\n            items = json.load(f)\n        expired = expire_missing_files([i for i in items if i.get("profile") == channel_key])\n        if expired:\n            print(f"[Orchestrator] {expired} unfinished video(s) from an earlier run lost their files; "\n                  "marked expired so new ones are made instead.")\n            with open(path, "w", encoding="utf-8") as f:\n                json.dump(items, f, indent=4, ensure_ascii=False)\n\n    def run_format(self, config, channel_key, dry_run):\n        """Find footage, narrate, edit and (unless a test run) upload one format\'s videos."""\n        profile = config["profiles"][channel_key]\n        paths = config["storage_paths"]\n        wanted = profile["max_videos_per_run"]\n        print(f"\\n---------- {channel_key}: {wanted} {profile[\'format\']} video(s) ----------")\n\n        self.expire_unfinishable(channel_key)\n        scout = TrendScoutAgent(config, self.instructions)\n        downloader = DownloaderAgent(paths["manifest_file"], paths["raw_downloads"], config)\n        voiceover = VoiceoverAgent(config, self.instructions)\n        if stock_mode(config, profile):\n            # Stock footage: write and narrate the script first, then fetch a clip that matches each scene\n            ready_statuses, in_progress = ("ready_to_edit", "edited"), ("discovered", "voiced")\n            steps = [voiceover.run, lambda: downloader.run(channel_key)]\n        else:\n            # Re-used trending video: download it first, then narrate\n            ready_statuses, in_progress = ("downloaded", "voiced", "edited"), ("discovered",)\n            steps = [lambda: downloader.run(channel_key), voiceover.run]\n\n        for attempt in range(FIND_ATTEMPTS):\n            items = self.manifest_items(channel_key, profile)\n            ready = sum(1 for i in items if i["status"] in ready_statuses)\n            pending = sum(1 for i in items if i["status"] in in_progress)\n            if ready >= wanted:\n                break\n            if attempt:\n                print(f"\\n[Orchestrator] {ready} of {wanted} video(s) ready; looking for more (attempt {attempt + 1}).")\n            if ready + pending < wanted:\n                scout.run(limit=wanted - ready - pending)\n            for step in steps:\n                step()\n\n        VideoEditorAgent(config).run()\n        if not dry_run:\n            PublisherAgent(config, self.instructions).run()\n\n    def execute_pipeline(self, channel_key, dry_run=False, formats=FORMATS, planned=None):\n        """Run every agent for one channel (long videos, then Shorts) and return the number of videos uploaded."""\n        base = self.config["profiles"][channel_key]\n        published_before = {i["video_id"] for i in self.manifest_items(channel_key) if i["status"] == "published"}\n        print("====================================================")\n        print(f" ORCHESTRATOR STARTED | CHANNEL: {channel_key}" + (" | TEST RUN" if dry_run else ""))\n        print("====================================================")\n\n        for fmt in formats:\n            if (fmt == "long" and not base["long"]["count"]) or (fmt == "short" and not base["max_videos_per_run"]):\n                continue\n            config = copy.deepcopy(self.config)\n            config["active_profile"] = channel_key\n            config["profiles"][channel_key] = format_profile(base, fmt)\n            self.run_format(config, channel_key, dry_run)\n\n        if dry_run:\n            print("\\n[Test run] Skipping upload, cleanup and Telegram alert.")\n            print(f"[Test run] Finished videos are in: {self.config[\'storage_paths\'][\'processed_videos\']}")\n            return 0\n\n        config = copy.deepcopy(self.config)\n        config["active_profile"] = channel_key\n        CleanupAgent(config).run()\n        uploaded = [i for i in self.manifest_items(channel_key)\n                    if i["status"] == "published" and i["video_id"] not in published_before]\n        TelegramNotifierAgent(config).run(uploaded, planned)\n\n        print("\\n====================================================")\n        print(f" {channel_key}: {len(uploaded)} video(s) uploaded")\n        for item in uploaded:\n            link = "shorts/" if item.get("format", "short") == "short" else "watch?v="\n            print(f"   https://youtube.com/{link}{item.get(\'uploaded_youtube_id\')}  ({item.get(\'format\', \'short\')})")\n        print("====================================================")\n        return len(uploaded)\n',
    'brain.py': '"""Loads BRAIN.md (global rules), execution/channels.yaml (who each channel is) and\nexecution/questions.yaml (what and when each channel posts), and works out GitHub schedules."""\nimport os\nimport re\nfrom datetime import datetime, time, timedelta, timezone\nfrom zoneinfo import ZoneInfo, ZoneInfoNotFoundError\n\nimport yaml\n\nPROJECT_DIR = os.path.dirname(os.path.abspath(__file__))\nBRAIN_FILE = os.path.join(PROJECT_DIR, "BRAIN.md")\nCHANNELS_FILE = os.path.join(PROJECT_DIR, "execution", "channels.yaml")\nQUESTIONS_FILE = os.path.join(PROJECT_DIR, "execution", "questions.yaml")\nVIEW_TECHNIQUES_FILE = os.path.join(PROJECT_DIR, "execution", "view_techniques.md")\n\nDAY_NAMES = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]\nDEFAULT_TIMEZONE = "Asia/Kolkata"\n\nFREQUENCIES = {"15 mins": 15, "30 mins": 30, "1 hour": 60, "3 hours": 180}\nLANGUAGES = {"English": "en-", "Hindi": "hi-", "Telugu": "te-"}\nDEFAULT_VOICES = {\n    # (language, made_for_kids) -> voice\n    ("English", False): "en-US-AndrewNeural",\n    ("English", True): "en-US-AnaNeural",\n    ("Hindi", False): "hi-IN-MadhurNeural",\n    ("Hindi", True): "hi-IN-SwaraNeural",\n    ("Telugu", False): "te-IN-MohanNeural",\n    ("Telugu", True): "te-IN-ShrutiNeural",\n}\nSPEEDS = ["-15%", "-5%", "+0%", "+10%"]\nVOICE_EXPRESSIONS = ["lively", "measured", "off"]\nMASCOTS = ["wondersprout"]\nVIDEO_LENGTHS = [15, 30, 45, 60]\nVISIBILITIES = ["public", "unlisted", "private"]\nFOOTAGE_STYLES = ["any", "animation", "film", "mixed", "real"]\nLONG_MINUTES = [4, 5, 6, 7, "4-5", "4-6", "5-6", "5-7", "6-7"]\nMAX_LONG_VIDEOS_PER_DAY = 4\nMAX_VIDEOS_PER_DAY = 50\n# Upload videos, and read which channel a login belongs to (checked before every upload)\nYOUTUBE_SCOPES = [\n    "https://www.googleapis.com/auth/youtube.upload",\n    "https://www.googleapis.com/auth/youtube.readonly",\n]\n\n\n# ---------- loading ----------\n\ndef load_brain(brain_file=BRAIN_FILE, channels_file=CHANNELS_FILE, questions_file=QUESTIONS_FILE):\n    with open(brain_file, "r", encoding="utf-8") as f:\n        raw_md = f.read()\n\n    fence = "`" * 3\n    yaml_match = re.search(fence + r"yaml\\n(.*?)\\n" + fence, raw_md, re.DOTALL)\n    if not yaml_match:\n        raise ValueError("Invalid BRAIN.md: Missing yaml configuration block.")\n\n    config = yaml.safe_load(yaml_match.group(1))\n    instructions = raw_md.split("## AGENT INSTRUCTIONS")[-1].strip()\n    rules = view_rules()\n    if rules:\n        instructions += "\\n\\n## VIEW-GROWTH RULES (apply to every script, title and hashtag)\\n" + rules\n    config["profiles"] = load_profiles(channels_file, questions_file)\n    lead = int(config.get("github_schedule_lead_minutes") or 0)\n    for profile in config["profiles"].values():\n        profile["schedule"]["lead_minutes"] = lead\n    apply_media_folders(config)\n    return config, instructions\n\n\ndef view_rules(path=VIEW_TECHNIQUES_FILE):\n    """The ACTIVE RULES section of execution/view_techniques.md, without the [S1]-style source tags."""\n    if not os.path.exists(path):\n        return ""\n    with open(path, "r", encoding="utf-8") as f:\n        text = f.read()\n    section = re.search(r"^## ACTIVE RULES\\s*\\n(.*?)(?=^## |\\Z)", text, re.DOTALL | re.MULTILINE)\n    return re.sub(r"\\s*\\[S\\d+(?:,\\s*S\\d+)*\\]", "", section.group(1)).strip() if section else ""\n\n\ndef apply_media_folders(config):\n    """Local runs keep video files in <root>/<YYYY-MM-DD>/download and /upload, so whole days are easy to delete.\n\n    GitHub runs store nothing between runs, so they keep the storage_paths folders from BRAIN.md.\n    """\n    media = config.get("local_media") or {}\n    if os.getenv("GITHUB_ACTIONS") == "true" or not media.get("enabled", True):\n        config["storage_mode"] = "cloud"\n        return\n    root = os.path.normpath(os.path.expanduser(media.get("root", "~/YouTube_Auto")))\n    if not os.path.isdir(os.path.splitdrive(root)[0] + os.sep):\n        # e.g. Google Drive for Desktop isn\'t running, so its drive letter is missing\n        fallback = os.path.normpath(os.path.expanduser("~/YouTube_Auto"))\n        print(f"[Storage] {root} isn\'t available; using {fallback} for video files this run.")\n        root = fallback\n    day = os.path.join(root, datetime.now().strftime("%Y-%m-%d"))\n    paths = config["storage_paths"]\n    paths["raw_downloads"] = os.path.join(day, "download")\n    paths["audio_renders"] = os.path.join(day, "upload")\n    paths["processed_videos"] = os.path.join(day, "upload")\n    config["storage_mode"] = "local"\n    config["media_root"] = root\n\n\ndef read_section(path, section):\n    with open(path, "r", encoding="utf-8") as f:\n        return (yaml.safe_load(f) or {}).get(section) or {}\n\n\ndef load_profiles(channels_file=CHANNELS_FILE, questions_file=QUESTIONS_FILE):\n    channels = read_section(channels_file, "channels")\n    answers = read_section(questions_file, "channels")\n\n    problems = validate_channels(channels) + validate_answers(answers, channels)\n    if problems:\n        raise ValueError("Please fix these problems:\\n  - " + "\\n  - ".join(problems))\n\n    return {key: build_profile(channels[key], answers.get(key)) for key in channels}\n\n\ndef fetch_times(answers):\n    """Q12 fetch_time as a list: one "HH:MM", or a list of them for several runs a day."""\n    value = answers.get("fetch_time")\n    if value in (None, "", []):\n        return []\n    return list(value) if isinstance(value, list) else [value]\n\n\ndef build_profile(channel, answers):\n    """Combine a channel\'s identity with its answers into the settings the agents use."""\n    kids = bool(channel["made_for_kids"])\n    a = answers or {}\n    language = a.get("language") or "English"\n    genre = a.get("genre") or channel["channel_name"]\n\n    return {\n        # From the channel page\n        "channel_name": channel["channel_name"],\n        "channel_url": channel["channel_url"],\n        "made_for_kids": kids,\n        "watermark_text": channel.get("watermark_text") or "@" + re.sub(r"[^A-Za-z0-9]", "", channel["channel_name"]),\n        "category_id": str(channel.get("category_id") or ("27" if kids else "24")),\n        "logo_file": channel.get("logo_file"),\n        # A superhero host drawn into the videos (agents/mascot.py); kids channels only\n        "mascot": channel.get("mascot"),\n        # From the questions file\n        "has_answers": answers is not None,\n        "enabled": answers is not None and a.get("run", True) is not False,\n        "niche": genre,\n        "search_queries": a.get("search_phrases") or [f"{genre} #shorts"],\n        "language": language,\n        "voice": a.get("voice") or DEFAULT_VOICES[(language, kids)],\n        "voice_rate": a.get("voice_speed") or ("-15%" if kids else "-5%"),\n        # Sentence-by-sentence pitch, speed and volume (agents/expressive_voice.py)\n        "voice_expression": a.get("voice_expression") or ("lively" if kids else "measured"),\n        "tone": a.get("tone") or ("Enthusiastic, warm, curious storyteller for young children." if kids\n                                  else "Clear, engaging and informative."),\n        "target_duration_seconds": int(a.get("video_length_seconds") or 30),\n        "avoid_terms": a.get("avoid_words") or [],\n        "lookback_days": int(a.get("lookback_days") or 5),\n        # Day total of Shorts: one per short_post_times entry when given, else videos_per_day\n        "max_videos_per_run": len(a.get("short_post_times") or []) or int(a.get("videos_per_day") or 1),\n        "privacy_status": a.get("visibility") or "public",\n        "test_run": bool(a.get("test_run", False)),\n        "exclude_sources": a.get("exclude_sources") or [],\n        "footage_style": a.get("footage_style") or "any",\n        "schedule": {\n            "timezone": a.get("timezone") or DEFAULT_TIMEZONE,\n            # One run per fetch time; the day\'s videos are shared between the runs (see run_window)\n            "post_times": fetch_times(a),\n            "days": a.get("days") or "daily",\n        },\n        "posting": {\n            # Exact go-live times (short_post_times), or first_post_time then every post_frequency\n            "post_times": list(a.get("short_post_times") or []),\n            "first_post_time": a.get("first_post_time"),\n            "frequency_minutes": FREQUENCIES.get(a.get("post_frequency") or "1 hour", 60),\n        },\n        # Long (landscape, 5 to 7 minute) videos, prepared in the same run as the Shorts\n        "long": {\n            "count": int(a.get("long_videos_per_day") or 0),\n            "minutes": a.get("long_video_minutes") or 6,\n            "post_times": [str(t) for t in (a.get("long_post_times") or [])],\n        },\n    }\n\n\n# ---------- validation ----------\n\ndef validate_channels(channels):\n    if not channels:\n        return ["channels.yaml: no channels listed under \'channels:\'."]\n    problems = []\n    for key, details in channels.items():\n        where = f"channels.yaml \'{key}\'"\n        if not re.fullmatch(r"[a-z][a-z0-9_]{1,40}", str(key)):\n            problems.append(f"{where}: key must be lowercase letters, numbers and underscores, starting with a letter")\n        if not isinstance(details, dict):\n            problems.append(f"{where}: details must be indented under the key")\n            continue\n        for field in ("channel_name", "channel_url", "made_for_kids"):\n            if details.get(field) in (None, ""):\n                problems.append(f"{where}: missing required field \'{field}\'")\n        if details.get("mascot") not in (None, *MASCOTS):\n            problems.append(f"{where}: mascot must be one of {\', \'.join(MASCOTS)}, or left out")\n        elif details.get("mascot") and not details.get("made_for_kids"):\n            problems.append(f"{where}: the mascot is for kids channels only (made_for_kids: true)")\n        if details.get("channel_url") and not parse_channel_url(details["channel_url"]):\n            problems.append(f"{where}: channel_url must look like https://www.youtube.com/@handle "\n                            "or https://www.youtube.com/channel/UC...")\n    return problems\n\n\ndef item_matches(item, channel_key, profile):\n    """True if a manifest item belongs to this channel and to the format (short or long) being processed."""\n    return item.get("profile") == channel_key and item.get("format", "short") == profile.get("format", "short")\n\n\ndef parse_channel_url(url):\n    """Return ("handle", "@name") or ("id", "UC...") from a YouTube channel link, or None if unrecognised."""\n    match = re.search(r"youtube\\.com/(@[\\w.\\-]+)", str(url))\n    if match:\n        return "handle", match.group(1).lower()\n    match = re.search(r"youtube\\.com/channel/(UC[\\w\\-]{22})", str(url))\n    if match:\n        return "id", match.group(1)\n    return None\n\n\ndef channel_matches(url, channel_id, custom_url):\n    """True if the signed-in channel (its ID and @handle from the YouTube API) is the one the link points to."""\n    kind, value = parse_channel_url(url)\n    if kind == "id":\n        return channel_id == value\n    return (custom_url or "").lower() == value\n\n\ndef validate_answers(answers, channels):\n    problems = []\n    for key, a in answers.items():\n        where = f"questions.yaml \'{key}\'"\n        if key not in channels:\n            problems.append(f"{where}: no channel with this key in channels.yaml")\n            continue\n        if not isinstance(a, dict):\n            problems.append(f"{where}: answers must be indented under the channel key")\n            continue\n\n        language = a.get("language", "English")\n        if language not in LANGUAGES:\n            problems.append(f"{where}: language must be one of {\', \'.join(LANGUAGES)}")\n        voice = a.get("voice")\n        if voice:\n            if not re.fullmatch(r"[a-z]{2,3}-[A-Z]{2,4}-\\w+Neural", str(voice)):\n                problems.append(f"{where}: voice \'{voice}\' should look like en-US-AndrewNeural")\n            elif language in LANGUAGES and not str(voice).startswith(LANGUAGES[language]):\n                problems.append(f"{where}: voice \'{voice}\' does not speak {language}; pick a {LANGUAGES[language]}... voice")\n        checks = [\n            ("voice_speed", SPEEDS), ("voice_expression", VOICE_EXPRESSIONS), ("video_length_seconds", VIDEO_LENGTHS),\n            ("post_frequency", list(FREQUENCIES)), ("visibility", VISIBILITIES), ("footage_style", FOOTAGE_STYLES),\n        ]\n        for field, allowed in checks:\n            if a.get(field) is not None and a[field] not in allowed:\n                problems.append(f"{where}: {field} must be one of {\', \'.join(str(x) for x in allowed)}")\n        for field in ("search_phrases", "avoid_words", "exclude_sources"):\n            value = a.get(field)\n            if value is not None and not (isinstance(value, list) and all(isinstance(v, str) for v in value)):\n                problems.append(f\'{where}: {field} must be a list in quotes, e.g. ["one", "two"] or []\')\n        videos = a.get("videos_per_day")\n        if videos is not None and not (isinstance(videos, int) and 1 <= videos <= MAX_VIDEOS_PER_DAY):\n            problems.append(f"{where}: videos_per_day must be a whole number from 1 to {MAX_VIDEOS_PER_DAY}")\n        long_count = a.get("long_videos_per_day")\n        if long_count is not None and not (isinstance(long_count, int) and 0 <= long_count <= MAX_LONG_VIDEOS_PER_DAY):\n            problems.append(f"{where}: long_videos_per_day must be a whole number from 0 to {MAX_LONG_VIDEOS_PER_DAY}")\n        if a.get("long_video_minutes") is not None and a["long_video_minutes"] not in LONG_MINUTES:\n            problems.append(f\'{where}: long_video_minutes must be one of 4, 5, 6, 7, "4-5", "4-6", "5-6", "5-7" \'\n                            \'or "6-7"\')\n        long_times = a.get("long_post_times") or []\n        if not isinstance(long_times, list):\n            problems.append(f\'{where}: long_post_times must be a list, e.g. ["13:00", "19:00"]\')\n            long_times = []\n        short_times = a.get("short_post_times") or []\n        if not isinstance(short_times, list):\n            problems.append(f\'{where}: short_post_times must be a list, e.g. ["08:00", "10:00"]\')\n            short_times = []\n        if len(short_times) > MAX_VIDEOS_PER_DAY:\n            problems.append(f"{where}: short_post_times can list at most {MAX_VIDEOS_PER_DAY} times")\n        for label, times_list in (("long", long_times), ("short", short_times)):\n            for t in times_list:\n                try:\n                    parse_time(t)\n                except (ValueError, AttributeError):\n                    problems.append(f"{where}: {label} post time \'{t}\' must be HH:MM in 24-hour format, in quotes")\n        if isinstance(long_count, int) and long_count > len(long_times):\n            problems.append(f"{where}: give one long_post_times entry per long video "\n                            f"({long_count} needed, {len(long_times)} given)")\n        lookback = a.get("lookback_days")\n        if lookback is not None and not (isinstance(lookback, int) and 1 <= lookback <= 30):\n            problems.append(f"{where}: lookback_days must be a whole number from 1 to 30")\n        times = [("fetch_time", t) for t in fetch_times(a)]\n        if a.get("first_post_time") is not None:\n            times.append(("first_post_time", a["first_post_time"]))\n        for field, value in times:\n            try:\n                parse_time(value)\n            except (ValueError, AttributeError):\n                problems.append(f"{where}: {field} \'{value}\' must be HH:MM in 24-hour format, in quotes")\n        try:\n            if len({parse_time(t) for t in fetch_times(a)}) < len(fetch_times(a)):\n                problems.append(f"{where}: fetch_time lists the same time twice")\n        except (ValueError, AttributeError):\n            pass\n        try:\n            ZoneInfo(a.get("timezone") or DEFAULT_TIMEZONE)\n        except (ZoneInfoNotFoundError, ValueError):\n            problems.append(f"{where}: unknown timezone \'{a.get(\'timezone\')}\'")\n        try:\n            parse_days(a.get("days") or "daily")\n        except ValueError:\n            problems.append(f"{where}: days must be daily, weekdays, weekends or a list like [mon, wed, fri]")\n    return problems\n\n\n# ---------- time helpers ----------\n\ndef parse_time(value):\n    # YAML reads an unquoted 09:30 as the base-60 integer 570, so accept both forms\n    if isinstance(value, int):\n        return time(value // 60, value % 60)\n    hours, minutes = str(value).strip().split(":")\n    return time(int(hours), int(minutes))\n\n\ndef parse_days(value):\n    if value in (None, "daily", "everyday", "all"):\n        return list(range(7))\n    if value == "weekdays":\n        return list(range(5))\n    if value == "weekends":\n        return [5, 6]\n    if isinstance(value, str):\n        value = value.split(",")\n    return sorted({DAY_NAMES.index(str(day).strip().lower()[:3]) for day in value})\n\n\ndef cron_time(local_dt, schedule):\n    """When GitHub\'s schedule should fire (UTC) for a run meant to start at local_dt: lead_minutes earlier."""\n    return (local_dt - timedelta(minutes=schedule.get("lead_minutes") or 0)).astimezone(timezone.utc)\n\n\ndef utc_slots(profile, ref_date=None):\n    """Map each fetch time to its GitHub cron time as {(minute, hour): {cron weekdays}} (cron weekdays: 0 = Sunday)."""\n    schedule = profile.get("schedule") or {}\n    tz = ZoneInfo(schedule.get("timezone", DEFAULT_TIMEZONE))\n    ref = ref_date or datetime.now(tz).date()\n    slots = {}\n\n    for post_time in schedule.get("post_times") or []:\n        local_time = parse_time(post_time)\n        for weekday in parse_days(schedule.get("days", "daily")):\n            local_date = ref + timedelta(days=(weekday - ref.weekday()) % 7)\n            utc_dt = cron_time(datetime.combine(local_date, local_time, tzinfo=tz), schedule)\n            slots.setdefault((utc_dt.minute, utc_dt.hour), set()).add((utc_dt.weekday() + 1) % 7)\n\n    return slots\n\n\ndef format_cron_days(days):\n    return "*" if len(days) == 7 else ",".join(str(day) for day in sorted(days))\n\n\ndef cron_lines(config):\n    merged = {}\n    for profile in config["profiles"].values():\n        if not profile.get("enabled", True):\n            continue\n        for slot, days in utc_slots(profile).items():\n            merged.setdefault(slot, set()).update(days)\n\n    ordered = sorted(merged.items(), key=lambda item: (item[0][1], item[0][0]))\n    return [f"{minute} {hour} * * {format_cron_days(days)}" for (minute, hour), days in ordered]\n\n\ndef fetch_time_for_cron(profile, cron, ref_date=None):\n    """The channel\'s local fetch time that the GitHub cron ("minute hour ...", UTC) stands for, or None."""\n    minute, hour = (int(part) for part in cron.split()[:2])\n    schedule = profile.get("schedule") or {}\n    tz = ZoneInfo(schedule.get("timezone", DEFAULT_TIMEZONE))\n    ref = ref_date or datetime.now(tz).date()\n    for post_time in schedule.get("post_times") or []:\n        utc_dt = cron_time(datetime.combine(ref, parse_time(post_time), tzinfo=tz), schedule)\n        if (utc_dt.minute, utc_dt.hour) == (minute, hour):\n            return parse_time(post_time)\n    return None\n\n\ndef due_profiles(config, cron, now=None):\n    now = now or datetime.now(timezone.utc)\n    minute, hour = (int(part) for part in cron.split()[:2])\n\n    scheduled = now.replace(hour=hour, minute=minute, second=0, microsecond=0)\n    if scheduled > now:\n        # GitHub started the run late, after midnight UTC\n        scheduled -= timedelta(days=1)\n    cron_day = (scheduled.weekday() + 1) % 7\n\n    return [\n        key for key, profile in config["profiles"].items()\n        if profile.get("enabled", True) and cron_day in utc_slots(profile).get((minute, hour), set())\n    ]\n',
    'agents/__init__.py': '# Multi-Agent Package Initializer\n',
    'agents/ai.py': '"""Shared AI text generation: Gemini first (BRAIN.md ai_models), then free backup providers (ai_fallbacks).\n\nWhen every Gemini model is out of quota or busy, the same prompt goes to the backup providers in order, so a run\nkeeps making videos. Backups are OpenAI-compatible chat APIs; one whose key isn\'t set is skipped.\n"""\nimport os\nimport time\n\nimport requests\n\nDEFAULT_MODELS = ["gemini-3.8-flash", "gemini-3.7-flash", "gemini-3.5-flash", "gemini-flash-latest"]\n\n# Busy (503), rate-limited (429) or retired (404) models are skipped in favour of the next one;\n# dropped connections and timeouts are retried the same way\nRETRYABLE = ("503", "500", "429", "404", "UNAVAILABLE", "RESOURCE_EXHAUSTED", "NOT_FOUND", "INTERNAL",\n             "disconnected", "Connection", "timed out", "Timeout")\nQUOTA = ("429", "RESOURCE_EXHAUSTED")\n# Spacing between requests keeps a run under the per-minute request limit\nMIN_GAP_SECONDS = 4\n# Per-minute limits clear within a minute, so when every model is rate-limited wait once and try again\nQUOTA_WAIT_SECONDS = 65\n\n# OpenAI-compatible providers that can stand in for Gemini, and the key each needs\nPROVIDERS = {\n    "groq": {"url": "https://api.groq.com/openai/v1/chat/completions", "env": "GROQ_API_KEY"},\n    "openrouter": {"url": "https://openrouter.ai/api/v1/chat/completions", "env": "OPENROUTER_API_KEY"},\n}\nDEFAULT_FALLBACKS = [{"provider": "groq", "models": ["openai/gpt-oss-120b", "qwen/qwen3.8-27b"]}]\n\n_state = {"last_call": 0.0, "out_of_quota": False, "fallbacks": DEFAULT_FALLBACKS, "written_by": None}\n\n\ndef configure(config):\n    """Use the backup providers listed under ai_fallbacks in BRAIN.md."""\n    if config.get("ai_fallbacks") is not None:\n        _state["fallbacks"] = config["ai_fallbacks"] or []\n\n\ndef last_writer():\n    """Which provider and model wrote the most recent reply, e.g. "gemini gemini-3.8-flash"."""\n    return _state["written_by"]\n\n\ndef backup_status():\n    """e.g. "groq (key set)" for each configured backup, for the run log; never prints a key."""\n    return ", ".join(f"{b[\'provider\']} ({\'key set\' if os.getenv(PROVIDERS[b[\'provider\']][\'env\']) else \'NO KEY\'})"\n                     for b in _state["fallbacks"] if b.get("provider") in PROVIDERS) or "none"\n\n\ndef _try_fallbacks(prompt, errors):\n    """One pass over the backup providers\' models. Returns the text, or None."""\n    for backup in _state["fallbacks"]:\n        provider = PROVIDERS.get(backup.get("provider"))\n        key = provider and os.getenv(provider["env"])\n        if not key:\n            continue\n        for model in backup.get("models") or []:\n            try:\n                response = requests.post(provider["url"], headers={"Authorization": f"Bearer {key}"},\n                                         json={"model": model, "messages": [{"role": "user", "content": prompt}]},\n                                         timeout=120)\n                if response.status_code == 200:\n                    text = (response.json()["choices"][0]["message"].get("content") or "").strip()\n                    if text:\n                        _state["written_by"] = f"{backup[\'provider\']} {model}"\n                        print(f"[AI] Gemini unavailable; written by {backup[\'provider\']} {model}.")\n                        return text\n                errors.append(f"{backup[\'provider\']} {model}: {response.status_code} {response.text[:150]}")\n            except requests.RequestException as e:\n                # The exception text never includes the key: it is sent in a header, not the URL\n                errors.append(f"{backup[\'provider\']} {model}: {type(e).__name__}")\n    return None\n\n\ndef is_retryable(error):\n    name = type(error).__name__\n    return any(code in str(error) for code in RETRYABLE) or any(\n        word in name for word in ("Connect", "Protocol", "Timeout", "Network"))\n\n\ndef _pace():\n    wait = _state["last_call"] + MIN_GAP_SECONDS - time.monotonic()\n    if wait > 0:\n        time.sleep(wait)\n    _state["last_call"] = time.monotonic()\n\n\ndef _try_models(client, prompt, models, errors, settings=None):\n    """One pass over the models. Returns the text, or None if every model failed with a retryable error."""\n    for model in models:\n        for attempt in range(2):\n            _pace()\n            try:\n                return client.models.generate_content(model=model, contents=prompt, config=settings).text.strip()\n            except Exception as e:\n                message = str(e)\n                if not is_retryable(e):\n                    raise\n                errors.append(f"{model}: {message[:200]}")\n                # A retired model or an exhausted quota will not recover in 5 seconds, so go straight to\n                # the next model instead of spending a second request on the same one\n                if any(code in message for code in ("404", "NOT_FOUND") + QUOTA):\n                    break\n                time.sleep(5 * (attempt + 1))\n    return None\n\n\ndef generate_text(client, prompt, models=None):\n    errors = []\n    if not _state["out_of_quota"]:\n        models = models or DEFAULT_MODELS\n        text = _try_models(client, prompt, models, errors)\n        if text is not None:\n            _state["written_by"] = "gemini"\n            return text\n    # Gemini can\'t answer: a backup provider usually can, straight away\n    text = _try_fallbacks(prompt, errors)\n    if text is not None:\n        return text\n    if not _state["out_of_quota"] and errors and all(any(code in e for code in QUOTA) for e in errors\n                                                     if e.startswith("gemini")):\n        print(f"[Gemini] Every model is rate-limited; waiting {QUOTA_WAIT_SECONDS}s for the limit to reset...")\n        time.sleep(QUOTA_WAIT_SECONDS)\n        retry_errors = []\n        text = _try_models(client, prompt, models, retry_errors)\n        errors += retry_errors\n        if text is not None:\n            _state["written_by"] = "gemini"\n            return text\n        if retry_errors and all(any(code in e for code in QUOTA) for e in retry_errors):\n            # Daily quota used up: later requests in this run skip Gemini and go to the backups\n            _state["out_of_quota"] = True\n    if _state["out_of_quota"] and not errors:\n        errors.append("Gemini daily quota used up earlier in this run (429); no backup answered")\n    raise RuntimeError("All AI models failed: " + " | ".join(errors))\n\n\ndef watch_video(client, url, prompt, models=None):\n    """Gemini watches a public YouTube video from its link and answers the prompt; None if no model could.\n\n    Only Gemini can watch videos, so the backup providers aren\'t tried. Low media resolution keeps a 10-minute\n    video at about 60,000 tokens.\n    """\n    from google.genai import types\n    contents = types.Content(parts=[types.Part(file_data=types.FileData(file_uri=url)), types.Part(text=prompt)])\n    settings = types.GenerateContentConfig(media_resolution=types.MediaResolution.MEDIA_RESOLUTION_LOW)\n    errors = []\n    try:\n        text = _try_models(client, contents, models or DEFAULT_MODELS, errors, settings)\n    except Exception as e:\n        # A private or unsupported video is not retryable; the caller falls back to the title and description\n        errors.append(f"{type(e).__name__}: {str(e)[:200]}")\n        text = None\n    if text is None:\n        print(f"[AI] Gemini could not watch the video: {\' | \'.join(errors)[:400]}")\n        return None\n    _state["written_by"] = "gemini (watched the video)"\n    return text\n',
    'agents/learner.py': '"""--learn: analyse a YouTube video about getting views and add its techniques to execution/view_techniques.md.\n\nReads the video\'s title, description and statistics (YouTube Data API) and its transcript (subtitles via yt-dlp;\nYouTube blocks this from cloud servers, so run it on a laptop), asks Gemini which techniques it teaches and how each\nfits this pipeline, and appends an entry to SOURCES marked "proposed". Nothing is adopted automatically: rules are\nonly sent to Gemini once someone copies them into ACTIVE RULES.\n"""\nimport glob\nimport os\nimport re\nimport tempfile\nfrom datetime import datetime\n\nfrom agents.ai import generate_text\nfrom brain import VIEW_TECHNIQUES_FILE\n\nMAX_TRANSCRIPT_CHARS = 60000\nVERDICTS = ("ADOPT-RULE", "ADOPT-CODE", "ALREADY", "MANUAL", "SKIP", "REJECT")\nVERDICT_TEXT = {\n    "ADOPT-RULE": "Proposed: add the rule below to ACTIVE RULES",\n    "ADOPT-CODE": "Proposed: needs a code change (ask Claude)",\n    "ALREADY": "Already done by the pipeline",\n    "MANUAL": "Owner does this by hand",\n    "SKIP": "Doesn\'t apply to this pipeline",\n    "REJECT": "Rejected: against YouTube\'s policies or misleading",\n}\n\n\ndef video_id_from_link(link):\n    match = re.search(r"(?:youtu\\.be/|[?&]v=|/shorts/|/embed/|/live/)([\\w-]{11})", link)\n    if match:\n        return match.group(1)\n    if re.fullmatch(r"[\\w-]{11}", link.strip()):\n        return link.strip()\n    raise ValueError(f"Not a YouTube video link: {link}")\n\n\ndef fetch_details(video_id):\n    from googleapiclient.discovery import build\n    youtube = build("youtube", "v3", developerKey=os.getenv("YOUTUBE_API_KEY"))\n    items = youtube.videos().list(part="snippet,statistics,contentDetails", id=video_id).execute().get("items", [])\n    if not items:\n        raise ValueError(f"Video {video_id} not found (private, removed, or a wrong link).")\n    return items[0]\n\n\ndef vtt_to_text(vtt):\n    """Subtitle file -> plain text, dropping timings, tags and the repeated lines of auto-captions."""\n    lines, previous = [], ""\n    for line in vtt.splitlines():\n        line = re.sub(r"<[^>]+>", "", line).strip()\n        if not line or "-->" in line or line.startswith(("WEBVTT", "Kind:", "Language:")) or line == previous:\n            continue\n        lines.append(line)\n        previous = line\n    return re.sub(r"\\s+", " ", " ".join(lines)).strip()\n\n\ndef fetch_transcript(video_id):\n    """The English (or original-language) subtitles as text, or "" if none can be downloaded."""\n    import yt_dlp\n    with tempfile.TemporaryDirectory() as folder:\n        options = {"skip_download": True, "writesubtitles": True, "writeautomaticsub": True,\n                   "subtitleslangs": ["en.*", "en"], "subtitlesformat": "vtt", "quiet": True,\n                   "no_warnings": True, "ignoreerrors": True, "outtmpl": os.path.join(folder, "%(id)s.%(ext)s")}\n        try:\n            with yt_dlp.YoutubeDL(options) as ydl:\n                ydl.download([f"https://www.youtube.com/watch?v={video_id}"])\n        except Exception as e:\n            print(f"[Learn] Could not download subtitles ({e}).")\n        files = sorted(glob.glob(os.path.join(folder, "*.vtt")), key=lambda p: ("orig" not in p, p))\n        for path in files:\n            with open(path, "r", encoding="utf-8") as f:\n                text = vtt_to_text(f.read())\n            if text:\n                return text\n    return ""\n\n\ndef build_prompt(video, transcript, pipeline_rules, watching=False):\n    snippet, stats = video["snippet"], video.get("statistics", {})\n    return (\n        "You review advice about growing YouTube views for a fully automated, faceless YouTube pipeline. It makes "\n        "Shorts and 4 to 7 minute videos from trending topics: Gemini writes an original script, title, description "\n        "and hashtags; an AI voice narrates; free stock clips are edited to match; videos upload on a fixed daily "\n        "schedule to a news/geopolitics channel and a kids entertainment channel. It can change: how topics are "\n        "chosen (YouTube search, trend speed, language), what the script/title/hashtag writer is told, posting "\n        "times, and it reads public view counts. It cannot film people or reply to comments.\\n\\n"\n        f"Rules the writer already follows:\\n{pipeline_rules or \'(none)\'}\\n\\n"\n        f"Video: {snippet[\'title\']} by {snippet[\'channelTitle\']} ({stats.get(\'viewCount\', \'?\')} views, "\n        f"published {snippet[\'publishedAt\'][:10]})\\n"\n        f"Description: {snippet.get(\'description\', \'\')[:1500]}\\n"\n        + (f"Transcript: {transcript[:MAX_TRANSCRIPT_CHARS]}\\n\\n" if transcript else\n           "You are watching the video itself.\\n\\n" if watching else\n           "Transcript: not available; judge from the title and description only.\\n\\n")\n        + "List each distinct technique the video teaches for getting more views (ignore its adverts and sponsors). "\n        "For each, choose one verdict: ADOPT-RULE (a new instruction for the script/title/hashtag writer), "\n        "ADOPT-CODE (the pipeline\'s code would need to change), ALREADY (the pipeline or its rules already do it), "\n        "MANUAL (the channel owner must do it by hand), SKIP (doesn\'t apply), REJECT (fakes engagement, misleads "\n        "viewers, re-uploads other people\'s content, or otherwise breaks YouTube\'s policies). Be strict: only ADOPT "\n        "what the video gives evidence for.\\n"\n        "Reply with one line per technique, nothing else, in exactly this form:\\n"\n        "TECHNIQUE: <short name> | VERDICT: <one verdict> | WHY: <one sentence of evidence from the video> | "\n        "RULE: <for ADOPT-RULE, the instruction in one sentence; otherwise ->"\n    )\n\n\ndef parse_techniques(text):\n    techniques = []\n    for line in text.splitlines():\n        line = line.strip().lstrip("-*0123456789. ")\n        if not line.upper().startswith("TECHNIQUE:"):\n            continue\n        fields = {}\n        for part in line.split("|"):\n            label, _, value = part.partition(":")\n            fields[label.strip().upper()] = value.strip()\n        verdict = fields.get("VERDICT", "").upper()\n        if fields.get("TECHNIQUE") and verdict in VERDICTS:\n            rule = fields.get("RULE", "")\n            techniques.append({"name": fields["TECHNIQUE"], "verdict": verdict, "why": fields.get("WHY", ""),\n                               "rule": rule if verdict == "ADOPT-RULE" and rule not in ("", "-") else ""})\n    return techniques\n\n\ndef source_entry(number, link, video, techniques, basis, today=None):\n    """One SOURCES entry; basis says what was analysed, e.g. "the transcript" or "watching the video"."""\n    snippet, stats = video["snippet"], video.get("statistics", {})\n    lines = [\n        f\'### S{number}. "{snippet["title"]}" by {snippet["channelTitle"]}\',\n        f"- Link: {link}",\n        f"- When analysed: {today or datetime.now().date().isoformat()}, by --learn with Gemini, from {basis}"\n        f" ({int(stats.get(\'viewCount\', 0)):,} views; published {snippet[\'publishedAt\'][:10]})",\n        "- Status: proposed (review before adopting; nothing here is sent to Gemini yet)",\n        "",\n        "**What it teaches:**",\n    ]\n    for i, t in enumerate(techniques, 1):\n        lines.append(f"{i}. **{t[\'name\']}.** {t[\'why\']}")\n        lines.append(f"   → {VERDICT_TEXT[t[\'verdict\']]}." + (f\' Rule: "{t["rule"]}"\' if t["rule"] else ""))\n    return "\\n".join(lines) + "\\n"\n\n\ndef next_source_number(text):\n    numbers = [int(n) for n in re.findall(r"^### S(\\d+)\\.", text, re.MULTILINE)]\n    return max(numbers, default=0) + 1\n\n\ndef known_source(video_id, path=VIEW_TECHNIQUES_FILE):\n    """The S number of the entry that already analysed this video, or None."""\n    with open(path, "r", encoding="utf-8") as f:\n        text = f.read()\n    for match in re.finditer(r"^### S(\\d+)\\.(.*?)(?=^### S|\\Z)", text, re.MULTILINE | re.DOTALL):\n        if f"/{video_id}" in match.group(2) or f"v={video_id}" in match.group(2):\n            return int(match.group(1))\n    return None\n\n\ndef save_entry(link, video, techniques, basis, path=VIEW_TECHNIQUES_FILE):\n    """Append a "proposed" entry to SOURCES. Returns its S number."""\n    with open(path, "r", encoding="utf-8") as f:\n        text = f.read()\n    number = next_source_number(text)\n    entry = source_entry(number, link, video, techniques, basis)\n    with open(path, "a", encoding="utf-8") as f:\n        f.write(("\\n" if not text.endswith("\\n\\n") else "") + entry)\n    print(f"[Learn] Added to {path}:\\n\\n{entry}")\n    return number\n\n\ndef learn(link, ai_client, models=None, path=VIEW_TECHNIQUES_FILE):\n    """Analyse one video and append its entry to view_techniques.md. Returns the techniques found."""\n    from agents.ai import watch_video\n    from brain import view_rules\n    video_id = video_id_from_link(link)\n    if known_source(video_id, path):\n        print(f"[Learn] {link} is already in {os.path.basename(path)}.")\n        return []\n    video = fetch_details(video_id)\n    print(f"[Learn] {video[\'snippet\'][\'title\']} by {video[\'snippet\'][\'channelTitle\']}")\n    transcript = fetch_transcript(video_id)\n    reply, basis = None, "the transcript"\n    if transcript:\n        print(f"[Learn] Transcript: {len(transcript.split())} words")\n    else:\n        # No subtitles (YouTube blocks them from cloud servers): Gemini watches the video itself\n        print("[Learn] No transcript; Gemini watches the video.")\n        reply = watch_video(ai_client, f"https://youtu.be/{video_id}",\n                            build_prompt(video, "", view_rules(path), watching=True), models)\n        basis = "watching the video" if reply else "the title and description only (the video couldn\'t be watched)"\n    reply = reply or generate_text(ai_client, build_prompt(video, transcript, view_rules(path)), models)\n    techniques = parse_techniques(reply)\n    if not techniques:\n        print("[Learn] Gemini returned no techniques in the expected form; nothing was saved. Try again later.")\n        return []\n    save_entry(link, video, techniques, basis, path)\n    return techniques\n\n\ndef entry_bounds(text, number):\n    """(start, end) of entry S<number> in view_techniques.md\'s text, or None."""\n    match = re.search(rf"^### S{number}\\..*?(?=^### S|\\Z)", text, re.MULTILINE | re.DOTALL)\n    return (match.start(), match.end()) if match else None\n\n\ndef proposed_rules(text, number):\n    """[(technique number, rule)] still waiting for approval in entry S<number>."""\n    bounds = entry_bounds(text, number)\n    if not bounds:\n        return []\n    marker = re.escape(VERDICT_TEXT["ADOPT-RULE"])\n    return [(int(n), rule) for n, rule in re.findall(rf\'^(\\d+)\\. .*\\n\\s+→ {marker}\\. Rule: "(.*)"$\',\n                                                     text[bounds[0]:bounds[1]], re.MULTILINE)]\n\n\ndef review(number, picks=None, approve=True, path=VIEW_TECHNIQUES_FILE, today=None):\n    """Approve proposed rules of entry S<number> into ACTIVE RULES, or reject them; returns the rules adopted.\n\n    picks: technique numbers to approve (None = all proposed rules). The entry is marked reviewed, and proposed\n    rules that weren\'t approved are marked as not adopted.\n    """\n    with open(path, "r", encoding="utf-8") as f:\n        text = f.read()\n    bounds = entry_bounds(text, number)\n    if not bounds:\n        raise ValueError(f"there is no S{number} in view_techniques.md")\n    rules = proposed_rules(text, number)\n    chosen = [(n, rule) for n, rule in rules if approve and (picks is None or n in picks)]\n    entry = text[bounds[0]:bounds[1]]\n    for n, rule in rules:\n        verdict = ("Adopted into ACTIVE RULES (approved in Telegram)" if (n, rule) in chosen\n                   else "Not adopted (owner, in Telegram)")\n        entry = entry.replace(f\'{VERDICT_TEXT["ADOPT-RULE"]}. Rule: "{rule}"\', f\'{verdict}. Rule: "{rule}"\', 1)\n    entry = re.sub(r"^- Status: .*$", f"- Status: reviewed in Telegram on {today or datetime.now().date()} "\n                   f"({\'approved\' if chosen else \'rejected\'})", entry, count=1, flags=re.MULTILINE)\n    text = text[:bounds[0]] + entry + text[bounds[1]:]\n    if chosen:\n        # Approved rules go at the end of ACTIVE RULES, numbered after the last one, tagged with their source\n        active = re.search(r"^## ACTIVE RULES\\s*\\n(.*?)(?=^## )", text, re.MULTILINE | re.DOTALL)\n        last = max((int(n) for n in re.findall(r"^(\\d+)\\. ", active.group(1), re.MULTILINE)), default=0)\n        added = "".join(f"{last + i}. {rule} [S{number}]\\n" for i, (_, rule) in enumerate(chosen, 1))\n        text = text[:active.start(1)] + active.group(1).rstrip("\\n") + "\\n" + added + "\\n" + text[active.end(1):]\n    with open(path, "w", encoding="utf-8", newline="\\n") as f:\n        f.write(text)\n    return [rule for _, rule in chosen]\n',
    'agents/inbox.py': '"""Telegram inbox: the owner posts in the alerts channel, and the pipeline reads it and acts on it.\n\nRuns from the "Telegram Inbox" GitHub workflow (hourly) or `python execution/execution.py --inbox`. The bot reads\nthe posts in TELEGRAM_CHANNEL_ID (only channel admins can post there) and handles:\n\n1. A YouTube link. Gemini watches the video and decides what it is:\n   - advice about getting views: its techniques become a "proposed" entry in execution/view_techniques.md and\n     the bot replies with the proposed rules. "approve S5" (or "approve S5 1,3") puts them in ACTIVE RULES,\n     "reject S5" drops them;\n   - an example the owner likes: queued in execution/video_requests.json for the channel it fits. That channel\'s\n     next run makes an original video like it (same topic and format, never its words, characters or footage),\n     and its search phrases lead the Scout\'s searches for BOOST_DAYS days, so the following videos ride the trend.\n2. A message asking for a video ("make a kids video about how octopuses hide"): queued the same way.\n3. "queue" lists the recent requests; "cancel Q3" removes one.\n\nEach post is confirmed after it\'s handled, so it\'s handled once. Telegram keeps unread posts for 24 hours.\n"""\nimport html\nimport json\nimport os\nimport re\nfrom datetime import datetime, timedelta, timezone\n\nimport requests\n\nfrom agents import learner\nfrom agents.agent_7_notifier import send_telegram\nfrom agents.ai import generate_text, watch_video\nfrom brain import view_rules\n\nREQUESTS_FILE = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "execution",\n                             "video_requests.json")\n# A request\'s search phrases lead the Scout\'s searches for this many days\nBOOST_DAYS = 7\n# Requests not made within this many days are dropped (e.g. a long video for a channel that makes none)\nKEEP_DAYS = 14\n# YouTube Shorts can be up to 3 minutes long\nSHORT_MAX_SECONDS = 180\nYOUTUBE_LINK = re.compile(r"https?://(?:www\\.|m\\.)?(?:youtube\\.com|youtu\\.be)/\\S+")\nOTHER_VIDEO_LINK = re.compile(r"https?://(?:www\\.)?(?:instagram\\.com|tiktok\\.com|facebook\\.com|fb\\.watch)/\\S+")\nREVIEW = re.compile(r"^/?(approve|reject)\\s+S?(\\d+)\\s*([\\d,\\s]*)$", re.IGNORECASE)\nCANCEL = re.compile(r"^/?cancel\\s+Q?(\\d+)$", re.IGNORECASE)\n\n\n# ---------- the request queue (execution/video_requests.json, committed by the workflow) ----------\n\ndef load_requests(path=REQUESTS_FILE):\n    try:\n        with open(path, "r", encoding="utf-8") as f:\n            data = json.load(f)\n    except (OSError, ValueError):\n        data = {}\n    return {"next_id": int(data.get("next_id") or 1), "requests": list(data.get("requests") or [])}\n\n\ndef save_requests(data, path=REQUESTS_FILE, now=None):\n    cutoff = ((now or datetime.now(timezone.utc)) - timedelta(days=KEEP_DAYS)).isoformat()\n    data["requests"] = [r for r in data["requests"] if r.get("added", "") >= cutoff]\n    with open(path, "w", encoding="utf-8", newline="\\n") as f:\n        json.dump(data, f, indent=2, ensure_ascii=False)\n        f.write("\\n")\n\n\ndef waiting_requests(channel_key, video_format, used_ids, path=REQUESTS_FILE):\n    """The owner\'s requests this channel\'s Scout should make next (oldest first), skipping ones already made."""\n    return [r for r in load_requests(path)["requests"]\n            if r.get("channel") == channel_key and r.get("format") in (video_format, "any")\n            and r.get("video_id") not in used_ids]\n\n\ndef boosted_phrases(channel_key, path=REQUESTS_FILE, now=None):\n    """Search phrases from this channel\'s requests of the last BOOST_DAYS days, newest first."""\n    cutoff = ((now or datetime.now(timezone.utc)) - timedelta(days=BOOST_DAYS)).isoformat()\n    recent = [r for r in load_requests(path)["requests"] if r.get("channel") == channel_key\n              and r.get("added", "") >= cutoff]\n    return list(dict.fromkeys(p for r in reversed(recent) for p in r.get("search_phrases") or []))\n\n\ndef add_request(fields, path=REQUESTS_FILE):\n    """Queue a request; fields: kind, channel, format, video_id (None for a topic), link, title, description,\n    creator, notes, search_phrases. Returns its id, e.g. "Q3"."""\n    data = load_requests(path)\n    request_id = f"Q{data[\'next_id\']}"\n    data["next_id"] += 1\n    request = dict(fields, id=request_id, added=datetime.now(timezone.utc).isoformat())\n    # A topic has no source video; its id keeps it apart in the manifest\n    request["video_id"] = request.get("video_id") or f"request-{request_id}"\n    data["requests"].append(request)\n    save_requests(data, path)\n    return request_id\n\n\n# ---------- Telegram ----------\n\ndef same_chat(chat, channel_id):\n    channel_id = str(channel_id)\n    return str(chat.get("id")) == channel_id or ("@" + (chat.get("username") or "")).lower() == channel_id.lower()\n\n\ndef get_posts(token, channel_id):\n    """[(update id, text)] of the unread posts; posts from other chats come back with empty text."""\n    reply = requests.get(f"https://api.telegram.org/bot{token}/getUpdates",\n                         params={"timeout": 0, "allowed_updates": json.dumps(["channel_post"])}, timeout=30)\n    reply.raise_for_status()\n    posts = []\n    for update in reply.json().get("result", []):\n        post = update.get("channel_post") or {}\n        text = (post.get("text") or post.get("caption") or "").strip()\n        posts.append((update["update_id"], text if same_chat(post.get("chat") or {}, channel_id) else ""))\n    return posts\n\n\ndef confirm(token, last_update_id):\n    """Tell Telegram every post up to last_update_id is handled, so it isn\'t delivered again."""\n    requests.get(f"https://api.telegram.org/bot{token}/getUpdates",\n                 params={"offset": last_update_id + 1, "timeout": 0, "limit": 1}, timeout=30)\n\n\n# ---------- understanding a post ----------\n\ndef fields_of(text):\n    """{"KIND": ..., "CHANNEL": ...} from "LABEL: value" lines of an AI reply."""\n    fields = {}\n    for line in text.splitlines():\n        label, colon, value = line.strip().lstrip("*# ").partition(":")\n        if colon and re.fullmatch(r"[A-Z]+", label.strip("* ")):\n            fields.setdefault(label.strip("* "), value.strip().strip("*").strip())\n    return fields\n\n\ndef channel_list(config):\n    lines = []\n    for key, p in config["profiles"].items():\n        kids = " (made for kids, ages 4 to 9)" if p.get("made_for_kids") else ""\n        long = "Shorts and long videos" if (p.get("long") or {}).get("count") else "Shorts only"\n        lines.append(f"- {key}: {p[\'channel_name\']}{kids}; niche: {p.get(\'niche\')}; language: "\n                     f"{p.get(\'language\', \'English\')}; makes {long}")\n    return "\\n".join(lines)\n\n\ndef seconds_of(duration):\n    """ISO 8601 duration (PT1M5S) -> seconds."""\n    parts = re.fullmatch(r"P(?:(\\d+)D)?T?(?:(\\d+)H)?(?:(\\d+)M)?(?:(\\d+)S)?", duration or "")\n    if not parts:\n        return 0\n    days, hours, minutes, seconds = (int(x or 0) for x in parts.groups())\n    return ((days * 24 + hours) * 60 + minutes) * 60 + seconds\n\n\ndef link_prompt(config, video, note, watching=True):\n    snippet = video["snippet"]\n    seen = ("You are watching the video." if watching else\n            f"You can\'t watch the video; judge from its title and description: {snippet[\'title\']} / "\n            f"{snippet.get(\'description\', \'\')[:1500]}.")\n    return (\n        "The owner of these YouTube channels shared the video below in their Telegram channel:\\n"\n        f"{channel_list(config)}\\n"\n        f"Owner\'s note with the link: {note or \'(none)\'}\\n\\n"\n        f"{seen} First decide what it is, and put KIND on the first line of your reply:\\n"\n        "KIND: ADVICE when the video teaches how to get more views or grow a channel. Then follow the ADVICE "\n        "instructions below.\\n"\n        "KIND: EXAMPLE when it\'s a content video the owner wants more videos like. Then reply with exactly these "\n        "lines:\\n"\n        "CHANNEL: the channel key it fits best (follow the owner\'s note if it names a channel), or NONE if it fits "\n        "no channel\'s niche or isn\'t suitable (a made-for-kids channel only takes content safe for ages 4 to 9)\\n"\n        "TOPIC: the topic in under 10 words\\n"\n        "WHY: 2 or 3 sentences on what makes it work (hook, structure, pacing, tone, visuals) that an original video "\n        "can copy without copying its words, characters, music or footage\\n"\n        "SEARCH: 3 YouTube search phrases (2 to 5 words, in the channel\'s language, comma-separated) that find more "\n        "videos on this trend\\n\\n"\n        "ADVICE instructions:\\n" + learner.build_prompt(video, "", view_rules(), watching=watching)\n        + f"\\n\\n(The video: {snippet[\'title\']} by {snippet[\'channelTitle\']}.)"\n    )\n\n\ndef text_prompt(config, text):\n    return (\n        "The owner of these YouTube channels posted this message in their Telegram channel:\\n"\n        f"{channel_list(config)}\\n\\n"\n        f\'Message: "{text}"\\n\\n\'\n        "If it asks for a video (a topic to make a video about), reply with exactly these lines:\\n"\n        "KIND: REQUEST\\n"\n        "CHANNEL: the channel key it is for (named in the message, or clearly that channel\'s niche), or NONE if "\n        "it\'s unclear or the topic isn\'t safe for a made-for-kids channel it names\\n"\n        "FORMAT: short or long only if the message says so, otherwise any\\n"\n        "TOPIC: the topic in under 12 words, in the channel\'s language\\n"\n        "WHY: what the owner wants from the video (angle, style, length) in 1 or 2 sentences, or -\\n"\n        "SEARCH: 3 YouTube search phrases (2 to 5 words, in the channel\'s language, comma-separated) that find "\n        "current videos on this topic\\n"\n        "Otherwise reply with only: KIND: OTHER"\n    )\n\n\ndef phrases_of(value):\n    return [p.strip().strip(\'"\') for p in (value or "").split(",") if p.strip()][:3]\n\n\nclass Inbox:\n    def __init__(self, config, ai_client):\n        self.config = config\n        self.client = ai_client\n        self.models = config.get("ai_models")\n\n    def queue(self, kind, fields, channel, video_format, **source):\n        """Queue a request and the Telegram reply that confirms it."""\n        profile = self.config["profiles"][channel]\n        if video_format == "long" and not (profile.get("long") or {}).get("count"):\n            video_format = "short"\n        phrases = phrases_of(fields.get("SEARCH"))\n        request_id = add_request(dict(source, kind=kind, channel=channel, format=video_format,\n                                      title=source.get("title") or fields.get("TOPIC", ""),\n                                      topic=fields.get("TOPIC", ""),\n                                      notes="" if fields.get("WHY", "-") == "-" else fields.get("WHY", ""),\n                                      search_phrases=phrases))\n        which = {"short": "Short", "long": "long video"}.get(video_format, "video")\n        return (f"🎬 <b>Queued {request_id}</b> for <b>{html.escape(profile[\'channel_name\'])}</b>: its next "\n                f"{which} will be an original video on <b>{html.escape(fields.get(\'TOPIC\', \'\'))}</b>"\n                + (" made like the video you shared" if kind == "example" else "") + ".\\n"\n                + (f"{\'Why it works\' if kind == \'example\' else \'Your wishes\'}: {html.escape(fields[\'WHY\'])}\\n"\n                   if fields.get("WHY", "-") != "-" else "")\n                + (f"Searching this trend first for {BOOST_DAYS} days: {html.escape(\', \'.join(phrases))}\\n"\n                   if phrases else "")\n                + f\'Reply "cancel {request_id}" to drop it.\')\n\n    def handle_link(self, link, note):\n        video_id = learner.video_id_from_link(link)\n        known = learner.known_source(video_id)\n        if known:\n            return f"ℹ️ That video was already analysed as S{known} in view_techniques.md."\n        if any(r.get("video_id") == video_id for r in load_requests()["requests"]):\n            return "ℹ️ That video is already queued."\n        video = learner.fetch_details(video_id)\n        reply = watch_video(self.client, f"https://youtu.be/{video_id}", link_prompt(self.config, video, note),\n                            self.models)\n        basis = "watching the video"\n        if reply is None:\n            basis = "the title and description only (the video couldn\'t be watched)"\n            reply = generate_text(self.client, link_prompt(self.config, video, note, watching=False), self.models)\n        fields = fields_of(reply)\n        title = video["snippet"]["title"]\n        if fields.get("KIND", "").upper() == "EXAMPLE":\n            channel = fields.get("CHANNEL", "NONE").strip().lower()\n            if channel not in self.config["profiles"]:\n                return (f"🤔 <b>{html.escape(title)}</b> doesn\'t fit any of the channels (or isn\'t suitable for "\n                        "kids), so nothing was queued. Post it again with the channel name (kids or frontline) "\n                        "to choose one.")\n            video_format = ("short" if seconds_of(video.get("contentDetails", {}).get("duration")) <= SHORT_MAX_SECONDS\n                            else "long")\n            snippet = video["snippet"]\n            return self.queue("example", fields, channel, video_format, video_id=video_id, link=link,\n                              description=snippet.get("description", ""), creator=snippet["channelTitle"],\n                              title=title)\n        techniques = learner.parse_techniques(reply)\n        if not techniques:\n            return f"⚠️ Couldn\'t analyse <b>{html.escape(title)}</b> right now. Post the link again later."\n        number = learner.save_entry(link, video, techniques, basis)\n        return self.advice_reply(number, title, techniques)\n\n    @staticmethod\n    def advice_reply(number, title, techniques):\n        lines = [f"🧠 <b>Learned from:</b> {html.escape(title)} (S{number})"]\n        rules = [(i, t) for i, t in enumerate(techniques, 1) if t["verdict"] == "ADOPT-RULE"]\n        if rules:\n            lines.append("<b>Proposed rules for every future video:</b>")\n            lines += [f"{i}. {html.escape(t[\'rule\'])}" for i, t in rules]\n            lines.append(f\'Reply "approve S{number}", "approve S{number} {rules[0][0]}" (only some) or \'\n                         f\'"reject S{number}".\')\n        else:\n            lines.append("Nothing new to adopt as a writing rule.")\n        groups = {"ALREADY": "♻️ Already done", "ADOPT-CODE": "🛠 Needs a code change (ask Claude)",\n                  "MANUAL": "🙋 For you to do", "REJECT": "⛔ Rejected (against YouTube\'s rules)"}\n        for verdict, label in groups.items():\n            names = [t["name"] for t in techniques if t["verdict"] == verdict]\n            if names:\n                lines.append(f"{label}: {html.escape(\'; \'.join(names))}")\n        return "\\n".join(lines)\n\n    def handle_text(self, text):\n        review = REVIEW.match(text)\n        if review:\n            approve, number = review.group(1).lower() == "approve", int(review.group(2))\n            picks = {int(n) for n in re.findall(r"\\d+", review.group(3))} or None\n            rules = learner.review(number, picks, approve)\n            if rules:\n                return (f"✅ Added to the rules every video follows, from the next run:\\n"\n                        + "\\n".join(f"• {html.escape(r)}" for r in rules))\n            return f"🗑 S{number} reviewed: no rules added."\n        cancel = CANCEL.match(text)\n        if cancel:\n            data = load_requests()\n            before = len(data["requests"])\n            data["requests"] = [r for r in data["requests"] if r.get("id") != f"Q{cancel.group(1)}"]\n            save_requests(data)\n            return (f"🗑 Q{cancel.group(1)} cancelled." if len(data["requests"]) < before\n                    else f"There is no request Q{cancel.group(1)}.")\n        if text.strip().lower().lstrip("/") in ("queue", "requests"):\n            recent = load_requests()["requests"]\n            if not recent:\n                return f"No requests in the last {KEEP_DAYS} days."\n            return (f"📋 Requests of the last {KEEP_DAYS} days (each is made in its channel\'s next run; the "\n                    "channel\'s upload message marks it):\\n" + "\\n".join(\n                        f"{r[\'id\']}: {html.escape(r.get(\'topic\') or r.get(\'title\', \'\'))} → {r[\'channel\']}, "\n                        f"{r[\'format\']}" for r in recent))\n        fields = fields_of(generate_text(self.client, text_prompt(self.config, text), self.models))\n        if fields.get("KIND", "").upper() != "REQUEST":\n            return None\n        channel = fields.get("CHANNEL", "NONE").strip().lower()\n        if channel not in self.config["profiles"]:\n            return ("🤔 I couldn\'t tell which channel that video is for (or the topic isn\'t suitable for kids). "\n                    "Say it again with the channel name, e.g. \\"make a kids video about ...\\".")\n        video_format = fields.get("FORMAT", "any").strip().lower()\n        return self.queue("topic", fields, channel, video_format if video_format in ("short", "long") else "any",\n                          description=text, creator="owner request")\n\n    def handle(self, text):\n        """The reply to one post (Telegram HTML), or None to stay quiet."""\n        link = YOUTUBE_LINK.search(text)\n        if link:\n            return self.handle_link(link.group(0), YOUTUBE_LINK.sub("", text).strip())\n        if OTHER_VIDEO_LINK.search(text):\n            return ("📎 Only YouTube links can be analysed for now: Instagram, TikTok and Facebook need a login. "\n                    "Find the same video on YouTube, or describe it as a request (\\"make a kids video about ...\\").")\n        return self.handle_text(text)\n\n\ndef run(config, ai_client):\n    """Handle every unread post in the Telegram channel. Returns how many were handled."""\n    token, channel_id = os.getenv("TELEGRAM_BOT_TOKEN"), os.getenv("TELEGRAM_CHANNEL_ID")\n    if not token or not channel_id:\n        print("[Inbox] TELEGRAM_BOT_TOKEN or TELEGRAM_CHANNEL_ID is not set.")\n        return 0\n    try:\n        posts = get_posts(token, channel_id)\n    except Exception as e:\n        # The exception text can contain the request URL, which includes the bot token\n        print(f"[Inbox] Could not read Telegram: {str(e).replace(token, \'***\')}")\n        return 0\n    inbox, handled = Inbox(config, ai_client), 0\n    for update_id, text in posts:\n        if text:\n            print(f"[Inbox] Post: {text[:120]}")\n            try:\n                reply = inbox.handle(text)\n            except Exception as e:\n                print(f"[Inbox] Failed: {e}")\n                reply = f"⚠️ Couldn\'t handle that post ({html.escape(str(e)[:150])}). Try again later."\n            if reply:\n                send_telegram(reply)\n            handled += 1\n        # Confirmed one by one, so a crash never makes Telegram deliver an already-handled post again\n        confirm(token, update_id)\n    print(f"[Inbox] {handled} post(s) handled.")\n    return handled\n',
    'agents/branding.py': '"""Fetches and caches each channel\'s YouTube profile picture, used as the logo on the end card."""\nimport os\nfrom io import BytesIO\n\nimport requests\nfrom PIL import Image\nfrom googleapiclient.discovery import build\n\nfrom brain import parse_channel_url\n\n\ndef channel_logo(profile, channel_key, branding_dir):\n    """Return a local PNG of the channel\'s logo, or None if it can\'t be found.\n\n    A logo_file set on the channel page wins; otherwise the channel\'s YouTube profile picture is\n    downloaded once and cached (delete the cached file to refresh it after changing the picture).\n    """\n    custom = profile.get("logo_file")\n    if custom and os.path.exists(custom):\n        return custom\n\n    cached = os.path.join(branding_dir, f"logo_{channel_key}.png")\n    if os.path.exists(cached):\n        return cached\n\n    api_key = os.getenv("YOUTUBE_API_KEY")\n    parsed = parse_channel_url(profile.get("channel_url", ""))\n    if not api_key or not parsed:\n        return None\n    kind, value = parsed\n    try:\n        lookup = {"forHandle": value} if kind == "handle" else {"id": value}\n        youtube = build("youtube", "v3", developerKey=api_key)\n        items = youtube.channels().list(part="snippet", **lookup).execute().get("items", [])\n        thumbnails = items[0]["snippet"]["thumbnails"] if items else {}\n        url = next((thumbnails[size]["url"] for size in ("high", "medium", "default") if size in thumbnails), None)\n        if not url:\n            return None\n        image = Image.open(BytesIO(requests.get(url, timeout=20).content)).convert("RGBA")\n        os.makedirs(branding_dir, exist_ok=True)\n        image.save(cached)\n        return cached\n    except Exception as e:\n        print(f"[Branding] Could not fetch the logo for {channel_key}: {e}")\n        return None\n',
    'agents/stock_footage.py': '"""Free stock footage from Pixabay or Pexels, used instead of re-using trending YouTube videos.\n\nYouTube blocks video downloads from cloud servers such as GitHub\'s, while these APIs work everywhere and their clips\nare free to use. Both ask that you show where the footage came from, so each description credits the site.\n\nfootage.provider in BRAIN.md: "pixabay", "pexels", or "auto" (whichever has a key: PIXABAY_API_KEY, then PEXELS_API_KEY).\n"""\nimport html\nimport os\nimport re\nimport shutil\nimport subprocess\nimport time\n\nimport imageio_ffmpeg\nimport requests\n\nfrom agents.ai import generate_text\n\nPROVIDERS = {\n    "pixabay": {"name": "Pixabay", "site": "https://pixabay.com", "env": "PIXABAY_API_KEY"},\n    "pexels": {"name": "Pexels", "site": "https://www.pexels.com", "env": "PEXELS_API_KEY"},\n}\nPEXELS_URLS = ["https://api.pexels.com/videos/search", "https://api.pexels.com/v1/videos/search"]\n# Real footage of the actual people, places and events (Frontline): Wikimedia Commons hosts official government and\n# news-agency video under free licences. Its API asks every client to identify itself.\nCOMMONS_API = "https://commons.wikimedia.org/w/api.php"\nCOMMONS_HEADERS = {"User-Agent": "FrontlineLedgerTT83/1.0 (https://github.com/tarunteja83/PersonalProjects-TT83)"}\nCOMMONS_SITE = "Wikimedia Commons"\n# File-name ending of real-footage clips; the editor shows them whole (not cropped) in vertical Shorts\nREAL_SUFFIX = "_real.mp4"\n# Words in a footage term that describe the shot rather than who or what is in it\nSHOT_WORDS = {"the", "and", "with", "speech", "address", "remarks", "footage", "video", "clip", "scene", "shot",\n              "close", "closeup", "view", "aerial", "live", "news", "of", "in", "at", "on", "for"}\nPIXABAY_URL = "https://pixabay.com/api/videos/"\nPIXABAY_IMAGES_URL = "https://pixabay.com/api/"\n# Words that describe the look of a clip, not what is in it; they don\'t make a clip match a scene\nSTYLE_WORDS = {"cartoon", "cartoons", "animated", "animation", "funny", "cute", "happy", "silly", "colorful",\n               "colourful", "kids", "kid", "children", "magical", "fun", "playful", "little", "illustration"}\nMAX_DOWNLOAD_BYTES = 80 * 1024 * 1024\n# The ideal clip height for each output shape: Shorts are 1080x1920, long videos 1920x1080\nTARGET_HEIGHT = {"portrait": 1920, "landscape": 1080}\n\n\ndef safe_error(error, api_key):\n    # Pixabay puts the key in the request URL, so error messages must never be printed with it\n    return str(error).replace(api_key, "***") if api_key else str(error)\n\n\ndef with_retries(action, attempts=4):\n    """Run action(), retrying dropped connections and rate limits with a growing pause."""\n    for attempt in range(attempts):\n        try:\n            return action()\n        except requests.RequestException as e:\n            status = getattr(getattr(e, "response", None), "status_code", None)\n            if attempt == attempts - 1 or (status is not None and status < 500 and status != 429):\n                raise\n            # Rate limits reset per minute, so wait long enough for the window to clear\n            time.sleep(30 * (attempt + 1) if status == 429 else 5 * (attempt + 1))\n\n\n_last_request = [0.0]\n\n\ndef pace(min_gap=0.7):\n    """Keep API searches under about 85 a minute (Pixabay allows 100)."""\n    wait = _last_request[0] + min_gap - time.monotonic()\n    if wait > 0:\n        time.sleep(wait)\n    _last_request[0] = time.monotonic()\n\n\ndef choose_provider(setting="auto"):\n    """Return (provider, api_key) for the configured provider, or (None, None) if no key is set."""\n    order = [setting] if setting in PROVIDERS else ["pixabay", "pexels"]\n    for provider in order:\n        key = os.getenv(PROVIDERS[provider]["env"])\n        if key:\n            return provider, key\n    return None, None\n\n\ndef search_terms(ai_client, item, profile, models, count):\n    """Ask Gemini for short visual search terms matching the trending topic."""\n    prompt = (\n        f"Trending video title: {item[\'original_title\']}\\n"\n        f"Context: {item[\'original_description\'][:300]}\\n"\n        f"Channel niche: {profile.get(\'niche\', \'\')}\\n"\n        + ("The audience is young children, so keep every term child-friendly.\\n" if profile.get("made_for_kids") else "")\n        + ("Some clips will be cartoon animation, so terms like \'cartoon cat\' or \'animated forest\' are good.\\n"\n           if profile.get("footage_style") in ("animation", "mixed") else "")\n        + f"Give {count} different stock-footage search terms in English (1 to 3 words each) for visuals that "\n        "match this topic. Avoid graphic violence. Output ONLY the terms, comma-separated."\n    )\n    try:\n        text = generate_text(ai_client, prompt, models)\n        terms = [t.strip().strip(\'"\').strip() for t in text.replace("\\n", ",").split(",") if t.strip()]\n    except Exception as e:\n        print(f"[Stock footage] Could not get search terms from Gemini ({e}); using the channel niche.")\n        terms = []\n    return with_generic_terms(terms, profile)[:count]\n\n\ndef with_generic_terms(terms, profile):\n    fallback = [w for w in profile.get("niche", "").replace(",", " ").split() if len(w) > 3]\n    return list(dict.fromkeys(terms + fallback + ["city", "nature", "people", "sky", "abstract"]))\n\n\ndef topic_fallback(item, profile):\n    """Footage terms Gemini wrote alongside the script, topped up with generic ones."""\n    return with_generic_terms(list(item.get("topic_terms") or []), profile)[:5]\n\n\nTERM_PAIR_RULE = (\n    "two English stock-footage search terms (1 to 4 words each) for visuals that show what THAT part is talking "\n    "about: first the most specific match, then a more generic backup that stock sites are sure to have (people, "\n    "places, objects, animals, maps, flags, actions). "\n)\n\n\ndef footage_rules(profile):\n    """Rules every footage term follows, shared by the script request and the per-scene request.\n\n    News channels may name public figures, countries and landmarks in the specific term (stock sites have little\n    footage of named people, so the generic backup is tried next). Kids channels never name real people.\n    """\n    kids = profile.get("made_for_kids")\n    return (\n        ("Never use names of real people. The audience is young children, so keep every term child-friendly. "\n         if kids else\n         "When the part is about a specific person (a head of state, minister or other government representative), "\n         "country, military unit, ship, weapon, place or event, the first term names it in 1 to 3 words so real "\n         "footage of it can be found, e.g. \'Zelensky\', \'Narendra Modi\', \'USS Gerald Ford\', \'NATO summit\', \'Kremlin\'. ")\n        + ("Some clips will be cartoon animation, so terms like \'cartoon cat\' work well. "\n           if profile.get("footage_style") in ("animation", "mixed") else "")\n        + "Avoid graphic violence."\n    )\n\n\ndef parse_scene_hints(text):\n    """\'a | b ; c | d ; e | f\' -> [[a, b], [c, d], [e, f]]."""\n    hints = []\n    for part in text.split(";"):\n        options = [t.strip().strip(\'"\') for t in part.split("|") if t.strip().strip(\'"\')]\n        if options:\n            hints.append(options[:2])\n    return hints\n\n\ndef hinted_terms(hints, scenes, item, profile):\n    """Spread the script\'s hints over the scenes in order, each with one topic term as a last resort."""\n    fallback = topic_fallback(item, profile)\n    return [hints[i * len(hints) // len(scenes)] + [fallback[i % len(fallback)]] for i in range(len(scenes))]\n\n\ndef scene_terms(ai_client, scenes, item, profile, models):\n    """For each scene, [specific term, generic backup term] describing what that scene\'s narration actually says."""\n    if item.get("scene_hints") and item.get("format") != "long":\n        # Shorts: the script request already chose terms for the opening, middle and end of the narration\n        return hinted_terms(item["scene_hints"], scenes, item, profile)\n    numbered = "\\n".join(f"{i + 1}. {scene[\'text\'][:400]}" for i, scene in enumerate(scenes))\n    prompt = (\n        f"A narrated video about: {item[\'original_title\']}\\n"\n        f"Channel niche: {profile.get(\'niche\', \'\')}\\n"\n        + "For EACH numbered scene below, give " + TERM_PAIR_RULE + footage_rules(profile)\n        + f"\\nReply with exactly {len(scenes)} lines in the form \'number. specific term | backup term\' and nothing "\n        f"else.\\n\\n{numbered}"\n    )\n    terms = {}\n    try:\n        for line in generate_text(ai_client, prompt, models).splitlines():\n            number, _, rest = line.partition(".")\n            options = [t.strip().strip(\'"\') for t in rest.split("|") if t.strip()]\n            if number.strip().isdigit() and options:\n                terms[int(number) - 1] = options[:2]\n    except Exception as e:\n        print(f"[Stock footage] Could not get scene terms from Gemini ({e}); using topic terms.")\n    fallback = []\n    if len(terms) < len(scenes):\n        # The script request already returned footage terms for the whole topic; only ask again if it didn\'t\n        fallback = topic_fallback(item, profile) if item.get("topic_terms") else \\\n            search_terms(ai_client, item, profile, models, 5)\n    return [terms.get(i) or [fallback[i % len(fallback)]] for i in range(len(scenes))]\n\n\n# ---------- Wikimedia Commons (real footage) ----------\n\ndef free_licence(name):\n    """Public domain, CC0 and CC BY can go in a monetised video with a credit; share-alike, non-commercial and\n    no-derivatives licences can\'t, so they are skipped."""\n    name = (name or "").upper().replace("-", " ")\n    if "PUBLIC DOMAIN" in name or name.startswith(("PD", "CC0", "CC ZERO")):\n        return True\n    return name.startswith("CC BY") and not any(f" {x} " in f" {name} " for x in ("SA", "NC", "ND"))\n\n\ndef key_words(term):\n    return [w for w in re.findall(r"[a-z0-9]+", term.lower()) if len(w) >= 3 and w not in SHOT_WORDS]\n\n\ndef relevant(title, term):\n    """Every name and subject word of the term must be in the clip\'s title (a Zelensky scene needs Zelensky)."""\n    words = key_words(term)\n    title = title.lower()\n    return bool(words) and all(w in title for w in words)\n\n\ndef commons_candidates(term, orientation="portrait", min_seconds=4):\n    """[(file title, video url, credit, duration seconds)] of freely licensed real footage matching the term."""\n    pace()\n    search = requests.get(COMMONS_API, headers=COMMONS_HEADERS, timeout=30, params={\n        "action": "query", "list": "search", "srsearch": f"{term} filetype:video", "srnamespace": 6,\n        "srlimit": 20, "format": "json"}).json()\n    titles = [h["title"] for h in search.get("query", {}).get("search", []) if relevant(h["title"], term)]\n    if not titles:\n        return []\n    pace()\n    info = requests.get(COMMONS_API, headers=COMMONS_HEADERS, timeout=30, params={\n        "action": "query", "titles": "|".join(titles[:20]), "prop": "videoinfo",\n        "viprop": "url|size|extmetadata|derivatives", "format": "json"}).json()\n    pages = {p["title"]: p for p in info.get("query", {}).get("pages", {}).values()}\n    target = TARGET_HEIGHT[orientation] if orientation == "landscape" else 720\n    found = []\n    for title in titles:\n        page = pages.get(title) or {}\n        details = (page.get("videoinfo") or [{}])[0]\n        meta = details.get("extmetadata", {})\n        licence = meta.get("LicenseShortName", {}).get("value", "")\n        if not free_licence(licence) or (details.get("duration") or 0) < min_seconds:\n            continue\n        versions = [d for d in details.get("derivatives", [])\n                    if d.get("type", "").startswith("video/webm") and (d.get("height") or 0) >= 360]\n        if not versions:\n            continue\n        best = min(versions, key=lambda d: abs(d["height"] - target))\n        artist = re.sub(r"<[^>]+>", "", meta.get("Artist", {}).get("value", ""))\n        artist = re.sub(r"\\s+", " ", html.unescape(artist)).strip() or "unknown"\n        credit = f"{artist[:60]}, {licence}, commons.wikimedia.org/?curid={page.get(\'pageid\')}"\n        found.append((title, best["src"], credit, float(details["duration"])))\n    return found\n\n\ndef commons_photo_candidates(term, orientation="portrait", min_width=800):\n    """[(file title, image url, credit)] of freely licensed real photos matching the term (when there is no video)."""\n    pace()\n    search = requests.get(COMMONS_API, headers=COMMONS_HEADERS, timeout=30, params={\n        "action": "query", "list": "search", "srsearch": f"{term} filetype:bitmap", "srnamespace": 6,\n        "srlimit": 20, "format": "json"}).json()\n    titles = [h["title"] for h in search.get("query", {}).get("search", []) if relevant(h["title"], term)]\n    if not titles:\n        return []\n    pace()\n    info = requests.get(COMMONS_API, headers=COMMONS_HEADERS, timeout=30, params={\n        "action": "query", "titles": "|".join(titles[:20]), "prop": "imageinfo",\n        "iiprop": "url|size|mime|extmetadata", "iiurlwidth": 1920, "format": "json"}).json()\n    pages = {p["title"]: p for p in info.get("query", {}).get("pages", {}).values()}\n    found = []\n    for title in titles:\n        page = pages.get(title) or {}\n        details = (page.get("imageinfo") or [{}])[0]\n        meta = details.get("extmetadata", {})\n        licence = meta.get("LicenseShortName", {}).get("value", "")\n        if (not free_licence(licence) or details.get("mime") not in ("image/jpeg", "image/png")\n                or (details.get("width") or 0) < min_width):\n            continue\n        artist = re.sub(r"<[^>]+>", "", meta.get("Artist", {}).get("value", ""))\n        artist = re.sub(r"\\s+", " ", html.unescape(artist)).strip() or "unknown"\n        credit = f"{artist[:60]}, {licence}, commons.wikimedia.org/?curid={page.get(\'pageid\')}"\n        found.append((title, details.get("thumburl") or details["url"], credit))\n    return found\n\n\ndef photo_clip(url, target, seconds, orientation="landscape"):\n    """Turn a photo into a moving shot lasting `seconds`: the whole photo (faces are never cropped) on a blurred copy\n    of itself, in the video\'s shape, slowly zooming in (the Ken Burns effect)."""\n    image_path = target + ".img"\n    for wait in (3, 6, 10, None):\n        response = requests.get(url, headers=COMMONS_HEADERS, timeout=60)\n        # Image servers (Pixabay\'s especially) refuse quick bursts for a few seconds: wait and try again\n        if response.status_code != 429 or wait is None:\n            break\n        time.sleep(wait)\n    response.raise_for_status()\n    with open(image_path, "wb") as f:\n        f.write(response.content)\n    frames = max(int(seconds * 30), 30)\n    exe = shutil.which("ffmpeg") or imageio_ffmpeg.get_ffmpeg_exe()\n    try:\n        w, h = (1080, 1920) if orientation == "portrait" else (1920, 1080)\n        layout = (f"split[a][b];[a]scale={w}:{h}:force_original_aspect_ratio=increase,crop={w}:{h},boxblur=25:2[bg];"\n                  f"[b]scale={w}:{h}:force_original_aspect_ratio=decrease[fg];[bg][fg]overlay=(W-w)/2:(H-h)/2,")\n        subprocess.run([exe, "-hide_banner", "-loglevel", "error", "-y", "-i", image_path, "-vf",\n                        layout + f"zoompan=z=\'min(zoom+0.0006,1.12)\':d={frames}:x=\'iw/2-(iw/zoom/2)\':"\n                        f"y=\'ih/2-(ih/zoom/2)\':s={w}x{h}:fps=30", "-frames:v", str(frames), "-c:v", "libx264",\n                        "-preset", "veryfast",\n                        "-crf", "23", "-pix_fmt", "yuv420p", target], check=True, timeout=300, capture_output=True)\n    finally:\n        os.remove(image_path)\n\n\ndef download_segment(url, target, start, seconds):\n    """Fetch only `seconds` of video from `start`: FFmpeg seeks over HTTP, so long videos aren\'t downloaded whole."""\n    exe = shutil.which("ffmpeg") or imageio_ffmpeg.get_ffmpeg_exe()\n    subprocess.run([exe, "-hide_banner", "-loglevel", "error", "-y", "-user_agent", COMMONS_HEADERS["User-Agent"],\n                    "-ss", f"{start:.2f}", "-i", url, "-t", f"{seconds:.2f}", "-an", "-c:v", "libx264",\n                    "-preset", "veryfast", "-crf", "23", target], check=True, timeout=300, capture_output=True)\n\n\ndef segment_start(duration, seconds):\n    """Skip the first quarter of longer videos (titles, intros) but stay inside the video."""\n    return max(0.0, min(duration * 0.25, duration - seconds - 0.5)) if duration > seconds + 1 else 0.0\n\n\ndef name_only(term):\n    """\'Narendra Modi summit\' -> \'Narendra Modi\': the first two words of a longer term, tried when the full term finds\n    nothing. Two-word terms aren\'t shortened (\'Western intelligence\' must not become \'Western\')."""\n    words = key_words(term)\n    return " ".join(words[:2]) if len(words) > 2 else ""\n\n\ndef real_photo(term, path, seconds, orientation, used_ids, cache):\n    """When there\'s no real video, a real photo of the person, place or event as a slow zoom; (title, credit) or None."""\n    key = ("photo", term)\n    if key not in cache:\n        cache[key] = commons_photo_candidates(term, orientation)\n        if not cache[key] and name_only(term):\n            cache[key] = commons_photo_candidates(name_only(term), orientation)\n    for title, url, credit in cache[key]:\n        if title in used_ids:\n            continue\n        used_ids.add(title)\n        photo_clip(url, path, seconds, orientation)\n        return title, credit\n    return None\n\n\ndef real_clip(term, path, seconds, orientation, used_ids, cache, uses):\n    """Download real footage for the term into path; returns (file title, credit), or None if nothing matches.\n\n    An unused video is preferred; if every match was already used, the best one is reused from a later moment,\n    which keeps the number of credits (and the description) short.\n    """\n    if term not in cache:\n        cache[term] = commons_candidates(term, orientation)\n        if not cache[term] and name_only(term):\n            cache[term] = commons_candidates(name_only(term), orientation)\n    if not cache[term]:\n        return None\n    fresh = [c for c in cache[term] if c[0] not in used_ids]\n    title, url, credit, duration = (fresh or cache[term])[0]\n    used_ids.add(title)\n    start = segment_start(duration, seconds) + uses.get(title, 0) * (seconds + 2)\n    if start + seconds > duration:\n        start = (start % max(duration - seconds, 1.0)) if duration > seconds else 0.0\n    uses[title] = uses.get(title, 0) + 1\n    download_segment(url, path, start, seconds)\n    return title, credit\n\n\ndef fetch_scene_clips(provider, api_key, terms, destination_dir, prefix, kids=False, style="any",\n                      orientation="portrait", lengths=None):\n    """One clip per scene, in scene order, trying each scene\'s terms in turn (specific first, then backup).\n\n    style "real": each scene\'s specific term is first looked up as real footage of the actual people, places and\n    events (Wikimedia Commons); stock footage is used when there is none. terms: [[term, ...] per scene];\n    lengths: seconds each scene lasts. Returns ([path or None per scene], [(site, credit)], [term used per scene]).\n    """\n    os.makedirs(destination_dir, exist_ok=True)\n    paths, credits, used_terms, used_ids, cache, real_cache, uses = [], [], [], set(), {}, {}, {}\n    for index, options in enumerate(terms):\n        wanted = clip_type(style, index)\n        path, chosen = None, None\n        if style == "real" and options:\n            target = os.path.join(destination_dir, f"{prefix}_scene{index + 1:03d}{REAL_SUFFIX}")\n            scene_seconds = lengths[index] if lengths and index < len(lengths) else 8\n            try:\n                seconds = min(max(scene_seconds + 1, 4), 30)\n                got = real_clip(options[0], target, seconds, orientation, used_ids, real_cache, uses)\n                kind = "real footage"\n                if not got:\n                    # No video of it: a real photo of the person, place or event, slowly zooming\n                    got = real_photo(options[0], target, seconds, orientation, used_ids, real_cache)\n                    kind = "real photo"\n                if got:\n                    path, chosen = target, options[0]\n                    credits.append((COMMONS_SITE, got[1]))\n                    print(f"[Stock footage] Scene {index + 1}: \'{options[0]}\' -> {kind}: {got[0][5:75]}")\n            except (requests.RequestException, subprocess.SubprocessError, OSError, ValueError, KeyError) as e:\n                print(f"[Stock footage] Scene {index + 1}: real footage for \'{options[0]}\' failed "\n                      f"({type(e).__name__}); using stock footage.")\n                path = None\n        try:\n            for term in ([] if path else options):\n                for video_type in ([wanted, None] if wanted else [None]):\n                    key = (term, video_type)\n                    if key not in cache:\n                        cache[key] = with_retries(\n                            lambda: CANDIDATES[provider](api_key, term, kids, video_type, orientation))\n                    pool = [c for c in cache[key] if c[0] not in used_ids]\n                    if pool:\n                        clip_id, url, credit = pool[0]\n                        used_ids.add(clip_id)\n                        path = os.path.join(destination_dir, f"{prefix}_scene{index + 1:03d}.mp4")\n                        with_retries(lambda: download_file(url, path))\n                        credits.append((PROVIDERS[provider]["name"], credit))\n                        chosen = term\n                        print(f"[Stock footage] Scene {index + 1}: \'{term}\' -> {PROVIDERS[provider][\'name\']} "\n                              f"video {clip_id}")\n                        break\n                if not path and provider == "pixabay" and style in ("animation", "mixed"):\n                    # No video really shows it: a matching cartoon drawing, gently zooming, before trying the\n                    # next (more generic) term\n                    key = ("illustration", term)\n                    if key not in cache:\n                        cache[key] = with_retries(lambda: pixabay_illustrations(api_key, term, kids))\n                    seconds = lengths[index] + 1 if lengths and index < len(lengths) else 8\n                    target = os.path.join(destination_dir, f"{prefix}_scene{index + 1:03d}.mp4")\n                    # Pixabay\'s image server sometimes refuses one picture for a while: try a few matching ones\n                    for image_id, url, credit in [c for c in cache[key] if c[0] not in used_ids][:4]:\n                        used_ids.add(image_id)\n                        try:\n                            photo_clip(url, target, min(max(seconds, 3), 30), orientation)\n                        except (requests.RequestException, subprocess.SubprocessError):\n                            continue\n                        path, chosen = target, term\n                        credits.append(("Pixabay", credit))\n                        print(f"[Stock footage] Scene {index + 1}: \'{term}\' -> Pixabay cartoon illustration "\n                              f"{image_id[3:]}")\n                        break\n                if path:\n                    break\n        except requests.RequestException as e:\n            print(f"[Stock footage] Scene {index + 1} ({\' / \'.join(options)}) failed: {safe_error(e, api_key)}")\n            path = None\n        if not path:\n            print(f"[Stock footage] Scene {index + 1}: no clip for {\' / \'.join(options)}; "\n                  "a neighbouring clip will be reused.")\n        paths.append(path)\n        used_terms.append(chosen)\n    return paths, credits, used_terms\n\n\ndef download_file(url, target):\n    with requests.get(url, stream=True, timeout=180) as response:\n        response.raise_for_status()\n        with open(target, "wb") as f:\n            for chunk in response.iter_content(chunk_size=1 << 20):\n                f.write(chunk)\n\n\n# ---------- Pexels ----------\n\ndef pick_file(video, orientation="portrait"):\n    """Pexels: choose the MP4 rendition closest to the target height without going below 720p."""\n    files = [f for f in video.get("video_files", [])\n             if f.get("file_type") == "video/mp4" and f.get("height") and f.get("link")]\n    usable = [f for f in files if min(f["height"], f.get("width") or f["height"]) >= 720] or files\n    target = TARGET_HEIGHT[orientation]\n    return min(usable, key=lambda f: abs(f["height"] - target)) if usable else None\n\n\ndef pexels_candidates(api_key, term, kids, video_type, orientation):\n    # Pexels has no animation filter, so video_type is ignored here\n    params = {"query": term, "orientation": orientation, "size": "medium", "per_page": 30}\n    for url in PEXELS_URLS:\n        pace()\n        response = requests.get(url, headers={"Authorization": api_key}, params=params, timeout=30)\n        if response.status_code == 404:\n            continue\n        response.raise_for_status()\n        return [(v["id"], pick_file(v, orientation)["link"], v.get("user", {}).get("name", "Pexels"))\n                for v in response.json().get("videos", []) if v.get("duration", 0) >= 3 and pick_file(v, orientation)]\n    return []\n\n\n# ---------- Pixabay ----------\n\ndef pick_rendition(renditions, orientation="portrait"):\n    """Pixabay: pick the version that best fills the output frame after cropping, within the size cap."""\n    usable = [r for r in renditions.values() if r.get("url") and r.get("height")]\n    if not usable:\n        return None\n    portrait_clip = any(r["height"] > r["width"] for r in usable)\n    if orientation == "landscape" or portrait_clip:\n        # Already the right shape (or portrait for a Short): closest to the target height\n        target = TARGET_HEIGHT[orientation]\n        return min(usable, key=lambda r: abs(r["height"] - target))\n    # Landscape clip for a vertical Short: the tallest version under the cap keeps the centre crop sharp\n    small_enough = [r for r in usable if 0 < r.get("size", 0) <= MAX_DOWNLOAD_BYTES] or usable\n    return max(small_enough, key=lambda r: r["height"])\n\n\ndef tags_match(tags, term):\n    """True if a clip\'s tags share a SUBJECT word with the search term (allowing plurals and word endings).\n\n    Style words ("cartoon", "funny", "cute"...) don\'t count: a clip tagged only "cartoon" doesn\'t show a\n    "cartoon turtle". They are used only when the term has nothing else.\n    """\n    words = key_words(term)\n    if not words:\n        return True\n    subjects = [w for w in words if w not in STYLE_WORDS] or words\n    tag_words = re.findall(r"[a-z0-9]+", tags.lower())\n    return any(t[:5] == w[:5] if min(len(t), len(w)) >= 5 else t == w for w in subjects for t in tag_words)\n\n\ndef pixabay_illustrations(api_key, term, kids):\n    """[(id, image url, artist)] of Pixabay cartoon illustrations whose tags match the term\'s subject."""\n    pace()\n    params = {"key": api_key, "q": term[:100], "image_type": "illustration", "per_page": 30, "order": "popular",\n              "safesearch": "true" if kids else "false"}\n    response = requests.get(PIXABAY_IMAGES_URL, params=params, timeout=30)\n    response.raise_for_status()\n    return [(f"img{h[\'id\']}", h.get("largeImageURL") or h["webformatURL"], h.get("user", "Pixabay"))\n            for h in response.json().get("hits", [])\n            if tags_match(h.get("tags", ""), term) and (h.get("imageWidth") or 0) >= 1000]\n\n\ndef pixabay_candidates(api_key, term, kids, video_type, orientation):\n    params = {"key": api_key, "q": term[:100], "per_page": 30, "order": "popular",\n              "safesearch": "true" if kids else "false"}\n    if video_type in ("animation", "film"):\n        params["video_type"] = video_type\n    pace()\n    response = requests.get(PIXABAY_URL, params=params, timeout=30)\n    response.raise_for_status()\n    # Pixabay ranks popular clips even when they don\'t match; keep only clips whose tags share a word with the term\n    hits = [h for h in response.json().get("hits", []) if h.get("duration", 0) >= 3 and tags_match(h.get("tags", ""), term)]\n\n    def is_portrait(hit):\n        medium = hit["videos"].get("medium", {})\n        return medium.get("height", 0) > medium.get("width", 1)\n\n    # Prefer clips that already match the output shape; others are centre-cropped by the editor\n    hits.sort(key=lambda h: 0 if is_portrait(h) == (orientation == "portrait") else 1)\n    found = []\n    for hit in hits:\n        rendition = pick_rendition(hit["videos"], orientation)\n        if rendition:\n            found.append((hit["id"], rendition["url"], hit.get("user", "Pixabay")))\n    return found\n\n\nCANDIDATES = {"pexels": pexels_candidates, "pixabay": pixabay_candidates}\n\n\ndef clip_type(style, index):\n    """footage_style -> Pixabay video_type for the index-th clip ("mixed" alternates cartoon and real)."""\n    if style == "mixed":\n        return "animation" if index % 2 == 0 else "film"\n    if style == "real":\n        return "film"\n    return style if style in ("animation", "film") else None\n\n\ndef fetch_clips(provider, api_key, terms, destination_dir, prefix, kids=False, style="any",\n                orientation="portrait", clips_per_term=1):\n    """Download clips_per_term clips for each search term. Returns (file paths, contributor credits).\n\n    Each term is searched once and several clips are taken from its results, to keep API requests low.\n    """\n    os.makedirs(destination_dir, exist_ok=True)\n    paths, credits, used_ids, cache = [], [], set(), {}\n\n    def candidates(term, video_type):\n        if (term, video_type) not in cache:\n            cache[(term, video_type)] = with_retries(\n                lambda: CANDIDATES[provider](api_key, term, kids, video_type, orientation))\n        return cache[(term, video_type)]\n\n    def download(url, target):\n        with requests.get(url, stream=True, timeout=180) as response:\n            response.raise_for_status()\n            with open(target, "wb") as f:\n                for chunk in response.iter_content(chunk_size=1 << 20):\n                    f.write(chunk)\n\n    index = 0\n    for term in terms:\n        for _ in range(clips_per_term):\n            wanted = clip_type(style, index)\n            try:\n                pool = [c for c in candidates(term, wanted) if c[0] not in used_ids]\n                if not pool and wanted:\n                    # e.g. no cartoon clip for this term: take any kind of clip instead\n                    pool = [c for c in candidates(term, None) if c[0] not in used_ids]\n            except requests.RequestException as e:\n                print(f"[Stock footage] {PROVIDERS[provider][\'name\']} search failed for \'{term}\': "\n                      f"{safe_error(e, api_key)}")\n                break\n            if not pool:\n                print(f"[Stock footage] No more clips for \'{term}\'.")\n                break\n            clip_id, url, credit = pool[0]\n            used_ids.add(clip_id)\n            index += 1\n            target = os.path.join(destination_dir, f"{prefix}_clip{index}.mp4")\n            try:\n                with_retries(lambda: download(url, target))\n            except requests.RequestException as e:\n                print(f"[Stock footage] Download failed for {PROVIDERS[provider][\'name\']} video {clip_id}: "\n                      f"{safe_error(e, api_key)}")\n                continue\n            paths.append(target)\n            credits.append(credit)\n            print(f"[Stock footage] \'{term}\' -> {PROVIDERS[provider][\'name\']} video {clip_id} by {credit}")\n    return paths, credits\n',
    'agents/agent_1_scout.py': 'import os\nimport re\nimport html\nimport json\nimport random\nimport unicodedata\nfrom datetime import datetime, timedelta, timezone\n\nimport requests\nfrom googleapiclient.discovery import build\nfrom googleapiclient.errors import HttpError\n\nfrom agents.agent_8_analyst import order_phrases\nfrom agents.inbox import boosted_phrases, waiting_requests\n\n# YouTube\'s relevanceLanguage codes, so results favour videos in the channel\'s narration language\nLANGUAGE_CODES = {"English": "en", "Hindi": "hi", "Telugu": "te"}\n# Don\'t reuse a source channel that supplied any of this channel\'s last N videos (unless nothing else is left)\nRECENT_SOURCES_WINDOW = 5\n# Letters of each narration language\'s own script; a source title written in another script is another audience\nSCRIPTS = {"Hindi": (0x0900, 0x097F), "Telugu": (0x0C00, 0x0C7F)}\n# Everyday Hindi words that rarely appear in English titles; two or more mark a Hinglish video\nHINGLISH_WORDS = {"hai", "hain", "ke", "ki", "ka", "ko", "se", "mein", "aur", "kya", "nahi", "wala", "wali", "wale",\n                  "gaya", "gayi", "bhi", "kahani", "kahaniyan", "bachpan", "bachpana", "dost", "pani", "jadu", "jaadu",\n                  "bacche", "bachon", "masti", "apna", "apni", "hum", "tum", "kaise", "kyun", "ghar", "gaon"}\n\n# A title naming its language ("Tamil Kids Story") is for that language\'s audience\nOTHER_LANGUAGES = {"hindi", "telugu", "tamil", "bengali", "bangla", "urdu", "malayalam", "kannada", "marathi",\n                   "gujarati", "punjabi", "odia", "arabic", "indonesian", "spanish", "portuguese"}\n\n\n# Hashtags that say nothing about the topic; YouTube treats piles of them as spam\nGENERIC_HASHTAGS = {"#shorts", "#short", "#viral", "#trending", "#trend", "#youtube", "#youtubeshorts", "#ytshorts",\n                    "#fyp", "#foryou", "#foryoupage", "#explore", "#explorepage", "#viralvideo", "#viralshorts",\n                    "#reels", "#subscribe", "#like", "#shortsfeed", "#shortvideo", "#shortsvideo", "#new", "#video",\n                    "#usashorts", "#viralshort", "#trendingshorts", "#feed", "#reel"}\nTRENDING_POOL = 15\nTRENDING_KEEP = 8\n# Search phrases handed to the script AI and the upload tags: rising videos\' keyword tags and YouTube\'s autocomplete\nKEYWORDS_KEEP = 10\nSUGGESTIONS_KEEP = 8\n\n\ndef trending_hashtags(videos, now=None):\n    """The hashtags the fastest-rising videos on a search use, weighted by their views per hour.\n\n    videos: [(video details from videos.list, views per hour)] of same-language sources. Generic tags, other\n    channels\' names and tags not written in Latin letters are left out.\n    """\n    weights, spelling = {}, {}\n    for video, speed in sorted(videos, key=lambda v: -v[1])[:TRENDING_POOL]:\n        snippet = video["snippet"]\n        brand = re.sub(r"\\W", "", snippet.get("channelTitle", "").lower())\n        seen = set()\n        for tag in re.findall(r"#\\w+", f"{snippet.get(\'title\', \'\')} {snippet.get(\'description\', \'\')}"):\n            key = tag.lower()\n            other_script = not all(is_latin(c) for c in tag[1:] if c.isalpha())\n            if (key in seen or key in GENERIC_HASHTAGS or len(key) < 4 or other_script\n                    or (brand and (brand in key or key.lstrip("#") in brand))):\n                continue\n            seen.add(key)\n            weights[key] = weights.get(key, 0) + 1 + speed\n            spelling.setdefault(key, tag)\n    return [spelling[k] for k in sorted(weights, key=lambda k: -weights[k])[:TRENDING_KEEP]]\n\n\ndef trending_keywords(videos):\n    """The keyword tags (YouTube\'s hidden search tags) the fastest-rising videos use, weighted by views per hour.\n\n    Same pool and filters as trending_hashtags; single words and very long tags are left out, since search\n    phrases of 2 to 6 words are what viewers type.\n    """\n    weights, spelling = {}, {}\n    for video, speed in sorted(videos, key=lambda v: -v[1])[:TRENDING_POOL]:\n        snippet = video["snippet"]\n        brand = re.sub(r"\\W", "", snippet.get("channelTitle", "").lower())\n        for tag in dict.fromkeys(t.strip() for t in snippet.get("tags") or []):\n            key = " ".join(tag.lower().split())\n            if (not 2 <= len(key.split()) <= 6 or len(key) > 50 or "#" + key.replace(" ", "") in GENERIC_HASHTAGS\n                    or not all(is_latin(c) for c in key if c.isalpha())\n                    or (brand and brand in key.replace(" ", ""))):\n                continue\n            weights[key] = weights.get(key, 0) + 1 + speed\n            spelling.setdefault(key, key)\n    return [spelling[k] for k in sorted(weights, key=lambda k: -weights[k])[:KEYWORDS_KEEP]]\n\n\ndef search_suggestions(phrase, language="English"):\n    """What people type into YouTube search starting with this phrase (YouTube\'s autocomplete), or [].\n\n    Free and outside the YouTube Data API quota; it\'s an unofficial endpoint, so any failure just means no\n    suggestions.\n    """\n    words = re.sub(r"#\\w+", "", phrase).split()\n    # A long phrase gets few suggestions, so its first three words are asked too\n    queries = [" ".join(words)] + ([" ".join(words[:3])] if len(words) > 3 else [])\n    other_languages = OTHER_LANGUAGES - {language.lower()}\n    found = []\n    for query in filter(None, queries):\n        try:\n            reply = requests.get("https://suggestqueries.google.com/complete/search",\n                                 params={"client": "firefox", "ds": "yt", "q": query,\n                                         "hl": LANGUAGE_CODES.get(language, "en")}, timeout=10)\n            reply.raise_for_status()\n            suggestions = reply.json()[1]\n        except Exception as e:\n            print(f"[Agent 1: Scout] No search suggestions for \'{query}\' ({str(e)[:80]})")\n            continue\n        # "... in hindi" or "... news tamil" is another language\'s audience\n        found += [s for s in suggestions if isinstance(s, str) and s.lower() not in queries\n                  and not set(s.lower().split()) & other_languages]\n        if len(found) >= SUGGESTIONS_KEEP // 2:\n            break\n    return list(dict.fromkeys(found))[:SUGGESTIONS_KEEP]\n\n\ndef is_latin(char):\n    """Latin letters, including accented ones and the \'bold\' or \'italic\' maths letters used in fancy titles."""\n    return ord(char) < 0x250 or unicodedata.name(char, "").startswith("MATHEMATICAL")\n\n\ndef views_per_hour(video, now=None):\n    """How fast a video is gaining views: views since upload divided by hours since upload (at least 1)."""\n    published = datetime.fromisoformat(video["snippet"]["publishedAt"].replace("Z", "+00:00"))\n    hours = max(((now or datetime.now(timezone.utc)) - published).total_seconds() / 3600, 1)\n    return int(video.get("statistics", {}).get("viewCount", 0)) / hours\n\n\ndef language_matches(video, language):\n    """True or False if the source video is or isn\'t in the channel\'s language, None if it can\'t be told.\n\n    Uses the language the uploader set, then the writing script of the title: an English channel shouldn\'t take\n    topics from a Hindi video (a different audience, and its title is no use as a fallback title).\n    """\n    code = LANGUAGE_CODES.get(language)\n    snippet = video["snippet"]\n    declared = (snippet.get("defaultAudioLanguage") or snippet.get("defaultLanguage") or "").lower()\n    if code and declared and not declared.startswith("zxx") and declared.split("-")[0] != code:\n        return False\n    # Uploaders often leave the language as English, so the title is checked too\n    title = snippet.get("title", "")\n    letters = [c for c in title if c.isalpha()]\n    if not letters:\n        return None\n    if language in SCRIPTS:\n        low, high = SCRIPTS[language]\n        return any(low <= ord(c) <= high for c in letters) or None\n    # English: no words in another script (Devanagari, Telugu, Bengali...), and not Hindi written in English\n    # letters ("Hinglish"), spotted by its common words in the title and the start of the description\n    if sum(not is_latin(c) for c in letters) >= 3:\n        return False\n    words = set(re.findall(r"[a-z]+", f"{title} {snippet.get(\'description\', \'\')[:300]}".lower()))\n    title_words = set(re.findall(r"[a-z]+", title.lower()))\n    return len(words & HINGLISH_WORDS) < 2 and not title_words & OTHER_LANGUAGES\n\nclass TrendScoutAgent:\n    def __init__(self, config, instructions):\n        self.config = config\n        self.instructions = instructions\n        self.active_key = config["active_profile"]\n        self.profile = config["profiles"][self.active_key]\n        self.manifest_path = config["storage_paths"]["manifest_file"]\n        self.search_cache = {}\n        self.suggestion_cache = {}\n        self.out_of_searches = False\n\n        api_key = os.getenv("YOUTUBE_API_KEY")\n        if not api_key:\n            raise ValueError("Missing YOUTUBE_API_KEY in .env file.")\n        self.youtube = build("youtube", "v3", developerKey=api_key)\n\n    def search(self, query, published_after):\n        # Cached per run: retries reuse the same results instead of spending more of the daily search quota\n        if query not in self.search_cache:\n            long_form = self.profile.get("format") == "long"\n            params = dict(\n                part="snippet",\n                # Long videos take their topics from longer trending videos (4 to 20 minutes)\n                q=query.replace("#shorts", "").strip() if long_form else query,\n                type="video",\n                videoDuration="medium" if long_form else "short",\n                order="viewCount",\n                publishedAfter=published_after,\n                maxResults=50,  # same quota cost as 1, and leaves room to skip used or repeated sources\n            )\n            language = LANGUAGE_CODES.get(self.profile.get("language", "English"))\n            if language:\n                params["relevanceLanguage"] = language\n            if self.out_of_searches:\n                return []\n            try:\n                found = self.youtube.search().list(**params).execute().get("items", [])\n            except HttpError as e:\n                if e.resp.status not in (403, 429) or "quota" not in str(e).lower():\n                    raise\n                # YouTube\'s 100 searches a day are used up: carry on with the videos already found or finished\n                print("[Agent 1: Scout] YouTube\'s daily search limit is used up (it resets at midnight Pacific "\n                      "time); no new topics this run.")\n                self.out_of_searches = True\n                return []\n            self.search_cache[query] = self.rank(found)\n        return self.search_cache[query]\n\n    def suggestions(self, query):\n        # Cached per run, like the searches\n        if query not in self.suggestion_cache:\n            self.suggestion_cache[query] = search_suggestions(query, self.profile.get("language", "English"))\n        return self.suggestion_cache[query]\n\n    def rank(self, items):\n        """Rising videos first (views per hour), in the channel\'s language first; costs 1 quota unit per 50 videos."""\n        details = {}\n        ids = [i["id"]["videoId"] for i in items]\n        for start in range(0, len(ids), 50):\n            response = self.youtube.videos().list(part="snippet,statistics", id=",".join(ids[start:start + 50])).execute()\n            details.update({v["id"]: v for v in response.get("items", [])})\n        language = self.profile.get("language", "English")\n        ranked, pool = [], []\n        for item in items:\n            video = details.get(item["id"]["videoId"])\n            if not video:\n                continue\n            item["views_per_hour"] = round(views_per_hour(video), 1)\n            item["language_ok"] = language_matches(video, language) is not False\n            ranked.append(item)\n            if item["language_ok"]:\n                pool.append((video, item["views_per_hour"]))\n        tags, keywords = trending_hashtags(pool), trending_keywords(pool)\n        for item in ranked:\n            item["trending_hashtags"] = tags\n            item["trending_keywords"] = keywords\n        return sorted(ranked, key=lambda i: (not i["language_ok"], -i["views_per_hour"]))\n\n    def run(self, limit=None):\n        """Add up to `limit` new videos (default: the channel\'s videos per day) to the manifest.\n\n        Picks rotate across the search phrases, take at most one video per source channel, skip sources\n        used for this channel recently, and never use channels listed in exclude_sources.\n        """\n        print(f"\\n[Agent 1: Scout] Searching trending videos for profile: {self.active_key}...")\n        published_after = (datetime.now(timezone.utc) - timedelta(days=self.profile.get("lookback_days", 5))).isoformat()\n\n        existing_trends = []\n        if os.path.exists(self.manifest_path):\n            with open(self.manifest_path, "r", encoding="utf-8") as f:\n                try:\n                    existing_trends = json.load(f)\n                except json.JSONDecodeError:\n                    existing_trends = []\n\n        existing_ids = {item["video_id"] for item in existing_trends}\n        mine = [item for item in existing_trends if item.get("profile") == self.active_key]\n        recent_sources = {item.get("original_creator", "").lower() for item in mine[-RECENT_SOURCES_WINDOW:]}\n        excluded = {name.lower() for name in self.profile.get("exclude_sources") or []}\n        max_per_run = limit or self.profile["max_videos_per_run"]\n\n        # Phrases whose videos got the most views come first; untried or long-unused phrases are tried again.\n        # The owner\'s recent Telegram requests lead for a few days, so the next videos follow that trend too\n        queries = list(dict.fromkeys(boosted_phrases(self.active_key) + order_phrases(\n            self.profile["search_queries"],\n            [i for i in mine if i.get("format", "short") == self.profile.get("format", "short")])))\n        # Phrases are searched only when the round-robin reaches them (each search costs 1 of YouTube\'s 100 a\n        # day), so a run that needs one or two topics usually searches just one or two phrases\n\n        new_items, used_sources = [], set()\n        # Videos the owner asked for in Telegram take the first slots (a shared example, or a topic)\n        for request in waiting_requests(self.active_key, self.profile.get("format", "short"), existing_ids):\n            if len(new_items) >= max_per_run:\n                break\n            new_items.append(self.request_entry(request))\n            existing_ids.add(request["video_id"])\n        # Rising, same-language sources first; a recently used source or another language only if nothing else\n        for allow_recent, allow_language in ((False, False), (True, False), (True, True)):\n            # Round-robin: best unused video from phrase 1, then phrase 2, ... until enough are picked\n            progress = True\n            while len(new_items) < max_per_run and progress:\n                progress = False\n                for query in queries:\n                    if len(new_items) >= max_per_run:\n                        break\n                    pick = self.next_candidate(self.search(query, published_after), existing_ids, used_sources,\n                                               excluded,\n                                               set() if allow_recent else recent_sources, allow_language)\n                    if pick:\n                        new_items.append(self.entry(pick, query))\n                        existing_ids.add(pick["id"]["videoId"])\n                        used_sources.add(pick["snippet"]["channelTitle"].lower())\n                        progress = True\n            if len(new_items) >= max_per_run:\n                break\n\n        all_trends = existing_trends + new_items\n        with open(self.manifest_path, "w", encoding="utf-8") as f:\n            json.dump(all_trends, f, indent=4, ensure_ascii=False)\n\n        sources = ", ".join(f"{i[\'original_creator\']} ({i[\'genre\']})" for i in new_items) or "none"\n        print(f"[Agent 1: Scout] Added {len(new_items)} new trending videos. Sources: {sources}")\n\n    @staticmethod\n    def next_candidate(items, existing_ids, used_sources, excluded, recent_sources, allow_language=True):\n        for item in items:\n            source = item["snippet"]["channelTitle"].lower()\n            if (item["id"]["videoId"] in existing_ids or source in used_sources\n                    or source in excluded or source in recent_sources\n                    or not (allow_language or item.get("language_ok", True))):\n                continue\n            return item\n        return None\n\n    def request_entry(self, request):\n        """A manifest entry for one of the owner\'s Telegram requests (agents/inbox.py)."""\n        phrase = (request.get("search_phrases") or [request.get("topic") or request.get("title", "")])[0]\n        source = {"id": {"videoId": request["video_id"]},\n                  "snippet": {"title": request.get("title") or request.get("topic", ""),\n                              "description": request.get("description", ""),\n                              "channelTitle": request.get("creator", "")}}\n        entry = self.entry(source, phrase)\n        entry.update(request_id=request["id"], source_url=request.get("link") or "",\n                     # What to make: the topic, and for a shared example what makes that video work\n                     reference_notes=request.get("notes", ""), request_kind=request.get("kind"))\n        print(f"[Agent 1: Scout] Making the owner\'s request {request[\'id\']}: {entry[\'original_title\']}")\n        return entry\n\n    def entry(self, item, query):\n        vid_id = item["id"]["videoId"]\n        entry_format = self.profile.get("format", "short")\n        minutes = str(self.profile.get("long", {}).get("minutes", 6))\n        if entry_format == "long":\n            # A range such as "5-6" gives every long video its own length, never longer than the upper bound\n            low, _, high = minutes.partition("-")\n            low, high = int(low), int(high or low)\n            target_seconds = random.randint(low * 60, high * 60 - 20) if high > low else low * 60 - 10\n            max_seconds = high * 60 - 5  # leaves room for the end card within the upper limit\n        else:\n            target_seconds = self.profile.get("target_duration_seconds", 30)\n            max_seconds = int(target_seconds * 1.2)\n        return {\n            "video_id": vid_id,\n            "profile": self.active_key,\n            "format": entry_format,\n            "target_seconds": target_seconds,\n            "max_seconds": max_seconds,\n            "genre": query,\n            "source_views_per_hour": item.get("views_per_hour"),\n            # What the fastest-rising videos on this search are tagged with right now\n            "trending_hashtags": item.get("trending_hashtags") or [],\n            # Search phrases viewers type for this niche: YouTube\'s autocomplete, then rising videos\' keyword tags\n            "search_keywords": list(dict.fromkeys(self.suggestions(query) + (item.get("trending_keywords") or []))),\n            # The search API returns HTML-escaped text (e.g. &#39; and &amp;)\n            "original_title": html.unescape(item["snippet"]["title"]),\n            "original_description": html.unescape(item["snippet"]["description"]),\n            "original_creator": html.unescape(item["snippet"]["channelTitle"]),\n            "source_url": f"https://www.youtube.com/watch?v={vid_id}",\n            "discovered_at": datetime.now(timezone.utc).isoformat(),\n            "status": "discovered",\n            "raw_video_path": None,\n            "voiceover_path": None,\n            "generated_script": None,\n            "edited_video_path": None,\n            "uploaded_youtube_id": None,\n            "notified_telegram": False\n        }\n',
    'agents/agent_2_downloader.py': 'import os\nimport json\nimport shutil\nimport yt_dlp\n\nfrom brain import item_matches\n\ndef ffmpeg_location():\n    # yt-dlp needs FFmpeg to merge video and audio; fall back to the copy bundled with MoviePy when none is installed\n    if shutil.which("ffmpeg"):\n        return None\n    try:\n        import imageio_ffmpeg\n        return imageio_ffmpeg.get_ffmpeg_exe()\n    except Exception:\n        return None\n\nclass DownloaderAgent:\n    """Gets footage for each discovered topic.\n\n    footage.source in BRAIN.md: "stock" downloads free Pexels clips matching the topic (works everywhere);\n    "youtube" downloads the trending video itself (laptop only: YouTube blocks downloads from cloud servers).\n    """\n    def __init__(self, manifest_path, download_destination_dir, config=None):\n        self.manifest_path = manifest_path\n        self.download_dir = download_destination_dir\n        self.config = config or {}\n        self.footage = self.config.get("footage") or {}\n\n    def run(self, active_profile):\n        print(f"\\n[Agent 2: Downloader] Checking manifest at {self.manifest_path}...")\n        with open(self.manifest_path, "r", encoding="utf-8") as f:\n            trends = json.load(f)\n\n        profile = self.config["profiles"][active_profile]\n        stock = self.footage.get("source", "stock") == "stock" or profile.get("format") == "long"\n        if stock:\n            from google import genai\n            from agents import stock_footage\n            provider, api_key = stock_footage.choose_provider(self.footage.get("provider", "auto"))\n            ai_client = genai.Client(api_key=os.getenv("GEMINI_API_KEY"))\n\n        # Stock footage is chosen after the script is narrated ("voiced"), one clip per scene of the script;\n        # re-used trending videos are downloaded straight after discovery\n        wanted_status = "voiced" if stock else "discovered"\n        for item in trends:\n            if item["status"] == wanted_status and item_matches(item, active_profile, profile):\n                vid_id = item["video_id"]\n                if stock:\n                    self.fetch_stock(item, stock_footage, provider, api_key, ai_client, profile)\n                else:\n                    self.download_source(item, vid_id)\n\n        with open(self.manifest_path, "w", encoding="utf-8") as f:\n            json.dump(trends, f, indent=4, ensure_ascii=False)\n\n    def fetch_stock(self, item, stock_footage, provider, api_key, ai_client, profile):\n        vid_id = item["video_id"]\n        if not provider:\n            print("[Agent 2: Downloader] No stock footage key: add PIXABAY_API_KEY (or PEXELS_API_KEY) "\n                  "to .env / GitHub secrets.")\n            item["status"] = "download_failed"\n            return\n        scenes = item.get("scenes") or [{"start": 0, "end": item.get("voice_seconds", 30), "text": item["original_title"]}]\n        orientation = "landscape" if item.get("format") == "long" else "portrait"\n        terms = stock_footage.scene_terms(ai_client, scenes, item, profile, self.config.get("ai_models"))\n        print(f"[Agent 2: Downloader] {len(scenes)} scenes for \'{item[\'original_title\'][:60]}\'")\n        try:\n            paths, credits, used_terms = stock_footage.fetch_scene_clips(\n                provider, api_key, terms, self.download_dir, f"stock_{vid_id}",\n                kids=profile.get("made_for_kids", False), style=profile.get("footage_style", "any"),\n                orientation=orientation, lengths=[s["end"] - s["start"] for s in scenes])\n        except Exception as e:\n            print(f"[Agent 2: Downloader] Stock footage failed for {vid_id}: {stock_footage.safe_error(e, api_key)}")\n            paths, credits, used_terms = [], [], []\n        # Sync report: what is said in each scene, and the footage shown with it\n        for scene, used in zip(scenes, used_terms):\n            words = " ".join(scene["text"].split()[:9])\n            print(f"   {int(scene[\'start\']) // 60}:{int(scene[\'start\']) % 60:02d}-{int(scene[\'end\']) // 60}:"\n                  f"{int(scene[\'end\']) % 60:02d}  shows \'{used or \'neighbouring clip\'}\'  while saying: {words}...")\n        if any(paths):\n            # A scene with no clip reuses the nearest earlier (or later) one, so every scene keeps its timing\n            filled, last = [], next(p for p in paths if p)\n            for path in paths:\n                last = path or last\n                filled.append(last)\n            item["footage_paths"] = filled\n            item["scene_terms"] = used_terms\n            item["footage_provider"] = provider\n            item["footage_credits"] = sorted({credit for site, credit in credits if site != stock_footage.COMMONS_SITE})\n            # Credits per site for the description: real footage (with licence and link) and stock footage\n            sources = {}\n            for site, credit in credits:\n                sources.setdefault(site, [])\n                if credit not in sources[site]:\n                    sources[site].append(credit)\n            item["footage_sources"] = sources\n            item["raw_video_path"] = filled[0]\n            item["status"] = "ready_to_edit"\n        else:\n            item["status"] = "download_failed"\n\n    def download_source(self, item, vid_id):\n        target_file = os.path.join(self.download_dir, f"raw_{vid_id}.mp4")\n        ydl_opts = {\n            "format": "bestvideo[ext=mp4][height<=1920]+bestaudio[ext=m4a]/best[ext=mp4]/best",\n            "outtmpl": target_file,\n            "merge_output_format": "mp4",\n            "quiet": True,\n            "no_warnings": True,\n            "noprogress": True\n        }\n        if ffmpeg_location():\n            ydl_opts["ffmpeg_location"] = ffmpeg_location()\n\n        try:\n            print(f"[Agent 2: Downloader] Downloading {item[\'source_url\']} -> {target_file}")\n            with yt_dlp.YoutubeDL(ydl_opts) as ydl:\n                ydl.download([item["source_url"]])\n\n            if os.path.exists(target_file):\n                item["raw_video_path"] = target_file\n                item["status"] = "downloaded"\n        except Exception as e:\n            print(f"[Agent 2: Downloader] Error downloading {vid_id}: {e}")\n            item["status"] = "download_failed"\n',
    'agents/agent_3_voiceover.py': 'import os\nimport re\nimport json\nimport asyncio\nimport edge_tts\nfrom google import genai\n\nfrom agents import expressive_voice\nfrom agents.ai import generate_text\nfrom agents.stock_footage import TERM_PAIR_RULE, footage_rules, parse_scene_hints\nfrom brain import item_matches\n\n# Roughly 150 spoken words per minute, a pace most listeners follow comfortably\nWORDS_PER_SECOND = 2.5\n# Scripts more than 20% over their target word count are shortened\nLENGTH_TOLERANCE = 1.2\n# Narration longer than the video\'s maximum length (times this factor) is shortened and narrated again\nDURATION_TOLERANCE = 1.0\n# Stock footage changes scene about this often in long videos (footage.long_scene_seconds in BRAIN.md);\n# Shorts use footage.clips_per_video scenes\nLONG_SCENE_SECONDS = 8\n\n\ndef stock_mode(config, profile):\n    """Stock-footage videos are scripted first, then footage is chosen to match each scene of the script."""\n    return (config.get("footage") or {}).get("source", "stock") == "stock" or profile.get("format") == "long"\n\n\ndef group_scenes(sentences, total_seconds, scene_seconds):\n    """Group timed sentences into scenes of about scene_seconds; each scene gets one stock clip.\n\n    sentences: [(start_seconds, text)]. Returns [{"start", "end", "text"}] covering 0..total_seconds.\n    """\n    if not sentences:\n        return [{"start": 0.0, "end": total_seconds, "text": ""}]\n    scenes, current = [], {"start": 0.0, "text": []}\n    for index, (start, text) in enumerate(sentences):\n        if current["text"] and start - current["start"] >= scene_seconds:\n            scenes.append({"start": current["start"], "end": start, "text": " ".join(current["text"])})\n            current = {"start": start, "text": []}\n        current["text"].append(text)\n    scenes.append({"start": current["start"], "end": total_seconds, "text": " ".join(current["text"])})\n    # Fold a very short final scene into the one before it\n    if len(scenes) > 1 and scenes[-1]["end"] - scenes[-1]["start"] < scene_seconds / 3:\n        last = scenes.pop()\n        scenes[-1]["end"], scenes[-1]["text"] = last["end"], scenes[-1]["text"] + " " + last["text"]\n    return scenes\n\n\nMETA_FIELDS = {"KEYWORD": "seo_keyword", "TITLE": "seo_title", "DESCRIPTION": "seo_description",\n               "HASHTAGS": "seo_hashtags", "KEYWORDS": "seo_keywords", "FOOTAGE": "topic_terms",\n               "SCENES": "scene_hints"}\n# Search phrases from the Scout shown to the AI (YouTube autocomplete first, then rising videos\' keyword tags)\nPROMPT_KEYWORDS = 12\n\n\ndef parse_script_reply(text):\n    """Split the AI\'s reply into (narration, {seo_title, seo_description, seo_hashtags, topic_terms, scene_hints}).\n\n    A field\'s value may continue on the following lines (some models list scenes or terms one per line). If the\n    reply ignores the layout, the whole reply is the narration and the publisher writes the title later.\n    """\n    head, marker, body = text.partition("SCRIPT:")\n    if not marker:\n        return text.strip(), {}\n    parts, field = {}, None\n    for line in head.splitlines():\n        label, colon, value = line.strip().lstrip("*# ").partition(":")\n        if colon and label.strip("* ").upper() in META_FIELDS:\n            field = META_FIELDS[label.strip("* ").upper()]\n            parts[field] = [value]\n        elif field and line.strip():\n            # A continuation line: drop list numbering or bullets such as "1." or "-"\n            parts[field].append(re.sub(r"^\\s*(?:\\d+[.)]|[-*•])\\s*", "", line))\n    joiners = {"scene_hints": " ; ", "topic_terms": ", ", "seo_keywords": ", "}\n    meta = {}\n    for field, values in parts.items():\n        value = joiners.get(field, " ").join(v.strip().strip("*").strip().strip(\'"\') for v in values if v.strip())\n        if value:\n            meta[field] = value\n    for field in ("topic_terms", "seo_keywords"):\n        if field in meta:\n            meta[field] = [t.strip().strip(\'"\') for t in meta[field].split(",") if t.strip()]\n    if "scene_hints" in meta:\n        meta["scene_hints"] = parse_scene_hints(meta["scene_hints"]) or None\n        if not meta["scene_hints"]:\n            del meta["scene_hints"]\n    return body.strip().strip("*").strip(), meta\n\n\nclass VoiceoverAgent:\n    def __init__(self, config, instructions):\n        self.config = config\n        self.instructions = instructions\n        self.active_key = config["active_profile"]\n        self.profile = config["profiles"][self.active_key]\n        self.paths = config["storage_paths"]\n        self.voice = self.profile.get("voice", "en-US-AndrewNeural")\n        self.voice_rate = self.profile.get("voice_rate", "-5%")\n\n        gemini_key = os.getenv("GEMINI_API_KEY")\n        if not gemini_key:\n            raise ValueError("Missing GEMINI_API_KEY in .env file.")\n        self.ai_client = genai.Client(api_key=gemini_key)\n\n    def generate_script(self, item):\n        target_seconds = item.get("target_seconds") or self.profile.get("target_duration_seconds", 30)\n        target_words = int(target_seconds * WORDS_PER_SECOND)\n        avoid_terms = self.profile.get("avoid_terms") or []\n        if item.get("format") == "long":\n            task = (\n                f"Task: Write an original, engaging narration script of about {target_words} words (about "\n                f"{round(target_seconds / 60)} minutes spoken) for a regular YouTube video, not a Short. Open with a "\n                "strong hook, then 3 to 5 clearly separated parts (a story with a beginning, middle and end, or an "\n                "explanation that builds step by step), keep a lively pace throughout, and end with a short recap and "\n                "a question inviting viewers to comment. Describe concrete, visual things (places, objects, animals, "\n                "people, actions) so matching footage can be shown for every sentence.\\n"\n            )\n        else:\n            task = (\n                f"Task: Write an original, high-retention narration script of about {target_words} words about this "\n                "topic for a YouTube Short: commentary, explanation, or a short funny story, whichever fits the "\n                "channel\'s tone and the master instructions.\\n"\n            )\n\n        prompt = (\n            f"Follow these master BRAIN instructions strictly:\\n{self.instructions}\\n\\n"\n            f"Profile: {self.active_key}\\n"\n            f"Channel Niche: {self.profile.get(\'niche\', self.active_key)}\\n"\n            f"Required Tone: {self.profile[\'tone\']}\\n"\n            f"Script Language: {self.profile.get(\'language\', \'English\')} (write in its native script)\\n"\n            f"Source Video Title: {item[\'original_title\']}\\n"\n            f"Source Video Context: {item[\'original_description\'][:300]}\\n\\n"\n            + task\n        )\n        notes = item.get("reference_notes")\n        if item.get("request_kind") == "example":\n            # The owner shared the source video in Telegram as an example to follow (agents/inbox.py)\n            prompt += ("The channel owner shared the source video as an example: make an original video like it. "\n                       + (f"What makes it work: {notes} " if notes else "")\n                       + "Follow its format, hook style and pacing, never its words, characters, music or footage.\\n")\n        elif item.get("request_kind") == "topic":\n            prompt += ("The channel owner asked for a video on this topic (the source title above)"\n                       + (f"; their wishes: {notes}" if notes else "") + ".\\n")\n        if avoid_terms:\n            prompt += f"Never use these words or topics: {\', \'.join(avoid_terms)}.\\n"\n        long = item.get("format") == "long"\n        keywords = (item.get("search_keywords") or [])[:PROMPT_KEYWORDS]\n        if keywords:\n            # Real search data from the Scout: what people type into YouTube search for this niche right now\n            prompt += f"What viewers search on YouTube for this niche right now: {\'; \'.join(keywords)}.\\n"\n        # Kids scripts carry the [SOUND] tags from the master instructions; they are removed before narration\n        brackets = "no brackets other than the sound tags" if self.profile.get("made_for_kids") else "no brackets"\n        prompt += (\n            f"Stay within {target_words} words; a little shorter is fine, longer is not. The narration must be "\n            f"only spoken text: no stage directions, {brackets}, no intro labels.\\n\\n"\n            # The upload title, keywords and footage ideas come from this same request, so each video costs one call\n            "Reply in exactly this layout:\\n"\n            "KEYWORD: the one search phrase (2 to 5 words, in the script language) a viewer would type to find this "\n            "video; use a phrase from the search list above when one fits the story, never one that doesn\'t\\n"\n            f"TITLE: a {\'click-worthy YouTube video\' if long else \'viral YouTube Short\'} title, at most "\n            f"{70 if long else 60} characters, no quotes, in the script language, with the KEYWORD (or its words) "\n            "in the first 3 to 5 words, written naturally\\n"\n            f"DESCRIPTION: a {3 if long else 2}-sentence SEO description in the script language whose first "\n            "sentence uses the KEYWORD naturally, with no credits, source names or keyword lists\\n"\n            "HASHTAGS: 5 hashtags separated by spaces that people actively search on YouTube for this topic right "\n            "now: 2 broad, popular ones for the niche and 3 specific to this story (no spaces inside a hashtag"\n            f"{\', do not use #shorts\' if long else \'\'})\\n"\n            "KEYWORDS: 6 more search phrases (2 to 5 words each, comma-separated) viewers might type for this exact "\n            "video: close variations of the KEYWORD and the story\'s main subject, only what the video is truly "\n            "about\\n"\n            "FOOTAGE: 5 English stock-footage search terms (1 to 3 words each, comma-separated) for visuals "\n            "that match the whole topic"\n            + (", child-friendly" if self.profile.get("made_for_kids") else "") + "\\n"\n        )\n        if not long:\n            # A Short has a few equal scenes, so footage for each is chosen here instead of in a second request\n            clips = int((self.config.get("footage") or {}).get("clips_per_video", 6))\n            prompt += (\n                f"SCENES: split the narration into {clips} equal parts in order and, for each part, give "\n                + TERM_PAIR_RULE + footage_rules(self.profile)\n                + f" Write them on this one line as \'specific | backup\' pairs separated by \' ; \' ({clips} pairs)\\n"\n            )\n        prompt += "SCRIPT:\\n<the narration>"\n\n        script, meta = parse_script_reply(generate_text(self.ai_client, prompt, self.config.get("ai_models")))\n        item.update(meta)\n        return self.fit_length(script, target_words)\n\n    def fit_length(self, script, target_words):\n        """Keep the video near its target length: Gemini sometimes writes far more than asked."""\n        limit = int(target_words * LENGTH_TOLERANCE)\n        if len(script.split()) <= limit:\n            return script\n        print(f"[Agent 3: Voiceover] Script is {len(script.split())} words (target {target_words}); shortening...")\n        try:\n            script = generate_text(self.ai_client, (\n                f"Shorten this narration script to at most {target_words} words. Keep the opening hook, the main "\n                "story or explanation, and the ending (recap and question). Same language and tone. Output ONLY "\n                f"the shortened narration text.\\n\\n{script}"\n            ), self.config.get("ai_models"))\n        except Exception as e:\n            print(f"[Agent 3: Voiceover] Could not shorten with Gemini ({e}); trimming instead.")\n        words = script.split()\n        if len(words) <= limit:\n            return script\n        # Last resort: cut at the final sentence ending before the limit\n        trimmed = " ".join(words[:limit])\n        cut = max(trimmed.rfind(mark) for mark in (". ", "! ", "? ", "। "))\n        return trimmed[:cut + 1] if cut > len(trimmed) // 2 else trimmed\n\n    def synthesize_voice(self, script_text, video_id):\n        """Narrate the script; returns (mp3 path, spoken seconds, [(sentence start seconds, sentence text)], sfx_cues)."""\n        out_mp3 = os.path.join(self.paths["audio_renders"], f"vo_{self.active_key}_{video_id}.mp3")\n        expression = self.profile.get("voice_expression", "off")\n        print(f"[Agent 3: Voiceover] Narrating video {video_id} with {self.voice} ({self.voice_rate}, "\n              f"{expression} expression)...")\n        if expression != "off":\n            try:\n                seconds, sentences, sfx_cues = expressive_voice.narrate(script_text, self.voice, self.voice_rate,\n                                                                        expression, out_mp3)\n                return out_mp3, seconds + 0.3, sentences, sfx_cues\n            except Exception as e:\n                print(f"[Agent 3: Voiceover] Expressive narration failed ({e}); narrating in one pass instead.")\n\n        async def narrate():\n            # Sound tags ([TADA]) are for the editor only; one-pass narration has no sound effects\n            communicate = edge_tts.Communicate(expressive_voice.strip_cues(script_text), self.voice,\n                                               rate=self.voice_rate,\n                                               boundary="SentenceBoundary")\n            sentences, end = [], 0.0\n            with open(out_mp3, "wb") as f:\n                async for chunk in communicate.stream():\n                    if chunk["type"] == "audio":\n                        f.write(chunk["data"])\n                    elif chunk["type"] == "SentenceBoundary":\n                        start = chunk["offset"] / 1e7\n                        sentences.append((start, chunk["text"]))\n                        end = max(end, start + chunk["duration"] / 1e7)\n            return sentences, end\n\n        sentences, end = asyncio.run(narrate())\n        return out_mp3, end + 0.5, sentences, []\n\n    def narrate_within_limit(self, item, script):\n        """Narrate, and if the spoken length runs past the video\'s maximum, shorten the script and narrate again."""\n        max_seconds = item.get("max_seconds")\n        vo_path, seconds, sentences, sfx_cues = self.synthesize_voice(script, item["video_id"])\n        if max_seconds and seconds > max_seconds * DURATION_TOLERANCE:\n            words = len(script.split())\n            # Aim for the video\'s target length (inside the allowed range), not just under the maximum\n            goal_seconds = min(item.get("target_seconds") or max_seconds, max_seconds)\n            target_words = int(words * goal_seconds / seconds)\n            print(f"[Agent 3: Voiceover] Narration is {seconds / 60:.1f} min, over the {max_seconds / 60:.1f} min "\n                  f"limit; shortening to about {target_words} words...")\n            script = self.fit_length(script, target_words) if words > target_words * LENGTH_TOLERANCE else script\n            if len(script.split()) > target_words:\n                script = " ".join(script.split()[:target_words])\n            vo_path, seconds, sentences, sfx_cues = self.synthesize_voice(script, item["video_id"])\n        return script, vo_path, seconds, sentences, sfx_cues\n\n    def run(self):\n        manifest_path = self.paths["manifest_file"]\n        with open(manifest_path, "r", encoding="utf-8") as f:\n            trends = json.load(f)\n\n        # Stock videos are scripted straight after discovery (footage is chosen afterwards to match the script);\n        # re-used trending videos are scripted after their download\n        stock = stock_mode(self.config, self.profile)\n        wanted_status = "discovered" if stock else "downloaded"\n        scene_seconds = float((self.config.get("footage") or {}).get("long_scene_seconds", LONG_SCENE_SECONDS))\n\n        for item in trends:\n            if item["status"] == wanted_status and item_matches(item, self.active_key, self.profile):\n                vid_id = item["video_id"]\n                try:\n                    script = self.generate_script(item)\n                    script, vo_path, seconds, sentences, sfx_cues = self.narrate_within_limit(item, script)\n                    item["generated_script"] = expressive_voice.strip_cues(script)\n                    item["voiceover_path"] = vo_path\n                    item["voice_seconds"] = round(seconds, 2)\n                    # When each sentence starts: the kids host\'s expressions follow these\n                    item["sentence_timings"] = [[round(start, 2), text] for start, text in sentences]\n                    # Where the kids channel\'s sound effects play ([[seconds, file]], from the script\'s [SOUND] tags)\n                    item["sfx_cues"] = [[at, sound] for at, sound in sfx_cues]\n                    if stock:\n                        if item.get("format") != "long":\n                            scene_seconds = seconds / int((self.config.get("footage") or {}).get("clips_per_video", 6))\n                        item["scenes"] = group_scenes(sentences, seconds, scene_seconds)\n                        print(f"[Agent 3: Voiceover] {seconds / 60:.1f} min of narration in {len(item[\'scenes\'])} scenes")\n                    item["status"] = "voiced"\n                except Exception as e:\n                    print(f"[Agent 3: Voiceover] Failed on {vid_id}: {e}")\n\n        with open(manifest_path, "w", encoding="utf-8") as f:\n            json.dump(trends, f, indent=4, ensure_ascii=False)\n',
    'agents/expressive_voice.py': '"""Expressive narration with edge-tts: each sentence gets its own speed, pitch and volume, with natural pauses.\n\nedge-tts reads a whole script in one even tone. Narrating sentence by sentence lets the hook start with energy,\nquestions rise, exclamations lift, plain sentences vary a little so the voice never drones, and the ending slows\ndown. The sentence audio is trimmed of silence and joined with pauses, which also gives exact sentence timings\nfor matching footage to the narration.\n\nvoice_expression in questions.yaml: "lively" (kids), "measured" (news), or "off" (the old one-pass narration).\n"""\nimport asyncio\nimport re\nimport shutil\nimport subprocess\n\nimport edge_tts\nimport imageio_ffmpeg\n\nSAMPLE_RATE = 24000\n\n# Sound-effect cues the kids script writes in square brackets ([BOING], [TADA], ...) -> files in assets/audio/kids_sfx.\n# The tags are never spoken; the editor plays the sound where the tag sits in the sentence.\nKNOWN_SFX = {\n    "boing": "boing.wav", "pop": "pop.wav", "whoosh": "whoosh.wav", "zoom": "whoosh.wav",\n    "ding": "ding.wav", "chime": "ding.wav", "bell": "ding.wav",\n    "tick": "tick.wav", "clock": "tick.wav", "timer": "tick.wav",\n    "tada": "tada.wav", "ta-da": "tada.wav", "fanfare": "tada.wav",\n    "splash": "splash.wav", "splat": "splash.wav",\n    "cheer": "cheer.wav", "yay": "cheer.wav", "woohoo": "cheer.wav",\n}\nCUE_TAG = re.compile(r"\\[([A-Za-z0-9_\\-]+)\\]")\n# Without tags, a spoken sound word still gets its effect (whole words only: "holding" is not "ding")\nSOUND_WORDS = re.compile(r"\\b(boing|pop|whoosh|splash|splat|ding|ta-?da|yay|woohoo)\\b|3[.,]*\\s*2[.,]*\\s*1\\b", re.I)\n# Repeats of one cue in a sentence ([TICK] [TICK] [TICK]) play this many seconds apart\nREPEAT_GAP = 0.6\n\n\ndef strip_cues(text):\n    """The text without its [SOUND] tags, so they are never read aloud or shown in a description."""\n    return re.sub(r"\\s+([!?.,])", r"\\1", re.sub(r"\\s{2,}", " ", CUE_TAG.sub("", text))).strip()\n\n\ndef extract_sfx_and_clean(sentence):\n    """(spoken sentence, [(fraction of the sentence where the sound plays, sfx file)])."""\n    clean = strip_cues(sentence)\n    cues = [(m.start() / max(1, len(sentence)), KNOWN_SFX[m.group(1).lower()])\n            for m in CUE_TAG.finditer(sentence) if m.group(1).lower() in KNOWN_SFX]\n    if not CUE_TAG.search(sentence):\n        word = SOUND_WORDS.search(clean)\n        if word:\n            # No group means the "3, 2, 1" countdown\n            sound = KNOWN_SFX[word.group(1).lower().replace("-", "")] if word.group(1) else "tick.wav"\n            cues = [(word.end() / max(1, len(clean)), sound)]\n    return clean, cues\n\n\n# Per sentence kind: (speed %, pitch Hz, volume %, pause after in seconds), added to the channel\'s voice_speed.\n# "plain" sentences rotate through their variants so neighbouring sentences never sound identical.\nSTYLES = {\n    "lively": {\n        "hook": (8, 20, 10, 0.30), "exclaim": (6, 14, 8, 0.25), "question": (-2, 24, 4, 0.45),\n        "plain": [(0, 6, 0, 0.20), (-4, -6, 0, 0.20), (3, 2, 3, 0.20)], "last": (-8, 8, 0, 0.35),\n    },\n    "measured": {\n        "hook": (4, 6, 8, 0.35), "exclaim": (3, 4, 5, 0.30), "question": (-3, 10, 2, 0.45),\n        "plain": [(0, 0, 0, 0.25), (-3, -4, 0, 0.25), (2, 2, 0, 0.25)], "last": (-6, -4, 0, 0.40),\n    },\n}\nEXPRESSIONS = ["lively", "measured", "off"]\n# Sentences this short are joined to the next one, so the voice doesn\'t stop and start on every fragment\nMIN_WORDS = 3\nPARALLEL = 4\n\n\ndef split_sentences(text):\n    parts = [p.strip() for p in re.split(r"(?<=[.!?।…])[\\"\'”’)]*\\s+", text.strip()) if p.strip()]\n    sentences, carry = [], ""\n    for part in parts:\n        carry = f"{carry} {part}".strip()\n        if len(carry.split()) >= MIN_WORDS:\n            sentences.append(carry)\n            carry = ""\n    if carry:\n        if sentences:\n            sentences[-1] = f"{sentences[-1]} {carry}"\n        else:\n            sentences.append(carry)\n    return sentences\n\n\ndef sentence_kind(index, count, text):\n    if index == 0:\n        return "hook"\n    if index == count - 1:\n        return "last"\n    if text.rstrip("\\"\'”’) ").endswith("?"):\n        return "question"\n    if text.rstrip("\\"\'”’) ").endswith("!"):\n        return "exclaim"\n    return "plain"\n\n\ndef prosody(style, index, count, text, base_rate):\n    """(rate, pitch, volume, pause) strings and seconds for one sentence."""\n    preset = STYLES[style][sentence_kind(index, count, text)]\n    if isinstance(preset, list):\n        preset = preset[index % len(preset)]\n    rate, pitch, volume, pause = preset\n    base = int(str(base_rate).replace("%", "") or 0)\n    return f"{base + rate:+d}%", f"{pitch:+d}Hz", f"{volume:+d}%", pause\n\n\nasync def _speak(text, voice, rate, pitch, volume, attempts=3):\n    for attempt in range(attempts):\n        try:\n            audio = bytearray()\n            async for chunk in edge_tts.Communicate(text, voice, rate=rate, pitch=pitch, volume=volume).stream():\n                if chunk["type"] == "audio":\n                    audio += chunk["data"]\n            if audio:\n                return bytes(audio)\n        except Exception:\n            if attempt == attempts - 1:\n                raise\n        await asyncio.sleep(2 * (attempt + 1))\n    raise RuntimeError(f"No audio for: {text[:60]}")\n\n\nasync def _speak_all(jobs):\n    gate = asyncio.Semaphore(PARALLEL)\n\n    async def one(job):\n        async with gate:\n            return await _speak(*job)\n    return await asyncio.gather(*(one(job) for job in jobs))\n\n\ndef ffmpeg_exe():\n    return shutil.which("ffmpeg") or imageio_ffmpeg.get_ffmpeg_exe()\n\n\ndef to_pcm(mp3):\n    """Decode to 16-bit mono PCM, trimming silence at both ends of the sentence."""\n    trim = "silenceremove=start_periods=1:start_threshold=-45dB"\n    result = subprocess.run(\n        [ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-i", "pipe:0",\n         "-af", f"{trim},areverse,{trim},areverse", "-f", "s16le", "-ac", "1", "-ar", str(SAMPLE_RATE), "pipe:1"],\n        input=mp3, capture_output=True, check=True)\n    return result.stdout\n\n\ndef narrate(script, voice, base_rate, style, out_mp3):\n    """Write the expressive narration to out_mp3.\n\n    Returns (seconds, [(sentence start seconds, sentence text)], [(seconds, sfx file)]).\n    """\n    spoken, cue_plans = [], []\n    for sentence in split_sentences(script):\n        clean, cues = extract_sfx_and_clean(sentence)\n        # A sentence that is only sound tags ("[TADA] [CHEER]!") isn\'t spoken: its sounds play in the pause\n        if re.search(r"\\w", clean):\n            spoken.append(clean)\n            cue_plans.append(cues)\n        elif cue_plans:\n            cue_plans[-1] += [(1.0, sound) for _, sound in cues]\n    plans = [prosody(style, i, len(spoken), s, base_rate) for i, s in enumerate(spoken)]\n    audio = asyncio.run(_speak_all([(s, voice, r, p, v) for s, (r, p, v, _) in zip(spoken, plans)]))\n    pcm, timings, sfx_events = bytearray(), [], []\n    lead_in = int(0.15 * SAMPLE_RATE) * 2\n    pcm += b"\\0" * lead_in\n    for sentence, cues, mp3, (_, _, _, pause) in zip(spoken, cue_plans, audio, plans):\n        start = len(pcm) / 2 / SAMPLE_RATE\n        timings.append((start, sentence))\n        speech = to_pcm(mp3)\n        length = len(speech) / 2 / SAMPLE_RATE\n        repeats = {}\n        for fraction, sound in cues:\n            at = start + fraction * length + REPEAT_GAP * repeats.get(sound, 0)\n            repeats[sound] = repeats.get(sound, 0) + 1\n            sfx_events.append((round(at, 2), sound))\n        pcm += speech\n        pcm += b"\\0" * (int(pause * SAMPLE_RATE) * 2)\n    subprocess.run(\n        [ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-f", "s16le", "-ar", str(SAMPLE_RATE),\n         "-ac", "1", "-i", "pipe:0", "-c:a", "libmp3lame", "-b:a", "96k", out_mp3],\n        input=bytes(pcm), check=True)\n    return len(pcm) / 2 / SAMPLE_RATE, timings, sfx_events\n',
    'agents/agent_4_editor.py': 'import os\nimport json\nimport shutil\nimport subprocess\nimport tempfile\nimport textwrap\nimport imageio_ffmpeg\nimport numpy as np\nfrom PIL import Image, ImageColor, ImageDraw, ImageEnhance, ImageFilter, ImageFont, ImageOps\nfrom moviepy.editor import (VideoFileClip, AudioFileClip, ImageClip, CompositeVideoClip, CompositeAudioClip,\n                            concatenate_videoclips)\n\nfrom agents import mascot\nfrom agents.branding import channel_logo\nfrom agents.stock_footage import REAL_SUFFIX\nfrom brain import item_matches\n\nSHORT_SIZE, LONG_SIZE = (1080, 1920), (1920, 1080)\n# Kids channels\' background music (kids_bgm) and cartoon sound effects (kids_sfx)\nAUDIO_DIR = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "assets", "audio")\n\n# MoviePy 1.0.3\'s resize uses Image.ANTIALIAS, which Pillow 10 removed (LANCZOS is the same filter)\nif not hasattr(Image, "ANTIALIAS"):\n    Image.ANTIALIAS = Image.LANCZOS\n\n# Bold fonts tried in order: Windows, macOS, then the DejaVu font present on GitHub\'s Ubuntu runners\nFONT_CANDIDATES = [\n    "arialbd.ttf",\n    "Arial Bold.ttf",\n    "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",\n    "DejaVuSans-Bold.ttf",\n]\nWATERMARK_MARGIN = 24\n\n\ndef load_font(size):\n    for candidate in FONT_CANDIDATES:\n        try:\n            return ImageFont.truetype(candidate, size)\n        except OSError:\n            continue\n    return ImageFont.load_default(size=size)\n\n\ndef ffmpeg(*args):\n    """Run FFmpeg (the system copy, or the one bundled with MoviePy) and raise if it fails."""\n    exe = shutil.which("ffmpeg") or imageio_ffmpeg.get_ffmpeg_exe()\n    result = subprocess.run([exe, "-y", "-hide_banner", "-loglevel", "error", *map(str, args)],\n                            capture_output=True, text=True)\n    if result.returncode != 0:\n        raise RuntimeError(f"FFmpeg failed: {result.stderr.strip()[-500:]}")\n\n\ndef watermark_image(text, fontsize, color, opacity=1.0):\n    """The watermark as a transparent PIL image (white text with a dark outline)."""\n    font = load_font(fontsize)\n    stroke = max(1, fontsize // 12)\n    left, top, right, bottom = ImageDraw.Draw(Image.new("RGBA", (1, 1))).textbbox(\n        (0, 0), text, font=font, stroke_width=stroke\n    )\n    image = Image.new("RGBA", (right - left + 4, bottom - top + 4), (0, 0, 0, 0))\n    ImageDraw.Draw(image).text(\n        (2 - left, 2 - top), text, font=font, fill=ImageColor.getrgb(color),\n        stroke_width=stroke, stroke_fill=(0, 0, 0)\n    )\n    if opacity < 1:\n        image.putalpha(image.getchannel("A").point(lambda a: int(a * opacity)))\n    return image\n\n\ndef render_watermark(text, fontsize, color):\n    # Drawn with Pillow instead of MoviePy\'s TextClip, so ImageMagick is not needed\n    font = load_font(fontsize)\n    stroke = max(1, fontsize // 12)\n    left, top, right, bottom = ImageDraw.Draw(Image.new("RGBA", (1, 1))).textbbox(\n        (0, 0), text, font=font, stroke_width=stroke\n    )\n    image = Image.new("RGBA", (right - left + 4, bottom - top + 4), (0, 0, 0, 0))\n    ImageDraw.Draw(image).text(\n        (2 - left, 2 - top), text, font=font, fill=ImageColor.getrgb(color),\n        stroke_width=stroke, stroke_fill=(0, 0, 0)\n    )\n    return ImageClip(np.array(image))\n\n\ndef draw_button(draw, width, scale, center_y, text, fill, text_color, font):\n    left, top, right, bottom = draw.textbbox((0, 0), text, font=font)\n    pad_x, pad_y = int(scale * 0.08), int(scale * 0.035)\n    box_w, box_h = (right - left) + 2 * pad_x, (bottom - top) + 2 * pad_y\n    x0, y0 = (width - box_w) // 2, center_y - box_h // 2\n    draw.rounded_rectangle((x0, y0, x0 + box_w, y0 + box_h), radius=box_h // 2, fill=fill)\n    draw.text((x0 + pad_x - left, y0 + pad_y - top), text, font=font, fill=text_color)\n\n\ndef render_end_card(background, logo_path, channel_name, like_text, subscribe_text, show_subscribe):\n    """One end-card frame: blurred last frame, round logo, channel name, then the LIKE / SUBSCRIBE buttons."""\n    w, h = background.size\n    s = min(w, h)  # sizes follow the shorter side, so the card fits both vertical Shorts and landscape videos\n    card = background.convert("RGB").filter(ImageFilter.GaussianBlur(radius=max(8, s // 40)))\n    card = ImageEnhance.Brightness(card).enhance(0.4).convert("RGBA")\n    draw = ImageDraw.Draw(card)\n\n    diameter, center_y = int(s * 0.34), int(h * 0.30)\n    if logo_path:\n        logo = ImageOps.fit(Image.open(logo_path).convert("RGBA"), (diameter, diameter))\n        mask = Image.new("L", (diameter, diameter), 0)\n        ImageDraw.Draw(mask).ellipse((0, 0, diameter, diameter), fill=255)\n        ring = int(s * 0.012)\n        draw.ellipse((w // 2 - diameter // 2 - ring, center_y - diameter // 2 - ring,\n                      w // 2 + diameter // 2 + ring, center_y + diameter // 2 + ring), fill=(255, 255, 255))\n        card.paste(logo, (w // 2 - diameter // 2, center_y - diameter // 2), mask)\n\n    wide = w > h\n    if logo_path:\n        name_font = load_font(int(s * 0.065))\n        y = center_y + diameter // 2 + int(s * 0.06)\n        wrap_width = 30 if wide else 18\n    else:\n        # No logo: the channel name becomes the centrepiece, larger and where the logo would be\n        name_font = load_font(int(s * 0.105))\n        y = int(h * (0.22 if wide else 0.30))\n        wrap_width = 24 if wide else 14\n    for line in textwrap.wrap(channel_name, width=wrap_width):\n        left, top, right, bottom = draw.textbbox((0, 0), line, font=name_font)\n        draw.text(((w - (right - left)) // 2 - left, y - top), line, font=name_font, fill=(255, 255, 255))\n        y += (bottom - top) + int(s * 0.02)\n\n    button_font = load_font(int(s * 0.07))\n    like_y, subscribe_y = (int(h * 0.58), int(h * 0.78)) if wide else (int(h * 0.62), int(h * 0.75))\n    if show_subscribe:\n        # LIKE stays on screen as "pressed", and SUBSCRIBE appears last\n        draw_button(draw, w, s, like_y, like_text, (6, 95, 212), (255, 255, 255), button_font)\n        draw_button(draw, w, s, subscribe_y, subscribe_text, (204, 0, 0), (255, 255, 255), button_font)\n    else:\n        draw_button(draw, w, s, like_y, like_text, (255, 255, 255), (20, 20, 20), button_font)\n    return np.array(card.convert("RGB"))\n\n\nclass VideoEditorAgent:\n    def __init__(self, config):\n        self.config = config\n        self.active_key = config["active_profile"]\n        self.profile = config["profiles"][self.active_key]\n        self.rules = config["editing_rules"]\n        self.paths = config["storage_paths"]\n\n    def end_card_frames(self, background):\n        """The two end-card frames (LIKE, then LIKE + SUBSCRIBE) and their durations, or None when disabled."""\n        settings = self.rules.get("end_card") or {}\n        if not settings.get("enabled", True):\n            return None\n        seconds = float(settings.get("seconds", 3))\n        branding_dir = self.paths.get("branding_dir", os.path.join(self.paths["base_dir"], "00_branding"))\n        logo = channel_logo(self.profile, self.active_key, branding_dir) if settings.get("show_logo", False) else None\n        frames = [\n            render_end_card(background, logo, self.profile["channel_name"],\n                            settings.get("like_text", "LIKE"), settings.get("subscribe_text", "SUBSCRIBE"), show)\n            for show in (False, True)\n        ]\n        # LIKE alone first, then SUBSCRIBE joins it for the rest of the card\n        return list(zip(frames, (seconds * 0.45, seconds * 0.55)))\n\n    def end_card_clip(self, video):\n        """The closing card as a MoviePy clip (used when re-using a trending video)."""\n        card = self.end_card_frames(Image.fromarray(video.get_frame(max(0, video.duration - 0.1))))\n        if card is None:\n            return None\n        return concatenate_videoclips([ImageClip(frame).set_duration(seconds) for frame, seconds in card])\n\n    def custom_hero_clip(self, kind, width, height, work, volume_factor=None):\n        """The owner\'s own intro / outro video (assets/wondersprout/intro.mp4, outro.mp4; intro_short.mp4 and\n        outro_short.mp4 for vertical Shorts if given), fitted to this video\'s shape without stretching, or None."""\n        if volume_factor is None:\n            volume_factor = (self.rules.get("audio_mastering") or {}).get("hero_volume_factor", 0.28)\n        names = [f"{kind}_short.mp4", f"{kind}.mp4"] if height > width else [f"{kind}.mp4"]\n        source = next((os.path.join(mascot.ART_DIR, n) for n in names\n                       if os.path.exists(os.path.join(mascot.ART_DIR, n))), None)\n        if not source:\n            return None\n        target = os.path.join(work, f"custom_{kind}.mp4")\n        exe = shutil.which("ffmpeg") or imageio_ffmpeg.get_ffmpeg_exe()\n        has_audio = "Audio:" in subprocess.run([exe, "-i", source], capture_output=True, text=True).stderr\n        # Whole clip on a blurred copy of itself when its shape differs from the video\'s (e.g. landscape in a Short)\n        fit = (f"[0:v]split[a][b];[a]scale={width}:{height}:force_original_aspect_ratio=increase,crop={width}:{height},"\n               f"boxblur=20:2[bg];[b]scale={width}:{height}:force_original_aspect_ratio=decrease[fg];"\n               f"[bg][fg]overlay=(W-w)/2:(H-h)/2,fps=30,format=yuv420p,setsar=1[v]")\n        encode = ["-c:v", "libx264", "-preset", "veryfast", "-crf", "20", "-c:a", "aac", "-ar", "44100", "-ac", "2"]\n        if has_audio:\n            # Her clips are about 11 dB louder than the narration: turned down so the video\'s volume stays even\n            ffmpeg("-i", source, "-filter_complex", fit, "-map", "[v]", "-map", "0:a:0", "-af",\n                   f"volume={volume_factor}", *encode, target)\n        else:\n            # A clip without sound gets silence, so it still joins the rest of the video\n            ffmpeg("-i", source, "-f", "lavfi", "-i", "anullsrc=r=44100:cl=stereo", "-filter_complex", fit,\n                   "-map", "[v]", "-map", "1:a", "-shortest", *encode, target)\n        return target\n\n    def mix_soundtrack(self, item, work, duration):\n        """Kids channels: the narration with quiet background music and the script\'s cartoon sound effects.\n\n        Returns the soundtrack to use (the plain narration for other channels or if mixing fails).\n        """\n        vo_path = item["voiceover_path"]\n        if not (self.profile.get("made_for_kids") or self.profile.get("bgm_enabled")):\n            return vo_path\n        bgm_dir = os.path.join(AUDIO_DIR, "kids_bgm")\n        tracks = sorted(t for t in os.listdir(bgm_dir) if t.endswith((".mp3", ".ogg", ".wav"))) \\\n            if os.path.isdir(bgm_dir) else []\n        sfx_cues = [(at, sound) for at, sound in item.get("sfx_cues") or []\n                    if at < duration and os.path.exists(os.path.join(AUDIO_DIR, "kids_sfx", sound))]\n        if not tracks and not sfx_cues:\n            return vo_path\n\n        levels = self.rules.get("audio_mastering") or {}\n        # amix divides every input by the number of inputs unless normalize=0, which buried the narration\n        inputs = ["-i", vo_path]\n        graph = [f"[0:a]volume={levels.get(\'voiceover_volume\', 1.15)},aresample=44100,"\n                 f"aformat=channel_layouts=stereo[vo]"]\n        labels = ["[vo]"]\n        if tracks:\n            # The same video always gets the same track; different videos rotate through them\n            track = tracks[sum(map(ord, item["video_id"])) % len(tracks)]\n            inputs += ["-stream_loop", "-1", "-i", os.path.join(AUDIO_DIR, "kids_bgm", track)]\n            graph.append(f"[1:a]volume={levels.get(\'bgm_volume\', 0.12)},aresample=44100,"\n                         f"aformat=channel_layouts=stereo,afade=t=in:st=0:d=1.5,"\n                         f"afade=t=out:st={max(0.5, duration - 2.0):.2f}:d=2.0[bgm]")\n            labels.append("[bgm]")\n        for at, sound in sfx_cues:\n            inputs += ["-i", os.path.join(AUDIO_DIR, "kids_sfx", sound)]\n            index = inputs.count("-i") - 1\n            delay = max(0, int(at * 1000))\n            graph.append(f"[{index}:a]volume={levels.get(\'sfx_volume\', 0.35)},aresample=44100,"\n                         f"aformat=channel_layouts=stereo,adelay={delay}|{delay}[sfx{index}]")\n            labels.append(f"[sfx{index}]")\n        graph.append("".join(labels) + f"amix=inputs={len(labels)}:duration=first:dropout_transition=2:"\n                     f"normalize={levels.get(\'amix_normalize\', 0)}[aout]")\n        soundtrack = os.path.join(work, "soundtrack.wav")\n        try:\n            ffmpeg(*inputs, "-filter_complex", ";".join(graph), "-map", "[aout]", "-t", f"{duration:.3f}",\n                   soundtrack)\n        except RuntimeError as e:\n            print(f"[Agent 4: Editor] Music and sound effects failed ({e}); using the narration only.")\n            return vo_path\n        print(f"[Agent 4: Editor] Added music{f\' ({track})\' if tracks else \'\'} and {len(sfx_cues)} sound effects")\n        return soundtrack\n\n    def mascot_settings(self, item):\n        """{} for channels without a host; else which hero parts this video gets (intro, host, outro)."""\n        if self.profile.get("mascot") != "wondersprout":\n            return {}\n        settings = dict(self.rules.get("mascot") or {})\n        long_video = item.get("format") == "long"\n        # Long videos open with her intro; Shorts by default don\'t (viewers swipe away from slow starts), and\n        # she swoops into her corner over the opening instead\n        settings["intro"] = settings.get("intro_long", True) if long_video else settings.get("intro_shorts", False)\n        return settings\n\n    def render_stock(self, item, output_video):\n        """Build a stock-footage video entirely with FFmpeg: much faster than MoviePy for long videos.\n\n        Each clip is cut to its scene\'s narration time, scaled and cropped to the frame, joined, then the\n        watermark, narration and end card are added in a single final encode.\n        """\n        width, height = LONG_SIZE if item.get("format") == "long" else SHORT_SIZE\n        voice = AudioFileClip(item["voiceover_path"])\n        duration = voice.duration\n        voice.close()\n        clips = item["footage_paths"]\n        scenes = item.get("scenes") or []\n        if len(scenes) == len(clips):\n            # Each clip plays exactly while its scene is narrated; the last one runs to the end of the narration\n            lengths = [max(0.5, s["end"] - s["start"]) for s in scenes]\n            lengths[-1] = max(0.5, duration - scenes[-1]["start"])\n        else:\n            lengths = [duration / len(clips)] * len(clips)\n        fit = (f"scale={width}:{height}:force_original_aspect_ratio=increase,crop={width}:{height},"\n               f"setsar=1,fps=30,format=yuv420p")\n        # Real footage (people at a table, a podium, a ship) is shown whole in a vertical Short, centred on a\n        # blurred copy of itself, instead of cropping away everything but the middle\n        whole = (f"split[a][b];[a]scale={width}:{height}:force_original_aspect_ratio=increase,crop={width}:{height},"\n                 f"boxblur=20:2[bg];[b]scale={width}:-2[fg];[bg][fg]overlay=(W-w)/2:(H-h)/2,"\n                 f"setsar=1,fps=30,format=yuv420p")\n\n        work = tempfile.mkdtemp(prefix="render_", dir=self.paths["processed_videos"])\n        try:\n            parts = []\n            for index, clip in enumerate(clips):\n                part = os.path.join(work, f"part{index:03d}.mp4")\n                # -stream_loop repeats clips shorter than their share\n                shape = whole if clip.endswith(REAL_SUFFIX) and height > width else fit\n                ffmpeg("-stream_loop", "-1", "-i", clip, "-t", f"{lengths[index]:.3f}", "-an", "-vf", shape,\n                       "-c:v", "libx264", "-preset", "veryfast", "-crf", "23", part)\n                parts.append(part)\n            with open(os.path.join(work, "parts.txt"), "w", encoding="utf-8") as f:\n                f.writelines(f"file \'{os.path.basename(p)}\'\\n" for p in parts)\n            montage = os.path.join(work, "montage.mp4")\n            ffmpeg("-f", "concat", "-safe", "0", "-i", os.path.join(work, "parts.txt"), "-c", "copy", montage)\n\n            mark = os.path.join(work, "watermark.png")\n            watermark_image(self.profile["watermark_text"], self.rules["watermark_fontsize"],\n                            self.rules["watermark_color"], self.rules["watermark_opacity"]).save(mark)\n\n            last_frame = os.path.join(work, "last.png")\n            ffmpeg("-sseof", "-0.2", "-i", montage, "-frames:v", "1", last_frame)\n            card = self.end_card_frames(Image.open(last_frame).convert("RGB"))\n\n            soundtrack_path = self.mix_soundtrack(item, work, duration)\n            inputs = ["-i", montage, "-i", soundtrack_path, "-i", mark]\n            hero = self.mascot_settings(item)\n            video = "[0:v]"\n            if hero.get("host", True) and hero:\n                # WonderSprout hosts from a corner, her face following the script and her mouth the narration\n                sentences = item.get("sentence_timings") or [(s["start"], s["text"]) for s in scenes]\n                host, hx, hy = mascot.render_host(item["voiceover_path"], sentences, duration, (width, height),\n                                                  os.path.join(work, "host.mov"), entrance=not hero.get("intro"))\n                inputs += ["-i", host]\n                host_index = inputs.count("-i") - 1\n                video = f"[0:v][{host_index}:v]overlay={hx}:{hy}:eof_action=pass[hosted];[hosted]"\n            graph = (f"{video}[2:v]overlay=W-w-{WATERMARK_MARGIN}:H-h-{WATERMARK_MARGIN},format=yuv420p,setsar=1[main];"\n                     "[1:a]aresample=44100,aformat=channel_layouts=stereo[voice];")\n            segments = []\n\n            def add_clip(path, name):\n                """Add a ready-made clip with sound (hero intro or outro) as the next segment."""\n                nonlocal graph\n                inputs.extend(["-i", path])\n                index = inputs.count("-i") - 1\n                graph += (f"[{index}:v]scale={width}:{height},fps=30,format=yuv420p,setsar=1[{name}v];"\n                          f"[{index}:a]aresample=44100,aformat=channel_layouts=stereo[{name}a];")\n                segments.append((f"[{name}v]", f"[{name}a]"))\n\n            # She speaks her intro and goodbye in the channel\'s own narrator voice\n            voice, rate = self.profile["voice"], self.profile.get("voice_rate", "-5%")\n            # A ready-made intro / outro video in assets/wondersprout is used when present; otherwise one is made\n            if hero.get("intro"):\n                add_clip(self.custom_hero_clip("intro", width, height, work) or\n                         mascot.render_intro((width, height), os.path.join(work, "intro.mp4"), load_font, voice, rate,\n                                             hero.get("intro_line", mascot.INTRO_LINE)), "intro")\n            segments.append(("[main]", "[voice]"))\n            if hero.get("outro", True) and hero:\n                add_clip(self.custom_hero_clip("outro", width, height, work) or\n                         mascot.render_outro((width, height), os.path.join(work, "outro.mp4"), load_font, voice, rate,\n                                             hero.get("outro_line", mascot.OUTRO_LINE)), "outro")\n            if card:\n                for index, (frame, seconds) in enumerate(card):\n                    path = os.path.join(work, f"card{index}.png")\n                    Image.fromarray(frame).save(path)\n                    inputs += ["-loop", "1", "-t", f"{seconds:.3f}", "-i", path,\n                               "-f", "lavfi", "-t", f"{seconds:.3f}", "-i", "anullsrc=r=44100:cl=stereo"]\n                    image_index = inputs.count("-i") - 2\n                    graph += f"[{image_index}:v]fps=30,format=yuv420p,setsar=1[c{index}];"\n                    segments.append((f"[c{index}]", f"[{image_index + 1}:a]"))\n            graph += "".join(v + a for v, a in segments) + f"concat=n={len(segments)}:v=1:a=1[v][a]"\n            ffmpeg(*inputs, "-filter_complex", graph, "-map", "[v]", "-map", "[a]",\n                   "-c:v", "libx264", "-preset", "veryfast", "-crf", "23", "-c:a", "aac", "-b:a", "160k",\n                   "-movflags", "+faststart", output_video)\n        finally:\n            shutil.rmtree(work, ignore_errors=True)\n\n    def run(self):\n        manifest_path = self.paths["manifest_file"]\n        with open(manifest_path, "r", encoding="utf-8") as f:\n            trends = json.load(f)\n\n        for item in trends:\n            # Stock videos are ready once their scene clips are in; re-used trending videos once narrated\n            ready = item["status"] == "ready_to_edit" or (item["status"] == "voiced" and not item.get("scenes"))\n            if ready and item_matches(item, self.active_key, self.profile):\n                vid_id = item["video_id"]\n                raw_video = item["raw_video_path"]\n                vo_audio = item["voiceover_path"]\n                output_video = os.path.join(\n                    self.paths["processed_videos"], f"final_{self.active_key}_{vid_id}.mp4"\n                )\n\n                print(f"\\n[Agent 4: Editor] Editing & Watermarking {vid_id}...")\n                if item.get("footage_paths"):\n                    try:\n                        self.render_stock(item, output_video)\n                        item["edited_video_path"] = output_video\n                        item["status"] = "edited"\n                        print(f"[Agent 4: Editor] Saved final video to {output_video}")\n                    except Exception as e:\n                        print(f"[Agent 4: Editor] Error editing {vid_id}: {e}")\n                    continue\n                try:\n                    # Re-used trending video (footage.source "youtube"): edited with MoviePy\n                    voice_clip = AudioFileClip(vo_audio)\n                    video_clip = VideoFileClip(raw_video)\n                    sources = [video_clip]\n                    # Loop or trim the picture only; looping a clip\'s audio in MoviePy 1.0.3 reads past its end\n                    original_audio = video_clip.audio\n                    picture = video_clip.without_audio()\n                    if picture.duration < voice_clip.duration:\n                        picture = picture.loop(duration=voice_clip.duration)\n                    else:\n                        picture = picture.subclip(0, voice_clip.duration)\n\n                    # Zoom in, then crop back to the original frame size around the centre\n                    width, height = picture.size\n                    transformed_video = picture.resize(self.rules["zoom_factor"]).crop(\n                        x_center=width * self.rules["zoom_factor"] / 2,\n                        y_center=height * self.rules["zoom_factor"] / 2,\n                        width=width - width % 2,\n                        height=height - height % 2,\n                    )\n\n                    # original_audio_volume 0 means the source\'s sound is dropped and only the AI voice is heard\n                    if original_audio is not None and self.rules.get("original_audio_volume", 0) > 0:\n                        bg_end = max(0, min(original_audio.duration - 0.1, voice_clip.duration))\n                        bg_audio = original_audio.subclip(0, bg_end).volumex(self.rules["original_audio_volume"])\n                        mixed_audio = CompositeAudioClip([bg_audio, voice_clip])\n                    else:\n                        mixed_audio = voice_clip\n\n                    transformed_video = transformed_video.set_audio(mixed_audio)\n\n                    watermark = render_watermark(\n                        self.profile["watermark_text"],\n                        self.rules["watermark_fontsize"],\n                        self.rules["watermark_color"],\n                    )\n                    watermark = (\n                        watermark\n                        .set_opacity(self.rules["watermark_opacity"])\n                        .set_position((\n                            transformed_video.w - watermark.w - WATERMARK_MARGIN,\n                            transformed_video.h - watermark.h - WATERMARK_MARGIN,\n                        ))\n                        .set_duration(transformed_video.duration)\n                    )\n\n                    final_clip = CompositeVideoClip([transformed_video, watermark])\n                    end_card = self.end_card_clip(transformed_video)\n                    if end_card is not None:\n                        final_clip = concatenate_videoclips([final_clip, end_card])\n                    final_clip.write_videofile(\n                        output_video,\n                        codec="libx264",\n                        audio_codec="aac",\n                        fps=30,\n                        # Long videos use a faster encoder setting so a 6-minute render stays quick\n                        preset="veryfast" if item.get("format") == "long" else "medium",\n                        threads=os.cpu_count() or 2,\n                        logger=None\n                    )\n\n                    for source in sources:\n                        source.close()\n                    voice_clip.close()\n                    final_clip.close()\n\n                    item["edited_video_path"] = output_video\n                    item["status"] = "edited"\n                    print(f"[Agent 4: Editor] Saved final video to {output_video}")\n                except Exception as e:\n                    print(f"[Agent 4: Editor] Error editing {vid_id}: {e}")\n\n        with open(manifest_path, "w", encoding="utf-8") as f:\n            json.dump(trends, f, indent=4, ensure_ascii=False)\n',
    'agents/mascot.py': '"""WonderSprout, the kids channel\'s superhero host: drawn in code, so every frame is consistent and needs no licence.\n\nShe appears in three ways (agents/agent_4_editor.py):\n- intro: swoops in and waves with her name at the start of every video;\n- host: in a corner of the video, her expression following the script sentence by sentence (talking, thinking,\n  asking, amazed, happy, waving), her mouth moving with the narration;\n- outro: waves goodbye and flies off just before the LIKE and SUBSCRIBE card.\n\nTo use professionally drawn art instead, see ART_DIR: a PNG per expression there replaces the drawn version.\n"""\nimport math\nimport os\n\nfrom PIL import Image, ImageDraw, ImageFilter\n\n# Base drawing size of the half-body character; drawn SUPER times larger and scaled down for smooth edges\nBASE_W, BASE_H = 600, 720\nSUPER = 3\n\nSKIN = "#C68A5E"\nSKIN_SHADE = "#A86F48"\nHAIR = "#3A2215"\nSUIT = "#2FB45A"\nSUIT_DARK = "#23914A"\nCAPE = "#139C93"\nCAPE_DARK = "#0E7A73"\nGOLD = "#FFCB2F"\nLEAF = "#7BD65A"\nLINE = "#2A1A10"\nWHITE = "#FFFFFF"\nIRIS = "#5B3A1E"\nBLUSH = (255, 120, 120, 90)\nMOUTH = "#7A1F2B"\nTONGUE = "#E8697A"\n\nEXPRESSIONS = ["happy", "talk", "think", "ask", "wow", "wave"]\n# Character art, if added (transparent PNGs, see `--hero-art` in execution.py and assets/wondersprout/PROMPTS.md):\n# <expression>.png, optionally <expression>_open.png with the mouth open, and fly.png for flying. It is kept in the\n# project so GitHub runs have it too. Once any art is there, it replaces the drawn character everywhere.\nART_DIR = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "assets", "wondersprout")\nART_NAMES = EXPRESSIONS + ["fly"]\n# A missing pose borrows the closest one that exists, so the art style never mixes with the drawing\nART_FALLBACK = {"talk": ["happy"], "think": ["happy"], "ask": ["talk", "happy"], "wow": ["happy"],\n                "wave": ["happy"], "fly": ["wave", "happy"], "happy": ["talk", "wave"]}\n\n\nclass Pen:\n    """Draws in base coordinates on the supersampled canvas, with a cartoon outline."""\n\n    def __init__(self, image):\n        self.draw = ImageDraw.Draw(image, "RGBA")\n\n    @staticmethod\n    def box(x0, y0, x1, y1):\n        return [x0 * SUPER, y0 * SUPER, x1 * SUPER, y1 * SUPER]\n\n    def ellipse(self, x0, y0, x1, y1, fill, outline=LINE, width=4):\n        self.draw.ellipse(self.box(x0, y0, x1, y1), fill=fill, outline=outline, width=width * SUPER if outline else 0)\n\n    def rounded(self, x0, y0, x1, y1, radius, fill, outline=LINE, width=4):\n        self.draw.rounded_rectangle(self.box(x0, y0, x1, y1), radius * SUPER, fill=fill, outline=outline,\n                                    width=width * SUPER if outline else 0)\n\n    def polygon(self, points, fill, outline=LINE, width=4):\n        pts = [(x * SUPER, y * SUPER) for x, y in points]\n        self.draw.polygon(pts, fill=fill)\n        if outline:\n            self.draw.line(pts + [pts[0]], fill=outline, width=width * SUPER, joint="curve")\n\n    def arc(self, x0, y0, x1, y1, start, end, width=4, fill=LINE):\n        self.draw.arc(self.box(x0, y0, x1, y1), start, end, fill=fill, width=width * SUPER)\n\n    def line(self, points, width=4, fill=LINE):\n        self.draw.line([(x * SUPER, y * SUPER) for x, y in points], fill=fill, width=width * SUPER, joint="curve")\n\n\ndef leaf(pen, cx, cy, length, angle, fill=LEAF):\n    """A pointed leaf from (cx, cy) in direction angle (degrees)."""\n    a = math.radians(angle)\n    tip = (cx + length * math.cos(a), cy - length * math.sin(a))\n    side = math.radians(angle + 90)\n    mid = (cx + length * 0.5 * math.cos(a), cy - length * 0.5 * math.sin(a))\n    w = length * 0.32\n    p1 = (mid[0] + w * math.cos(side), mid[1] - w * math.sin(side))\n    p2 = (mid[0] - w * math.cos(side), mid[1] + w * math.sin(side))\n    pen.polygon([(cx, cy), p1, tip, p2], fill)\n    pen.line([(cx, cy), tip], width=2, fill="#4E9E3A")\n\n\ndef glove(pen, x, y, r=30):\n    pen.ellipse(x - r, y - r, x + r, y + r, GOLD)\n\n\ndef limb(pen, points, width=46, fill=SUIT):\n    """A bendy cartoon arm through the points: an outline stroke, then the colour, with round ends."""\n    for colour, w in ((LINE, width + 8), (fill, width)):\n        pen.line(points, width=w, fill=colour)\n        for x, y in (points[0], points[-1]):\n            r = w / 2\n            pen.ellipse(x - r, y - r, x + r, y + r, colour, outline=None)\n\n\ndef open_hand(pen, x, y, up=True):\n    """A gloved open hand: palm plus four fingers pointing up (wave) or a cupped palm facing up (ask)."""\n    if up:\n        glove(pen, x, y, 36)\n        for dx, h in ((-24, 46), (-8, 54), (8, 54), (24, 46)):\n            pen.rounded(x + dx - 9, y - h - 10, x + dx + 9, y - 14, 9, GOLD)\n        pen.rounded(x + 26, y - 6, x + 58, y + 12, 9, GOLD)                            # thumb\n    else:\n        pen.draw.chord(pen.box(x - 62, y - 46, x + 62, y + 44), 0, 180, fill=GOLD, outline=LINE, width=4 * SUPER)\n        pen.rounded(x - 70, y - 16, x - 30, y + 6, 10, GOLD)                           # thumb\n\n\ndef draw_arms(pen, expression):\n    """Arms in front of the body for the expressions that use them."""\n    if expression == "think":\n        limb(pen, [(440, 560), (450, 660), (360, 520)])                                 # elbow down, hand to the chin\n        glove(pen, 352, 452, 34)\n    elif expression == "ask":\n        limb(pen, [(165, 560), (140, 660), (95, 585)])                                   # palm up, inviting an answer\n        open_hand(pen, 92, 560, up=False)\n    elif expression == "wave":\n        limb(pen, [(440, 540), (530, 560), (540, 420)])                                 # elbow out, hand up\n        open_hand(pen, 540, 390, up=True)\n\n\ndef draw_face(pen, expression, mouth_open):\n    cx = 300\n    # Eyes\n    if expression == "happy" and not mouth_open:\n        for ex in (255, 345):\n            pen.arc(ex - 30, 285, ex + 30, 335, 200, 340, width=6)                    # smiling closed eyes\n    else:\n        big = expression == "wow"\n        for ex in (255, 345):\n            ry = 34 if big else 29\n            pen.ellipse(ex - 26, 300 - ry, ex + 26, 300 + ry, WHITE, width=3)\n            look_x, look_y = (8, -12) if expression == "think" else (0, 2)\n            ir = 17 if big else 16\n            pen.ellipse(ex - ir + look_x, 302 - ir + look_y, ex + ir + look_x, 302 + ir + look_y, IRIS, outline=None)\n            pen.ellipse(ex - 8 + look_x, 302 - 8 + look_y, ex + 8 + look_x, 302 + 8 + look_y, "#1A0F08", outline=None)\n            pen.ellipse(ex - 3 + look_x, 293 + look_y, ex + 5 + look_x, 301 + look_y, WHITE, outline=None)\n            side = -1 if ex < cx else 1                                               # one lash at the outer corner\n            pen.line([(ex + side * 24, 300 - ry + 10), (ex + side * 36, 300 - ry + 2)], width=4)\n    # Eyebrows\n    lift = {"wow": -14, "ask": -10, "think": -4}.get(expression, 0)\n    pen.arc(222, 236 + lift, 288, 270 + lift, 205, 335, width=5)\n    if expression == "think":\n        pen.line([(318, 250), (372, 256)], width=5)                                   # one brow flat: pondering\n    else:\n        pen.arc(312, 236 + lift, 378, 270 + lift, 205, 335, width=5)\n    # Nose and cheeks\n    pen.arc(288, 318, 312, 345, 20, 160, width=3, fill=SKIN_SHADE)\n    pen.draw.ellipse(pen.box(205, 335, 245, 360), fill=BLUSH)\n    pen.draw.ellipse(pen.box(355, 335, 395, 360), fill=BLUSH)\n    # Mouth\n    if mouth_open or expression == "wow":\n        if expression in ("wow", "ask"):\n            pen.ellipse(cx - 20, 362, cx + 20, 400, MOUTH, width=3)                   # round "Oh!"\n        else:\n            pen.draw.chord(pen.box(cx - 40, 345, cx + 40, 410), 0, 180, fill=MOUTH, outline=LINE, width=3 * SUPER)\n            pen.draw.chord(pen.box(cx - 22, 380, cx + 22, 406), 180, 360, fill=TONGUE)\n    elif expression == "think":\n        pen.line([(cx - 14, 378), (cx + 16, 372)], width=5)                           # small thoughtful mouth\n    else:\n        pen.arc(cx - 40, 335, cx + 40, 392, 20, 160, width=6)                         # smile\n\n\ndef draw_hero(expression="happy", mouth_open=False):\n    """The half-body character as an RGBA image of BASE_W x BASE_H."""\n    image = Image.new("RGBA", (BASE_W * SUPER, BASE_H * SUPER), (0, 0, 0, 0))\n    pen = Pen(image)\n    # Cape behind the shoulders\n    pen.polygon([(150, 470), (450, 470), (540, 720), (60, 720)], CAPE)\n    pen.polygon([(160, 480), (205, 480), (150, 720), (90, 720)], CAPE_DARK, outline=None)\n    # Long hair falling behind the shoulders\n    pen.rounded(140, 140, 460, 600, 140, HAIR)\n    # Neck and body\n    pen.rounded(270, 400, 330, 480, 20, SKIN)\n    pen.rounded(150, 460, 450, 760, 90, SUIT)\n    pen.polygon([(150, 470), (205, 450), (230, 500)], CAPE)                            # cape collar points\n    pen.polygon([(450, 470), (395, 450), (370, 500)], CAPE)\n    pen.polygon([(240, 455), (360, 455), (300, 505)], SKIN)                            # V neckline\n    pen.ellipse(250, 520, 350, 620, GOLD)                                              # emblem\n    leaf(pen, 300, 590, 50, 70)\n    leaf(pen, 300, 590, 42, 125)\n    pen.rounded(150, 690, 450, 720, 8, GOLD, outline=None)                             # belt\n    # Head, hair, tiara and sprout\n    pen.ellipse(165, 140, 435, 430, SKIN)\n    pen.draw.chord(pen.box(158, 122, 442, 360), 180, 360, fill=HAIR, outline=LINE, width=4 * SUPER)\n    pen.polygon([(165, 260), (200, 190), (250, 250)], HAIR, outline=None)              # side-swept fringe\n    pen.polygon([(250, 190), (330, 175), (300, 245)], HAIR, outline=None)\n    pen.polygon([(435, 260), (400, 190), (360, 240)], HAIR, outline=None)\n    pen.rounded(195, 178, 405, 202, 10, GOLD)                                          # tiara\n    pen.ellipse(284, 168, 316, 200, LEAF, width=3)\n    pen.line([(300, 124), (300, 84)], width=6, fill="#4E9E3A")                         # sprout on her head\n    leaf(pen, 300, 92, 58, 35)\n    leaf(pen, 300, 92, 52, 150)\n    draw_face(pen, expression, mouth_open)\n    draw_arms(pen, expression)\n    return image.resize((BASE_W, BASE_H), Image.LANCZOS)\n\n\ndef has_art(name=None):\n    """True if character art exists: for one pose, or (no name) for any pose."""\n    if name:\n        return os.path.exists(os.path.join(ART_DIR, f"{name}.png"))\n    return any(has_art(n) for n in ART_NAMES)\n\n\ndef art_image(expression, mouth_open):\n    """The art for a pose: its mouth-open version if asked for and present, else the pose, else the closest pose."""\n    # Its own picture, then the closest poses, then any pose of her at all\n    for name in dict.fromkeys([expression] + ART_FALLBACK.get(expression, []) + ART_NAMES):\n        if mouth_open and has_art(f"{name}_open"):\n            return Image.open(os.path.join(ART_DIR, f"{name}_open.png")).convert("RGBA")\n        if has_art(name):\n            image = Image.open(os.path.join(ART_DIR, f"{name}.png")).convert("RGBA")\n            if mouth_open:\n                # No mouth-open picture: a tiny squash shows she is talking\n                image = image.resize((image.width, round(image.height * 0.985)), Image.LANCZOS)\n            return image\n    return None\n\n\ndef hero_image(expression="happy", mouth_open=False, height=None):\n    """The character for an expression: the art in ART_DIR if there is any, else the drawing; scaled to height."""\n    image = art_image(expression, mouth_open) if has_art() else None\n    if image is None:\n        image = draw_hero(expression if expression in EXPRESSIONS else "happy", mouth_open)\n    if height and image.height != height:\n        image = image.resize((round(image.width * height / image.height), height), Image.LANCZOS)\n    return image\n\n\ndef clean_cutout(image):\n    """Keep only the character in a transparent picture.\n\n    - Marks that aren\'t part of her (an image AI\'s logo in a corner, specks) are dropped: only her shape, and\n      pieces right next to it such as loose strands of hair, are kept.\n    - Leftover backdrop-coloured pixels along her outline (a magenta fringe round the hair) are removed: the\n      backdrop colour is read from the transparent pixels, which still hold it.\n    - The edge is softened slightly, so she sits naturally over video.\n    """\n    import numpy as np\n    alpha = np.asarray(image.getchannel("A"))\n    solid = alpha > 20\n    if not solid.any():\n        return image\n    # Her shape: flood-fill from the visible pixel nearest the centre of all visible pixels\n    ys, xs = np.nonzero(solid)\n    nearest = np.argmin((ys - ys.mean()) ** 2 + (xs - xs.mean()) ** 2)\n    # .copy(): an image made straight from a NumPy array can be read-only, and the fill would silently do nothing\n    marked = Image.fromarray(np.where(solid, 255, 0).astype(np.uint8), "L").copy()\n    ImageDraw.floodfill(marked, (int(xs[nearest]), int(ys[nearest])), 128)\n    body = np.asarray(marked) == 128\n    # Keep anything within about 3% of the picture\'s width of her (hair strands); drop what\'s further away\n    small = Image.fromarray(np.where(body, 255, 0).astype(np.uint8), "L").resize(\n        (max(1, image.width // 4), max(1, image.height // 4)), Image.BOX)\n    reach = max(3, (image.width // 4) // 33) | 1\n    near = np.asarray(small.filter(ImageFilter.MaxFilter(reach)).resize(image.size, Image.NEAREST)) > 0\n    keep = body | (solid & near)\n    # The backdrop colour, from the pixels that are transparent\n    rgb = np.asarray(image.convert("RGB")).astype(np.int32)\n    hidden = alpha < 10\n    if hidden.any():\n        backdrop = np.median(rgb[hidden], axis=0)\n        inner = np.asarray(Image.fromarray(np.where(keep, 255, 0).astype(np.uint8), "L")\n                           .filter(ImageFilter.MinFilter(7))) > 0\n        edge = keep & ~inner\n        tinted = np.sqrt(((rgb - backdrop) ** 2).sum(axis=2)) < 140\n        keep &= ~(edge & tinted)\n        # Hair strands further in can still carry a tint of the backdrop: take that colour out of the outer band\n        # (about 12 pixels) instead of deleting them. Only pixels whose red AND blue both exceed green change, so\n        # skin and her green and blue costume keep their colours.\n        small_keep = Image.fromarray(np.where(keep, 255, 0).astype(np.uint8), "L").resize(\n            (max(1, image.width // 4), max(1, image.height // 4)), Image.BOX)\n        deep = np.asarray(small_keep.filter(ImageFilter.MinFilter(7)).resize(image.size, Image.NEAREST)) > 250\n        band = keep & ~deep\n        spill = np.minimum(rgb[..., 0], rgb[..., 2]) - rgb[..., 1]\n        fix = band & (spill > 0) if backdrop[0] > backdrop[1] and backdrop[2] > backdrop[1] else np.zeros_like(band)\n        rgb = rgb.copy()\n        rgb[..., 0] = np.where(fix, rgb[..., 0] - spill, rgb[..., 0])\n        rgb[..., 2] = np.where(fix, rgb[..., 2] - spill, rgb[..., 2])\n        # What\'s left of a red-purple cast on those strands goes back to her dark brown hair colour\n        cast = band & (rgb[..., 0] - rgb[..., 1] > 25) & (rgb[..., 2] - rgb[..., 1] > -5) if fix.any() else fix\n        rgb[..., 0] = np.where(cast, np.minimum(rgb[..., 0], rgb[..., 1] + 12), rgb[..., 0])\n        rgb[..., 2] = np.where(cast, np.minimum(rgb[..., 2], rgb[..., 1] + 6), rgb[..., 2])\n    soft = Image.fromarray(np.where(keep, 255, 0).astype(np.uint8), "L").filter(ImageFilter.GaussianBlur(1.2))\n    new_alpha = np.minimum(np.asarray(soft), alpha).astype(np.uint8)\n    result = Image.fromarray(np.clip(rgb, 0, 255).astype(np.uint8), "RGB").convert("RGBA")\n    result.putalpha(Image.fromarray(new_alpha, "L"))\n    return result\n\n\ndef import_art(source_dir, out_dir=ART_DIR, height=1200):\n    """Turn pictures of her into transparent pose images: cut out the background, clean the edges, crop, resize.\n\n    Pictures in source_dir are named after poses (happy.png, talk.png, wave_open.jpg, fly.png...). A transparent\n    PNG keeps its own transparency; otherwise the plain backdrop colour is taken from the picture\'s corners (magenta\n    is easiest: it\'s in none of her colours). Returns the poses imported.\n    """\n    import numpy as np\n    os.makedirs(out_dir, exist_ok=True)\n    done = []\n    for file in sorted(os.listdir(source_dir)):\n        name, ext = os.path.splitext(file)\n        if ext.lower() not in (".png", ".jpg", ".jpeg", ".webp") or name.split("_open")[0] not in ART_NAMES:\n            continue\n        picture = Image.open(os.path.join(source_dir, file))\n        if picture.mode in ("RGBA", "LA", "PA") and picture.convert("RGBA").getchannel("A").getextrema()[0] < 128:\n            image = picture.convert("RGBA")                   # already a transparent cut-out\n        else:\n            rgb = np.asarray(picture.convert("RGB")).astype(np.float32)\n            h, w, _ = rgb.shape\n            k = max(4, min(h, w) // 40)\n            corners = np.concatenate([rgb[:k, :k].reshape(-1, 3), rgb[:k, -k:].reshape(-1, 3),\n                                      rgb[-k:, :k].reshape(-1, 3), rgb[-k:, -k:].reshape(-1, 3)])\n            background = np.median(corners, axis=0)\n            distance = np.sqrt(((rgb - background) ** 2).sum(axis=2))\n            alpha = np.clip((distance - 40) / 50, 0, 1)        # soft edge between 40 and 90 colour steps away\n            # Remove the background colour\'s tint from the soft edge pixels\n            spill = (1 - alpha)[..., None]\n            clean = np.clip((rgb - background * spill) / np.maximum(alpha[..., None], 0.05), 0, 255)\n            rgba = np.dstack([np.where(alpha[..., None] > 0, clean, rgb), alpha * 255]).astype(np.uint8)\n            image = Image.fromarray(rgba, "RGBA")\n        image = clean_cutout(image)\n        box = image.getchannel("A").point(lambda a: 255 if a > 20 else 0).getbbox()\n        if box:\n            image = image.crop(box)\n        image = image.resize((round(image.width * height / image.height), height), Image.LANCZOS)\n        image.save(os.path.join(out_dir, f"{name}.png"))\n        done.append(name)\n    return done\n\n\ndef ws_badge(width, font_loader):\n    """A small green "WS" badge with a gold border (her emblem), `width` pixels wide."""\n    scale = 4\n    w, h = width * scale, round(width * 0.52) * scale\n    badge = Image.new("RGBA", (w, h), (0, 0, 0, 0))\n    draw = ImageDraw.Draw(badge)\n    draw.rounded_rectangle([0, 0, w - 1, h - 1], radius=h // 2, fill=SUIT, outline=GOLD, width=max(2, h // 12))\n    font = font_loader(round(h * 0.62))\n    box = draw.textbbox((0, 0), "WS", font=font, stroke_width=max(1, h // 24))\n    draw.text(((w - box[2] - box[0]) / 2, (h - box[3] - box[1]) / 2), "WS", font=font, fill=GOLD,\n              stroke_width=max(1, h // 24), stroke_fill="#1C6B2E")\n    return badge.resize((width, round(width * 0.52)), Image.LANCZOS)\n\n\ndef cover_corner_logo(source, target, font_loader, work_dir):\n    """Copy a video with a "WS" badge over its bottom-right corner, where image AIs put their logo (e.g. "Grok").\n\n    The badge is about 12% of the video\'s width, just inside the corner; sound is copied unchanged.\n    """\n    import re\n    import subprocess\n    info = subprocess.run([ffmpeg_exe(), "-i", source], capture_output=True, text=True).stderr\n    width, height = (int(n) for n in re.search(r"Video: .*?, (\\d{2,5})x(\\d{2,5})", info).groups())\n    badge_w = max(40, round(width * 0.12))\n    badge = os.path.join(work_dir, "ws_badge.png")\n    ws_badge(badge_w, font_loader).save(badge)\n    margin_x, margin_y = max(2, round(width * 0.005)), max(3, round(height * 0.005))\n    subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-i", source, "-i", badge,\n                    "-filter_complex", f"[0:v][1:v]overlay=W-w-{margin_x}:H-h-{margin_y},format=yuv420p[v]",\n                    "-map", "[v]", "-map", "0:a?", "-c:v", "libx264", "-preset", "veryfast", "-crf", "18",\n                    "-c:a", "copy", target], check=True, capture_output=True)\n    os.remove(badge)\n    return target\n\n\ndef expression_for(sentence, index=0):\n    """Which face suits a sentence of the script."""\n    text = sentence.lower()\n    if index == 0 and any(w in text for w in ("hi ", "hello", "hey ")):\n        return "wave"\n    if any(w in text for w in ("whoa", "wow", "amazing", "incredible", "can you believe", "surprise", "oh no")):\n        return "wow"\n    if any(w in text for w in ("guess", "think", "wonder", "hmm", "what if", "imagine")):\n        return "think"\n    if text.rstrip("\\"\'”’) ").endswith("?"):\n        return "ask"\n    if any(w in text for w in ("bye", "see you", "next time")):\n        return "wave"\n    if text.rstrip("\\"\'”’) ").endswith("!"):\n        return "happy"\n    return "talk"\n\n\ndef sheet(path):\n    """Every expression side by side (mouth closed, then open) for a quick visual check."""\n    images = [hero_image(e, m, BASE_H) for e in EXPRESSIONS for m in (False, True)]\n    w, h = BASE_W // 2, BASE_H // 2\n    out = Image.new("RGB", (w * 6, h * 2), "#BFE8FF")\n    for i, image in enumerate(images):\n        small = image.resize((round(image.width * h / image.height), h), Image.LANCZOS)\n        col, row = (i // 2), (i % 2)\n        out.paste(small, (col * w, row * h), small)\n    out.save(path)\n\n\n# ---------- animation ----------\n\nHOST_FPS = 15          # the host overlay changes pose and mouth at this rate; plenty for a cartoon\nCLIP_FPS = 30\n# Her lines, spoken in the channel\'s narrator voice (editing_rules.mascot in BRAIN.md can change them)\nINTRO_LINE = "Hey kids! This is Wonder Sprout, your fun and learning superhero!"\nOUTRO_LINE = "Wonder Sprout signing off, kids! We\'ll meet next time!"\nENTRANCE_SECONDS = 0.8  # Shorts: she swoops into her corner over the opening instead of a separate intro\n\n\ndef ffmpeg_exe():\n    import shutil\n    import imageio_ffmpeg\n    return shutil.which("ffmpeg") or imageio_ffmpeg.get_ffmpeg_exe()\n\n\ndef mouth_track(voice_path, fps=HOST_FPS):\n    """True for each frame where the narration is loud enough for her mouth to be open."""\n    import subprocess\n    import numpy as np\n    pcm = subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-i", voice_path, "-f", "s16le",\n                          "-ac", "1", "-ar", "16000", "pipe:1"], capture_output=True, check=True).stdout\n    samples = np.frombuffer(pcm, dtype=np.int16).astype(np.float32)\n    step = 16000 // fps\n    frames = len(samples) // step\n    if not frames:\n        return []\n    rms = np.sqrt((samples[:frames * step].reshape(frames, step) ** 2).mean(axis=1))\n    loud = np.percentile(rms, 90) or 1.0\n    return list(rms > 0.3 * loud)\n\n\ndef expression_track(sentences, frames, fps=HOST_FPS):\n    """The expression for each frame, from the sentence being spoken (sentences: [(start seconds, text)])."""\n    track, current, index = [], "happy", -1\n    for frame in range(frames):\n        t = frame / fps\n        while index + 1 < len(sentences) and sentences[index + 1][0] <= t:\n            index += 1\n            current = expression_for(sentences[index][1], index)\n        track.append(current)\n    return track\n\n\ndef sprite_set(height):\n    """Every expression with its mouth closed and open, scaled to height."""\n    return {(e, m): hero_image(e, m, height) for e in EXPRESSIONS for m in (False, True)}\n\n\ndef ease_out(t):\n    return 1 - (1 - min(max(t, 0.0), 1.0)) ** 3\n\n\ndef render_host(voice_path, sentences, duration, frame_size, out_path, entrance=False):\n    """A transparent video of her hosting in the bottom-left corner, as long as the narration.\n\n    Returns (out_path, x, y): where to overlay it on the main video.\n    """\n    import subprocess\n    width, height = frame_size\n    portrait = height > width\n    # Full-body art needs more height than the half-body drawing for her face to read\n    full_body = has_art()\n    hero_h = round(height * ((0.3 if portrait else 0.55) if full_body else (0.24 if portrait else 0.36)))\n    sprites = sprite_set(hero_h)\n    sw, sh = sprites[("happy", False)].size\n    bob = max(4, hero_h // 60)\n    box_w, box_h = sw, sh + 2 * bob\n    x = round(width * 0.02)\n    y = height - box_h - round(height * (0.11 if portrait else 0.03))   # above YouTube\'s Shorts caption area\n    frames = int(duration * HOST_FPS) + 1\n    mouths = mouth_track(voice_path)\n    faces = expression_track(sentences, frames)\n    cache = {}\n    encoder = subprocess.Popen(\n        [ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-f", "rawvideo", "-pix_fmt", "rgba",\n         "-s", f"{box_w}x{box_h}", "-r", str(HOST_FPS), "-i", "pipe:0", "-c:v", "qtrle", "-pix_fmt", "argb", out_path],\n        stdin=subprocess.PIPE)\n    try:\n        for frame in range(frames):\n            t = frame / HOST_FPS\n            face = faces[frame]\n            mouth = bool(mouths[frame]) if frame < len(mouths) else False\n            if face == "think":\n                mouth = False                      # thinking is shown with a closed mouth even mid-sentence\n            dy = round(bob + bob * math.sin(2 * math.pi * t / 1.6))\n            dx = 0\n            if entrance and t < ENTRANCE_SECONDS:\n                # Swoop in from above the right side of the frame into her corner\n                p = ease_out(t / ENTRANCE_SECONDS)\n                dx, dy = round((1 - p) * width * 0.7), round(dy - (1 - p) * height * 0.6)\n            key = (face, mouth, dx, dy)\n            if key not in cache:\n                canvas = Image.new("RGBA", (box_w, box_h), (0, 0, 0, 0))\n                sprite = sprites[(face, mouth)]\n                canvas.paste(sprite, (dx, dy), sprite)          # paste clips whatever falls outside the box\n                cache[key] = canvas.tobytes()\n                if len(cache) > 400:\n                    cache.clear()\n            encoder.stdin.write(cache[key])\n    finally:\n        encoder.stdin.close()\n        encoder.wait()\n    if encoder.returncode:\n        raise RuntimeError("Could not render the host overlay")\n    return out_path, x, y\n\n\ndef speed_lines(draw, cx, cy, size, alpha):\n    for i in range(7):\n        off = (i - 3) * size * 0.09\n        length = size * (0.5 + 0.12 * (i % 3))\n        draw.line([(cx + size * 0.2, cy + off), (cx + size * 0.2 + length, cy + off - length * 0.35)],\n                  fill=(255, 255, 255, alpha), width=max(3, size // 70))\n\n\ndef star(draw, cx, cy, r, colour):\n    points = []\n    for k in range(10):\n        a = math.pi / 2 + k * math.pi / 5\n        rr = r if k % 2 == 0 else r * 0.45\n        points.append((cx + rr * math.cos(a), cy - rr * math.sin(a)))\n    draw.polygon(points, fill=colour)\n\n\ndef title_card(text, font, colour="#FFCB2F"):\n    """Big outlined title text as an RGBA image."""\n    probe = ImageDraw.Draw(Image.new("RGBA", (1, 1)))\n    box = probe.textbbox((0, 0), text, font=font, stroke_width=max(4, font.size // 10))\n    image = Image.new("RGBA", (box[2] - box[0] + 20, box[3] - box[1] + 20), (0, 0, 0, 0))\n    ImageDraw.Draw(image).text((10 - box[0], 10 - box[1]), text, font=font, fill=colour,\n                               stroke_width=max(4, font.size // 10), stroke_fill="#1C6B2E")\n    return image\n\n\ndef sky(width, height):\n    """A bright sky gradient, the backdrop she flies through."""\n    top, bottom = (78, 170, 245), (190, 232, 255)\n    column = Image.new("RGB", (1, height))\n    for y in range(height):\n        k = y / max(height - 1, 1)\n        column.putpixel((0, y), tuple(round(a + (b - a) * k) for a, b in zip(top, bottom)))\n    return column.resize((width, height))\n\n\ndef cloud(size):\n    """A soft white cloud as an RGBA image `size` pixels wide."""\n    w, h = size, size // 2\n    image = Image.new("RGBA", (w, h), (0, 0, 0, 0))\n    draw = ImageDraw.Draw(image)\n    for cx, cy, r in ((0.3, 0.62, 0.22), (0.5, 0.45, 0.28), (0.7, 0.6, 0.22), (0.5, 0.7, 0.3)):\n        draw.ellipse([w * (cx - r), h * (cy - r * 1.6), w * (cx + r), h * (cy + r * 1.6)], fill=(255, 255, 255, 235))\n    return image.filter(ImageFilter.GaussianBlur(size // 40))\n\n\nclass FlyingSky:\n    """Clouds drifting past at different speeds (near ones bigger and faster), so she seems to fly."""\n\n    def __init__(self, width, height, seed=7):\n        import random\n        rng = random.Random(seed)\n        self.width, self.height = width, height\n        self.base = sky(width, height)\n        self.clouds = []\n        for layer, (scale, speed) in enumerate(((0.18, 0.08), (0.3, 0.16), (0.45, 0.3))):\n            for _ in range(3):\n                image = cloud(round(width * scale))\n                self.clouds.append((image, rng.random(), rng.uniform(0.05, 0.85), speed * (0.8 + 0.4 * rng.random())))\n\n    def frame(self, t):\n        image = self.base.copy().convert("RGBA")\n        span = self.width * 1.6\n        for picture, start, y, speed in self.clouds:\n            x = self.width - ((start * span + t * speed * self.width) % span)\n            image.paste(picture, (round(x), round(y * self.height)), picture)\n        return image\n\n\ndef speak_line(line, voice, rate, out_path):\n    """Her line in the channel\'s voice, lively. Returns the audio\'s length in seconds."""\n    from agents import expressive_voice\n    seconds, *rest = expressive_voice.narrate(line, voice, rate, "lively", out_path)\n    return seconds\n\n\ndef effect_sources(seconds, whooshes=(), chimes=()):\n    """FFmpeg audio sources: a soft wind bed for flight, whooshes and sparkle chimes at the given times."""\n    sources = [f"anoisesrc=d={seconds}:c=brown:r=44100:a=0.5,lowpass=f=500,highpass=f=80,volume=0.25,"\n               f"afade=t=in:d=0.4,afade=t=out:st={max(seconds - 0.5, 0)}:d=0.5"]\n    for start in whooshes:\n        sources.append(f"anoisesrc=d=0.9:c=pink:r=44100:a=0.45,highpass=f=300,lowpass=f=4500,afade=t=in:d=0.3,"\n                       f"afade=t=out:st=0.35:d=0.55,adelay={int(start * 1000)}")\n    for start in chimes:\n        sources.append("aevalsrc=exprs=\'0.25*sin(2*PI*1568*t)*exp(-5*t)+0.2*sin(2*PI*2093*t)*exp(-6*t)"\n                       f"+0.15*sin(2*PI*2637*t)*exp(-7*t)\':d=1.2:s=44100,adelay={int(start * 1000)}")\n    return sources\n\n\ndef render_clip(frames_fn, size, seconds, out_path, voice_path=None, voice_at=0.0, whooshes=(), chimes=()):\n    """Encode a clip from frames_fn(t) -> RGB image, with her line (voice_path, starting at voice_at) mixed over\n    the flight sound effects."""\n    import subprocess\n    width, height = size\n    total = int(seconds * CLIP_FPS)\n    command = [ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-f", "rawvideo", "-pix_fmt", "rgb24",\n               "-s", f"{width}x{height}", "-r", str(CLIP_FPS), "-i", "pipe:0"]\n    labels, graph = [], ""\n    if voice_path:\n        command += ["-i", voice_path]\n        delay = int(voice_at * 1000)\n        graph += f"[1:a]aresample=44100,adelay={delay}|{delay},volume=1.6[voice];"\n        labels.append("[voice]")\n    effects = effect_sources(seconds, whooshes, chimes)\n    inputs_before = command.count("-i")\n    for source in effects:\n        command += ["-f", "lavfi", "-i", source]\n    for k in range(len(effects)):\n        graph += f"[{inputs_before + k}:a]aformat=channel_layouts=stereo,aresample=44100[e{k}];"\n        labels.append(f"[e{k}]")\n    graph += "".join(labels) + f"amix=inputs={len(labels)}:duration=longest:normalize=0,apad,atrim=0:{seconds}[a]"\n    command += ["-filter_complex", graph, "-map", "0:v", "-map", "[a]", "-t", f"{seconds:.3f}", "-c:v", "libx264",\n                "-preset", "veryfast", "-crf", "20", "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "160k",\n                "-ar", "44100", "-ac", "2", out_path]\n    encoder = subprocess.Popen(command, stdin=subprocess.PIPE)\n    try:\n        for frame in range(total):\n            encoder.stdin.write(frames_fn(frame / CLIP_FPS).tobytes())\n    finally:\n        encoder.stdin.close()\n        encoder.wait()\n    if encoder.returncode:\n        raise RuntimeError("Could not render the hero clip")\n    return out_path\n\n\ndef flying(sprite, t, tilt=6):\n    """Her pose in flight: a gentle sway (the drawn character tilts; photo art just bobs)."""\n    if os.path.isdir(ART_DIR) and has_art():\n        return sprite\n    angle = tilt * math.sin(2 * math.pi * t / 1.4)\n    return sprite.rotate(angle, resample=Image.BICUBIC, expand=True)\n\n\ndef talking_frames(voice_path, seconds):\n    """Mouth open/closed per CLIP_FPS frame for a line of speech."""\n    track = mouth_track(voice_path, fps=CLIP_FPS)\n    return track + [False] * max(0, int(seconds * CLIP_FPS) - len(track))\n\n\ndef render_intro(size, out_path, font_loader, voice, rate, line, name="WonderSprout!"):\n    """She swoops in through the sky, hovers, waves and says her line; her name pops up with a sparkle."""\n    width, height = size\n    work = out_path + ".voice.mp3"\n    spoken = speak_line(line, voice, rate, work)\n    swoop, speak_at = 0.9, 0.7\n    seconds = round(speak_at + spoken + 0.5, 2)\n    backdrop = FlyingSky(width, height)\n    hero_h = round(height * (0.55 if height > width else 0.68))\n    sprites = sprite_set(hero_h)\n    fly = hero_image("fly", False, hero_h) if has_art("fly") else None\n    sw, sh = sprites[("wave", False)].size\n    home_x, home_y = (width - sw) // 2, height - sh - round(height * (0.12 if height > width else 0.02))\n    title = title_card(name, font_loader(round(min(width, height) * 0.11)))\n    mouths = talking_frames(work, seconds)\n    title_at = speak_at + 0.6\n\n    def frame_at(t):\n        image = backdrop.frame(t)\n        draw = ImageDraw.Draw(image, "RGBA")\n        bob = round(sh * 0.025 * math.sin(2 * math.pi * t / 1.5))\n        if t < swoop:                                          # swoop in from the top right, trailing speed lines\n            p = ease_out(t / swoop)\n            x = round(home_x + (1 - p) * width * 0.9)\n            y = round(home_y - (1 - p) * height * 0.6)\n            speed_lines(draw, x + sw * 0.55, y + sh * 0.35, sw, int(220 * (1 - p)))\n            sprite = flying(fly or sprites[("happy", False)], t, tilt=14)\n        else:\n            spoken_frame = int((t - speak_at) * CLIP_FPS)\n            open_mouth = 0 <= spoken_frame < len(mouths) and mouths[spoken_frame]\n            pose = "wave" if int(t * 3) % 2 == 0 else "happy"\n            sprite = flying(sprites[(pose, bool(open_mouth))], t)\n            x, y = home_x, home_y + bob\n        image.paste(sprite, (x, y), sprite)\n        if t > title_at:                                        # her name pops in with a little overshoot\n            p = min((t - title_at) / 0.35, 1.0)\n            scale = 0.6 + 0.5 * ease_out(p) - 0.1 * max(0.0, p - 0.7) / 0.3\n            tw, th = max(1, round(title.width * scale)), max(1, round(title.height * scale))\n            sized = title.resize((tw, th), Image.LANCZOS)\n            image.alpha_composite(sized, ((width - tw) // 2, round(height * 0.06)))\n            for k, (sx, sy) in enumerate(((0.15, 0.1), (0.85, 0.14), (0.1, 0.28), (0.9, 0.3))):\n                twinkle = 0.6 + 0.4 * math.sin(t * 8 + k)\n                star(draw, width * sx, height * sy, min(width, height) * 0.025 * twinkle, (255, 236, 120, 230))\n        return image.convert("RGB")\n\n    try:\n        return render_clip(frame_at, size, seconds, out_path, work, speak_at, whooshes=(0.0,), chimes=(title_at,))\n    finally:\n        if os.path.exists(work):\n            os.remove(work)\n\n\ndef render_outro(size, out_path, font_loader, voice, rate, line):\n    """She hovers in the sky, waves and says goodbye, then flies off into the distance with a sparkle trail."""\n    width, height = size\n    work = out_path + ".voice.mp3"\n    spoken = speak_line(line, voice, rate, work)\n    leave_at = round(0.3 + spoken + 0.2, 2)\n    seconds = round(leave_at + 1.3, 2)\n    backdrop = FlyingSky(width, height, seed=11)\n    hero_h = round(height * (0.55 if height > width else 0.68))\n    sprites = sprite_set(hero_h)\n    fly = hero_image("fly", False, hero_h) if has_art("fly") else None\n    sw, sh = sprites[("wave", False)].size\n    home_x, home_y = (width - sw) // 2, height - sh - round(height * (0.12 if height > width else 0.02))\n    mouths = talking_frames(work, seconds)\n\n    def frame_at(t):\n        image = backdrop.frame(t)\n        draw = ImageDraw.Draw(image, "RGBA")\n        if t < leave_at:\n            frame = int((t - 0.3) * CLIP_FPS)\n            open_mouth = 0 <= frame < len(mouths) and mouths[frame]\n            pose = "wave" if int(t * 3) % 2 == 0 else "happy"\n            sprite = flying(sprites[(pose, bool(open_mouth))], t)\n            bob = round(sh * 0.025 * math.sin(2 * math.pi * t / 1.5))\n            image.paste(sprite, (home_x, home_y + bob), sprite)\n        else:                                                  # zoom off up and away, shrinking into the sky\n            p = ease_in((t - leave_at) / (seconds - leave_at))\n            scale = max(0.05, 1 - 0.95 * p)\n            sprite = flying(fly or sprites[("happy", False)], t, tilt=14)\n            small = sprite.resize((max(1, round(sprite.width * scale)), max(1, round(sprite.height * scale))))\n            cx = home_x + sw / 2 + p * width * 0.45\n            cy = home_y + sh / 2 - p * height * 0.75\n            for k in range(6):                                 # sparkle trail behind her\n                lag = k * 0.06\n                q = ease_in(max(0.0, (t - leave_at - lag)) / (seconds - leave_at))\n                star(draw, home_x + sw / 2 + q * width * 0.45, home_y + sh / 2 - q * height * 0.75,\n                     min(width, height) * 0.02 * (1 - k / 7), (255, 236, 120, 220 - k * 30))\n            image.paste(small, (round(cx - small.width / 2), round(cy - small.height / 2)), small)\n        return image.convert("RGB")\n\n    try:\n        return render_clip(frame_at, size, seconds, out_path, work, 0.3, whooshes=(leave_at - 0.1,),\n                           chimes=(leave_at + 0.2,))\n    finally:\n        if os.path.exists(work):\n            os.remove(work)\n\n\ndef ease_in(t):\n    return min(max(t, 0.0), 1.0) ** 2\n\n\nif __name__ == "__main__":\n    sheet("wondersprout_sheet.png")\n',
    'assets/wondersprout/PROMPTS.md': '# WonderSprout assets: what to provide\n\nDrop everything into Google Drive → `YouTube_Auto/wondersprout_assets/` and tell Claude. Claude imports it into\nthis folder (`assets/wondersprout/`) and pushes it to GitHub, so every run uses it. Until something is provided, the\npipeline makes its own version (a drawn cartoon WonderSprout and a generated intro and outro).\n\n## 1. Intro and outro videos (optional, recommended)\n\n| File | What it is |\n|---|---|\n| `intro.mp4` | Opens every long video. She flies in and says "Hey kids! This is Wonder Sprout, your fun and learning superhero!" |\n| `outro.mp4` | Ends every video, just before the LIKE / SUBSCRIBE card. She says "Wonder Sprout signing off, kids! We\'ll meet next time!" and flies away |\n| `intro_short.mp4`, `outro_short.mp4` | Optional vertical versions for Shorts. Without them, Shorts use the landscape files fitted on a blurred background |\n\n- **Format:** MP4 (H.264 video, AAC sound), 1920 x 1080 landscape (16:9); vertical versions 1080 x 1920 (9:16).\n- **Length:** 3 to 6 seconds each. Long intros make viewers leave before the story starts.\n- **Sound:** include the voice and sound effects in the file. (A file without sound gets silence.)\n- **Size:** under 20 MB each.\n- **Ending:** the intro should end on a clean frame (the story cuts straight in); the outro\'s last frame is used as\n  is, then the end card follows.\n- Shorts: by default Shorts don\'t play the intro (viewers swipe away from slow starts; she swoops into her corner\n  instead) but do play the outro. `intro_shorts: true` in BRAIN.md makes Shorts play it too.\n\n## 2. Expression pictures for the corner host (9 pictures)\n\nShe sits in a corner of every video and changes expression with the script, so she needs one picture per\nexpression. All 9 must be **the same character, same outfit, same framing and size**, so she doesn\'t jump when\nshe switches.\n\n| File name | Expression |\n|---|---|\n| `happy.png` | Smiling warmly, mouth closed, hands relaxed |\n| `happy_open.png` | Same, mouth open as if laughing or talking |\n| `talk.png` | Talking cheerfully to the viewer, mouth open mid-word, one hand gesturing |\n| `think.png` | Thinking: finger on her chin, eyes looking up, small closed smile |\n| `ask.png` | Asking a question: eyebrows raised, one palm held out and up, mouth slightly open |\n| `wow.png` | Amazed: big eyes, mouth open in a round "Wow!", both hands up near her cheeks |\n| `wave.png` | Waving hello with her right hand raised, closed-mouth smile |\n| `wave_open.png` | Waving with her right hand raised, mouth open saying "Hi!" |\n| `fly.png` | Flying like a superhero: body horizontal, one fist forward, legs together, hair streaming back |\n\n- **Framing:** head to knees, facing the viewer, centred, a little space around her.\n- **Background:** a transparent PNG is best. Otherwise a solid flat **magenta (#FF00FF)** background; avoid\n  green or blue backgrounds (her outfit is green and blue).\n- **Size:** at least 1024 pixels tall, PNG.\n\n### Making them with a free image AI\n\nUpload the WonderSprout reference image to the free Gemini app (gemini.google.com) or ChatGPT, and send this, plus\nthe expression from the table above:\n\n> Use the woman in the green and light-blue superhero outfit from the attached picture. Keep her face, skin tone,\n> dark wavy hair with green streaks in a high ponytail, the green and light-blue tunic with the yellow-green "WS"\n> logo, the gold utility belt with the leaf buckle, green leggings and brown boots exactly the same. Show only her,\n> from head to knees, facing the viewer, centred, with space around her. No children, no room, no text, no\n> shadow. Solid flat pure magenta (#FF00FF) background, even studio lighting. Expression:\n\nIf the face or outfit drifts, ask again with "keep her face exactly like the reference".\n\n## How Claude imports them\n\n`python execution/execution.py --hero-art "<folder>"` cuts out the backgrounds (or keeps transparent ones), drops\nan image AI\'s corner logo and any magenta fringe, crops and resizes the pictures into this folder and saves a\npreview sheet; the MP4 files get a small "WS" badge over the image AI\'s logo in the bottom-right corner.\nMissing pictures are fine: a missing expression borrows the closest one, and without a mouth-open picture she gives\na small "talking" pulse instead.\n',
    'agents/agent_5_publisher.py': 'import os\nimport re\nimport json\nfrom datetime import datetime, timedelta, timezone\nfrom google import genai\nfrom google_auth_oauthlib.flow import InstalledAppFlow\nfrom google.auth.transport.requests import Request\nfrom google.oauth2.credentials import Credentials\nfrom googleapiclient.discovery import build\nfrom googleapiclient.errors import HttpError\nfrom googleapiclient.http import MediaFileUpload\nimport time\n\nfrom agents.ai import generate_text\nfrom agents.agent_1_scout import GENERIC_HASHTAGS\nfrom agents.stock_footage import COMMONS_SITE\nfrom brain import YOUTUBE_SCOPES as SCOPES, channel_matches, item_matches\n\nUPLOAD_CHUNK_BYTES = 8 * 1024 * 1024\nUPLOAD_RETRIES = 5\nPASSED_SLOT_GAP = timedelta(minutes=30)\nMAX_HASHTAGS = 12\nMAX_DESCRIPTION = 4900\n# Words too general to make a search phrase relevant to a video on their own (without a final "s", as compared:\n# "kids" -> "kid", "this" -> "thi", "news" -> "new")\nKEYWORD_FILLER = {"kid", "children", "short", "video", "with", "from", "thi", "that", "what", "your", "new",\n                  "today", "latest", "best", "funny", "story", "fact", "update"}\n\nclass PublisherAgent:\n    def __init__(self, config, instructions):\n        self.config = config\n        self.instructions = instructions\n        self.active_key = config["active_profile"]\n        self.profile = config["profiles"][self.active_key]\n        self.upload_rules = config["upload_rules"]\n        self.paths = config["storage_paths"]\n        self.ai_client = genai.Client(api_key=os.getenv("GEMINI_API_KEY"))\n\n    def get_authenticated_service(self):\n        tokens_dir = self.paths.get("tokens_dir", ".")\n        token_file = os.path.join(tokens_dir, f"token_{self.active_key}.json")\n        creds = None\n\n        if os.path.exists(token_file):\n            creds = Credentials.from_authorized_user_file(token_file, SCOPES)\n\n        if not creds or not creds.valid:\n            if creds and creds.expired and creds.refresh_token:\n                creds.refresh(Request())\n            else:\n                if os.getenv("GITHUB_ACTIONS") == "true":\n                    raise RuntimeError(\n                        f"YouTube login for \'{self.active_key}\' is missing or expired. Run "\n                        f"\'python execution/execution.py --authorize {self.active_key}\' on your laptop "\n                        "and upload the token file to Google Drive: YouTube_Automation/00_tokens/"\n                    )\n                print(f"\\n[!] Please select the \'{self.profile[\'channel_name\']}\' Brand Channel in the browser popup!")\n                flow = InstalledAppFlow.from_client_secrets_file("client_secret.json", SCOPES)\n                creds = flow.run_local_server(port=0)\n            os.makedirs(tokens_dir, exist_ok=True)\n            with open(token_file, "w") as token:\n                token.write(creds.to_json())\n\n        youtube = build("youtube", "v3", credentials=creds)\n        self.verify_channel(youtube)\n        return youtube\n\n    def verify_channel(self, youtube):\n        # Stop before uploading if this login belongs to a different channel than channels.yaml says\n        items = youtube.channels().list(part="snippet", mine=True).execute().get("items", [])\n        if not items:\n            raise RuntimeError(f"The YouTube login for \'{self.active_key}\' has no channel.")\n        channel_id, snippet = items[0]["id"], items[0]["snippet"]\n        if not channel_matches(self.profile["channel_url"], channel_id, snippet.get("customUrl")):\n            raise RuntimeError(\n                f"The YouTube login for \'{self.active_key}\' is for \'{snippet[\'title\']}\' ({channel_id}), "\n                f"not {self.profile[\'channel_url\']}. Run --authorize {self.active_key} again and pick the right channel."\n            )\n        print(f"[Agent 5: Publisher] Confirmed channel: {snippet[\'title\']}")\n\n    @staticmethod\n    def fallback_seo_package(item, max_title):\n        """Used when Gemini is unavailable: the source video\'s own title, and the opening of our narration."""\n        title = re.sub(r"#\\w+", "", item.get("original_title") or "").replace(\'"\', "")\n        title = " ".join(title.split()).strip(" |-:") or "New video"\n        if len(title) > max_title:\n            title = title[:max_title - 3].rsplit(" ", 1)[0] + "..."\n        script = " ".join((item.get("generated_script") or "").split())\n        sentences = [s.strip() for s in re.split(r"(?<=[.!?])\\s+", script) if s.strip()]\n        return title, " ".join(sentences[:2])[:400]\n\n    def generate_seo_package(self, item):\n        max_title = 75 if item.get("format") == "long" else 65\n        if item.get("seo_title"):\n            # Written together with the script, so no extra Gemini request is needed\n            new_title = item["seo_title"].replace(\'"\', \'\').strip()[:max_title]\n            return new_title, self.finish_description(item, item.get("seo_description") or "",\n                                                      item.get("seo_hashtags") or "")\n\n        prompt = (\n            f"Follow these system instructions: {self.instructions}\\n"\n            f"Profile: {self.active_key}\\n"\n            f"Original Title: {item[\'original_title\']}\\n"\n            f"Our Voiceover Script: {item[\'generated_script\']}\\n"\n            f"Language for title, description and hashtags: {self.profile.get(\'language\', \'English\')}\\n\\n"\n            + ("Generate a click-worthy YouTube video title (maximum 70 characters, no quotes) on Line 1.\\n"\n               "On the following lines, write a 3-sentence SEO description followed by 5 relevant hashtags "\n               "(do not use #shorts)."\n               if item.get("format") == "long" else\n               "Generate a viral YouTube Short Title (maximum 60 characters, no quotes) on Line 1.\\n"\n               "On the following lines, write a 2-sentence SEO description followed by 5 relevant hashtags.")\n        )\n        try:\n            resp = generate_text(self.ai_client, prompt, self.config.get("ai_models")).split("\\n")\n            new_title = resp[0].replace(\'"\', \'\').strip()[:max_title]\n            seo_body = "\\n".join(resp[1:]).strip()\n        except Exception as e:\n            # Gemini quota ran out or it is down: the video is already rendered, so publish it under the\n            # source video\'s title instead of losing the slot\n            print(f"[Agent 5: Publisher] The AI could not write the title for {item[\'video_id\']}, "\n                  f"using the source video\'s title: {str(e)[:160]}")\n            new_title, seo_body = self.fallback_seo_package(item, max_title)\n\n        # Gemini\'s hashtags may sit inside the text; gather them so they are merged with the trending ones\n        gemini_tags = " ".join(re.findall(r"#\\w+", seo_body))\n        seo_body = "\\n".join(line for line in seo_body.splitlines() if not re.fullmatch(r"(\\s*#\\w+)+\\s*", line))\n        return new_title, self.finish_description(item, seo_body.strip(), gemini_tags)\n\n    def hashtags(self, item, gemini_tags):\n        """Hashtags for reach: what is trending in the niche right now, the video\'s own topic, and the source\'s.\n\n        YouTube shows the first three above the title, so they are the two strongest trending niche tags and the\n        strongest topic tag; then #shorts (Shorts), the other topic tags, the rest of the trending ones and the\n        source video\'s. Generic tags (#viral, #fyp) and other channels\' names are left out; at most MAX_HASHTAGS.\n        """\n        source_text = f"{item.get(\'original_title\') or \'\'} {item.get(\'original_description\') or \'\'}"\n        creator = re.sub(r"\\W", "", (item.get("original_creator") or "").lower())\n        source = [t for t in re.findall(r"#\\w+", source_text)\n                  if not (creator and (creator in t.lower() or t.lower().lstrip("#") in creator))\n                  and t.lower() not in GENERIC_HASHTAGS]\n        niche = list(item.get("trending_hashtags") or [])\n        topic = re.findall(r"#\\w+", gemini_tags)\n        tags = (niche[:2] + topic[:1] + (["#shorts"] if item.get("format") != "long" else [])\n                + topic[1:] + niche[2:] + source)\n        if len(tags) <= 1:\n            # Nothing from Gemini or the source: fall back to the channel\'s niche words\n            tags += ["#" + w.lower() for w in re.findall(r"[A-Za-z]{4,}", self.profile.get("niche", ""))][:4]\n        unique = {}\n        for tag in tags:\n            if item.get("format") == "long" and tag.lower() == "#shorts":\n                continue\n            unique.setdefault(tag.lower(), tag)\n        return list(unique.values())[:MAX_HASHTAGS]\n\n    @staticmethod\n    def relevant_keywords(item):\n        """The Scout\'s search phrases (autocomplete, rising videos\' tags) that are about this video.\n\n        A phrase is kept only when every word of 4+ letters in it (besides general ones like "kids") is in the\n        video\'s title, keywords, hashtags or script, so the tags never promise something the video isn\'t about\n        and never carry other channels\' names.\n        """\n        def words(text):\n            return {w.rstrip("s") for w in re.findall(r"\\w{4,}", text.lower())} - KEYWORD_FILLER\n\n        own = words(" ".join([item.get("seo_title") or "", item.get("seo_keyword") or "",\n                              " ".join(item.get("seo_keywords") or []), item.get("seo_hashtags") or "",\n                              item.get("generated_script") or ""]))\n        return [k for k in item.get("search_keywords") or [] if words(k) and words(k) <= own]\n\n    def search_tags(self, item):\n        """YouTube\'s hidden search tags, strongest first: the video\'s search keyword and its variations, the real\n        search phrases that fit it, the hashtags as words, the footage topic terms and the channel name."""\n        keyword = [item["seo_keyword"]] if item.get("seo_keyword") else []\n        tags = keyword + list(item.get("seo_keywords") or []) + self.relevant_keywords(item) + \\\n            [t.lstrip("#") for t in item.get("upload_hashtags") or []] + list(item.get("topic_terms") or []) + \\\n            [self.profile["channel_name"].replace(" ", "")]\n        kept, seen, length = [], set(), 0\n        # YouTube rejects tags with < or > and splits them at commas\n        for tag in (" ".join(re.sub(r"[<>,]", " ", t).split()) for t in tags):\n            if not tag or tag.lower() in seen:\n                continue\n            # YouTube rejects the upload if the tags add up to more than 500 characters; shorter ones may still fit\n            if length + len(tag) + 3 > 450:\n                continue\n            seen.add(tag.lower())\n            kept.append(tag)\n            length += len(tag) + 3\n        return kept\n\n    def finish_description(self, item, text, gemini_tags):\n        tags = self.hashtags(item, gemini_tags)\n        item["upload_hashtags"] = tags\n        credit = self.credit_block(item)\n        # YouTube rejects descriptions over 5,000 characters: shorten the AI text, never the hashtags or credits\n        room = MAX_DESCRIPTION - len(credit) - len(" ".join(tags)) - 4\n        if len(text) > room:\n            text = text[:max(room - 3, 0)].rstrip() + "..."\n        return "\\n\\n".join(p for p in (text, " ".join(tags)) if p) + credit\n\n    @staticmethod\n    def credit_block(item):\n        """Credits only for real footage and photos of the actual events (Wikimedia Commons, e.g. Frontline).\n\n        Stock sites (Pixabay, Pexels) and music get no credits section (owner\'s decision, 2026-10-31).\n        """\n        commons = (item.get("footage_sources") or {}).get(COMMONS_SITE) if item.get("footage_paths") else None\n        if not commons:\n            return ""\n        # CC BY asks for the author, the licence and a link; public domain clips are credited too\n        lines = ["", "", "---", "Real footage and photos via Wikimedia Commons (free licences):"]\n        return "\\n".join(lines + [f"- {credit}" for credit in commons])\n\n    @staticmethod\n    def upload(youtube, path, body):\n        """Upload in 8 MB chunks, resuming after dropped connections, so long videos survive a shaky network."""\n        media = MediaFileUpload(path, chunksize=UPLOAD_CHUNK_BYTES, resumable=True)\n        request = youtube.videos().insert(part="snippet,status", body=body, media_body=media)\n        response, failures = None, 0\n        while response is None:\n            try:\n                status, response = request.next_chunk()\n                failures = 0\n                if status:\n                    print(f"[Agent 5: Publisher] Uploaded {int(status.progress() * 100)}%")\n            except (HttpError, OSError) as e:\n                retryable = not isinstance(e, HttpError) or e.resp.status in (500, 502, 503, 504)\n                failures += 1\n                if not retryable or failures > UPLOAD_RETRIES:\n                    raise\n                print(f"[Agent 5: Publisher] Upload interrupted ({e}); resuming in {10 * failures}s...")\n                time.sleep(10 * failures)\n        return response\n\n    def scheduled_publish_time(self, index, now=None):\n        """Go-live time for the index-th video of this run, or None to publish immediately.\n\n        execution.py sets publish_plan to either\n          {"first_utc": ISO time, "interval_minutes": gap}: slots repeat every interval from first_utc, and if\n          preparing the videos took past some slots, the next future slot is used (Shorts); or\n          {"times_utc": [ISO times]}: this run\'s go-live slots, one per video. A slot that passed while the\n          videos were being made (GitHub often starts scheduled runs hours late) goes live soon instead, keeping\n          at least PASSED_SLOT_GAP between videos.\n        """\n        plan = self.profile.get("publish_plan")\n        if not plan:\n            return None\n        if "times_utc" in plan:\n            earliest = (now or datetime.now(timezone.utc)) + timedelta(minutes=10)\n            slots, previous = [], None\n            for t in sorted(datetime.fromisoformat(t) for t in plan["times_utc"]):\n                if t < earliest:\n                    t = earliest if previous is None else max(earliest, previous + PASSED_SLOT_GAP)\n                elif previous is not None and t < previous + PASSED_SLOT_GAP:\n                    t = previous + PASSED_SLOT_GAP\n                slots.append(t)\n                previous = t\n            return slots[index] if index < len(slots) else None\n        first = datetime.fromisoformat(plan["first_utc"])\n        interval = timedelta(minutes=plan.get("interval_minutes") or 0)\n        earliest = (now or datetime.now(timezone.utc)) + timedelta(minutes=10)\n\n        if first < earliest:\n            if not interval:\n                return None\n            missed_slots = -((first - earliest) // interval)\n            first += interval * missed_slots\n        return first + interval * index\n\n    def run(self):\n        manifest_path = self.paths["manifest_file"]\n        with open(manifest_path, "r", encoding="utf-8") as f:\n            trends = json.load(f)\n\n        items_to_publish = [\n            i for i in trends if i["status"] == "edited" and item_matches(i, self.active_key, self.profile)\n        ]\n        # A finished video whose file was deleted (e.g. an old day folder) can\'t be uploaded any more\n        for item in [i for i in items_to_publish if not os.path.exists(i.get("edited_video_path") or "")]:\n            print(f"[Agent 5: Publisher] Skipping {item[\'video_id\']}: its edited video file no longer exists.")\n            item["status"] = "expired"\n            items_to_publish.remove(item)\n        plan = self.profile.get("publish_plan") or {}\n        if "times_utc" in plan and len(items_to_publish) > len(plan["times_utc"]):\n            # This run has a fixed number of go-live slots; the oldest finished videos fill them first and\n            # the rest wait for the next run\n            waiting = len(items_to_publish) - len(plan["times_utc"])\n            items_to_publish = items_to_publish[:len(plan["times_utc"])]\n            print(f"[Agent 5: Publisher] {waiting} more finished video(s) will be uploaded in a later run.")\n        if not items_to_publish:\n            print("[Agent 5: Publisher] No edited videos pending upload.")\n            return\n\n        youtube = self.get_authenticated_service()\n\n        for index, item in enumerate(items_to_publish):\n            vid_id = item["video_id"]\n            try:\n                title, description = self.generate_seo_package(item)\n            except Exception as e:\n                # The video stays "edited" and is uploaded on the next run\n                print(f"[Agent 5: Publisher] Could not write the title for {vid_id}, will retry next run: {e}")\n                continue\n\n            body = {\n                "snippet": {\n                    "title": title,\n                    "description": description,\n                    "categoryId": self.profile["category_id"],\n                    "tags": self.search_tags(item)\n                },\n                "status": {\n                    "privacyStatus": self.profile.get("privacy_status", self.upload_rules["privacy_status"]),\n                    "selfDeclaredMadeForKids": self.profile["made_for_kids"],\n                    "containsSyntheticMedia": self.upload_rules["synthetic_media_disclosure"]\n                }\n            }\n\n            publish_at = self.scheduled_publish_time(index)\n            if publish_at:\n                # YouTube only accepts publishAt on private videos; it flips them public at that time\n                body["status"]["privacyStatus"] = "private"\n                body["status"]["publishAt"] = publish_at.strftime("%Y-%m-%dT%H:%M:%SZ")\n                print(f"[Agent 5: Publisher] Scheduled to go public at {body[\'status\'][\'publishAt\']}")\n\n            print(f"\\n[Agent 5: Publisher] Uploading \'{title}\' to {self.profile[\'channel_name\']}...")\n            try:\n                response = self.upload(youtube, item["edited_video_path"], body)\n                item["uploaded_youtube_id"] = response["id"]\n                item["uploaded_title"] = title\n                item["uploaded_tags"] = body["snippet"]["tags"]\n                item["publish_at"] = body["status"].get("publishAt")\n                item["uploaded_at"] = datetime.now(timezone.utc).isoformat()\n                item["status"] = "published"\n                print(f"[Agent 5: Publisher] SUCCESS! Uploaded Video ID: {response[\'id\']}")\n            except Exception as e:\n                print(f"[Agent 5: Publisher] Upload failed for {vid_id}: {e}")\n\n        with open(manifest_path, "w", encoding="utf-8") as f:\n            json.dump(trends, f, indent=4, ensure_ascii=False)\n',
    'agents/agent_6_cleanup.py': 'import os\nimport re\nimport json\nimport shutil\nfrom datetime import datetime, timedelta, timezone\n\n# Videos still waiting for a later step; if their files are gone they can never finish\nUNFINISHED = ("downloaded", "voiced", "ready_to_edit", "edited")\nFILE_FOR_STATUS = {"downloaded": "raw_video_path", "voiced": "voiceover_path",\n                   "ready_to_edit": "raw_video_path", "edited": "edited_video_path"}\n\n\ndef required_files(item):\n    """The files a video still needs for its next step."""\n    status = item.get("status")\n    if status == "ready_to_edit":\n        return [item.get("voiceover_path")] + list(item.get("footage_paths") or [])\n    if status in FILE_FOR_STATUS:\n        return [item.get(FILE_FOR_STATUS[status])]\n    return []\n\n\ndef expire_missing_files(items):\n    """Mark unfinished videos whose files are gone as "expired", so they stop counting toward the day\'s videos.\n\n    GitHub runs start on a fresh machine and only finished ("edited") videos are carried over through Google Drive,\n    so a video left half-done by an interrupted run can never be completed.\n    """\n    expired = 0\n    for item in items:\n        if item.get("status") in UNFINISHED and not all(f and os.path.exists(f) for f in required_files(item)):\n            item["status"] = "expired"\n            expired += 1\n    return expired\n\nclass CleanupAgent:\n    def __init__(self, config):\n        self.config = config\n        self.paths = config["storage_paths"]\n        self.cleanup_rules = config.get("cleanup_rules", {\n            "delete_raw_after_publish": True,\n            "delete_voiceover_after_publish": True,\n            "delete_edited_from_previous_dates": True\n        })\n\n    def _safe_remove(self, file_path):\n        if file_path and os.path.exists(file_path):\n            try:\n                os.remove(file_path)\n                print(f"[Agent 6: Cleanup] Deleted file: {file_path}")\n                return True\n            except Exception as e:\n                print(f"[Agent 6: Cleanup] Failed to delete {file_path}: {e}")\n        return False\n\n    def remove_old_date_folders(self):\n        """Local runs: delete whole YouTube_Auto/<YYYY-MM-DD> folders older than local_media.keep_days."""\n        media = self.config.get("local_media") or {}\n        root = self.config.get("media_root")\n        keep_days = int(media.get("keep_days", 2))\n        if not root or not os.path.isdir(root):\n            return 0\n        oldest_kept = (datetime.now() - timedelta(days=keep_days - 1)).strftime("%Y-%m-%d")\n        removed = 0\n        for name in sorted(os.listdir(root)):\n            if re.fullmatch(r"\\d{4}-\\d{2}-\\d{2}", name) and name < oldest_kept:\n                try:\n                    shutil.rmtree(os.path.join(root, name))\n                    print(f"[Agent 6: Cleanup] Deleted folder older than {keep_days} days: {os.path.join(root, name)}")\n                    removed += 1\n                except Exception as e:\n                    print(f"[Agent 6: Cleanup] Failed to delete {name}: {e}")\n        return removed\n\n    def run(self):\n        manifest_path = self.paths["manifest_file"]\n        if not os.path.exists(manifest_path):\n            return\n\n        local = self.config.get("storage_mode") == "local"\n        print("\\n[Agent 6: Cleanup] " + ("Removing date folders past the keep period..." if local\n                                         else "Scanning manifest for published & previous-date videos..."))\n        removed_folders = self.remove_old_date_folders() if local else 0\n\n        with open(manifest_path, "r", encoding="utf-8") as f:\n            trends = json.load(f)\n\n        today_str = datetime.now(timezone.utc).strftime("%Y-%m-%d")\n        cleaned_count = expired = 0\n\n        for item in trends:\n            status = item.get("status")\n            if local:\n                # Files are kept in the date folders until those are deleted as a whole\n                for field in ("raw_video_path", "voiceover_path", "edited_video_path"):\n                    if item.get(field) and not os.path.exists(item[field]):\n                        item[field] = None\n                if status in UNFINISHED and not item.get(FILE_FOR_STATUS[status]):\n                    item["status"] = "expired"\n                    expired += 1\n                continue\n\n            if status == "published":\n                discovered_date = item.get("discovered_at", "")[:10]\n                is_previous_date = (discovered_date != "" and discovered_date < today_str)\n\n                if self.cleanup_rules.get("delete_raw_after_publish", True):\n                    for clip in item.get("footage_paths") or []:\n                        self._safe_remove(clip)\n                    if self._safe_remove(item.get("raw_video_path")) or item.get("footage_paths"):\n                        item["raw_video_path"] = None\n                        item["footage_paths"] = []\n                        cleaned_count += 1\n\n                if self.cleanup_rules.get("delete_voiceover_after_publish", True):\n                    if self._safe_remove(item.get("voiceover_path")):\n                        item["voiceover_path"] = None\n\n                # Published videos live on YouTube; deleting the file keeps it from being synced to Drive every run\n                delete_edited = (self.cleanup_rules.get("delete_edited_after_publish", True)\n                                 or (self.cleanup_rules.get("delete_edited_from_previous_dates", True)\n                                     and is_previous_date))\n                if delete_edited and self._safe_remove(item.get("edited_video_path")):\n                    item["edited_video_path"] = None\n\n            elif status == "download_failed":\n                discovered_date = item.get("discovered_at", "")[:10]\n                if discovered_date and discovered_date < today_str:\n                    self._safe_remove(item.get("raw_video_path"))\n                    item["raw_video_path"] = None\n\n        with open(manifest_path, "w", encoding="utf-8") as f:\n            json.dump(trends, f, indent=4, ensure_ascii=False)\n\n        if local:\n            print(f"[Agent 6: Cleanup] Cleanup complete. Removed {removed_folders} old date folder(s); "\n                  f"{expired} unfinished video(s) expired with them.")\n        else:\n            print(f"[Agent 6: Cleanup] Cleanup complete. Purged {cleaned_count} published raw video sets.")\n',
    'agents/agent_7_notifier.py': 'import os\nimport html\nimport json\nimport requests\nfrom datetime import datetime\nfrom zoneinfo import ZoneInfo\n\n\ndef send_telegram(html_text):\n    """Post a message (Telegram HTML) to the channel in TELEGRAM_CHANNEL_ID; never stops the run on failure."""\n    bot_token, channel_id = os.getenv("TELEGRAM_BOT_TOKEN"), os.getenv("TELEGRAM_CHANNEL_ID")\n    if not bot_token or not channel_id:\n        print("[Agent 7: Telegram] Skipping alert: Missing TELEGRAM_BOT_TOKEN or TELEGRAM_CHANNEL_ID.")\n        return\n    payload = {"chat_id": channel_id, "text": html_text, "parse_mode": "HTML", "disable_web_page_preview": True}\n    try:\n        resp = requests.post(f"https://api.telegram.org/bot{bot_token}/sendMessage", json=payload, timeout=15)\n        if resp.status_code == 200:\n            print("[Agent 7: Telegram] Alert posted to Telegram channel!")\n        else:\n            print(f"[Agent 7: Telegram] API Error: {resp.text}")\n    except Exception as e:\n        # The exception text can contain the request URL, which includes the bot token\n        print(f"[Agent 7: Telegram] Failed to send Telegram alert: {str(e).replace(bot_token, \'***\')}")\n\n\nclass TelegramNotifierAgent:\n    def __init__(self, config):\n        self.config = config\n        self.active_key = config["active_profile"]\n        self.profile = config["profiles"][self.active_key]\n        self.paths = config["storage_paths"]\n\n    def go_live_text(self, item):\n        if not item.get("publish_at"):\n            return "live now"\n        tz = ZoneInfo(self.profile["schedule"]["timezone"])\n        when = datetime.fromisoformat(item["publish_at"].replace("Z", "+00:00")).astimezone(tz)\n        day = "today" if when.date() == datetime.now(tz).date() else f"{when:%d %b}"\n        return f"goes live {day} {when:%H:%M} {when:%Z}"\n\n    def run(self, uploaded, planned=None):\n        """One message for this channel: the videos this run uploaded and when each one goes live."""\n        uploaded = sorted(uploaded, key=lambda i: i.get("publish_at") or "")\n        planned = planned if planned is not None else len(uploaded)\n        icon = "✅" if uploaded and len(uploaded) >= planned else "⚠️"\n        lines = [f"{icon} <b>{html.escape(self.profile[\'channel_name\'])}</b>: "\n                 f"{len(uploaded)} of {planned} video(s) uploaded and scheduled"]\n        for idx, item in enumerate(uploaded, 1):\n            long = item.get("format") == "long"\n            yt_id = item.get("uploaded_youtube_id")\n            url = f"https://youtube.com/{\'watch?v=\' if long else \'shorts/\'}{yt_id}"\n            title = item.get("uploaded_title") or item.get("original_title") or yt_id\n            tags = " ".join(item.get("upload_hashtags") or [])\n            keyword = item.get("seo_keyword")\n            lines.append(f"\\n{idx}. {\'🎬 Long video\' if long else \'📱 Short\'}, {self.go_live_text(item)}\\n"\n                         f"<b>{html.escape(title)}</b>\\n🔗 {url}"\n                         + (f"\\n📌 Your request {item[\'request_id\']}" if item.get("request_id") else "")\n                         + (f"\\n🔎 {html.escape(keyword)}" if keyword else "")\n                         + (f"\\n🏷 {html.escape(tags)}" if tags else ""))\n        if len(uploaded) < planned:\n            lines.append(f"\\n{planned - len(uploaded)} video(s) were not uploaded. Check the GitHub run log, "\n                         "step 8, for the [Agent ...] lines explaining why.")\n        send_telegram("\\n".join(lines))\n\n        if not uploaded:\n            return\n        manifest_path = self.paths["manifest_file"]\n        with open(manifest_path, "r", encoding="utf-8") as f:\n            trends = json.load(f)\n        ids = {item["video_id"] for item in uploaded}\n        for item in trends:\n            if item.get("video_id") in ids and item.get("profile") == self.active_key:\n                item["notified_telegram"] = True\n        with open(manifest_path, "w", encoding="utf-8") as f:\n            json.dump(trends, f, indent=4, ensure_ascii=False)\n',
    'agents/agent_8_analyst.py': '"""Agent 8, Analyst: records how every uploaded video performs and feeds it back into topic choice.\n\nAfter each run it reads the public view, like and comment counts of the channel\'s recent uploads (1 YouTube quota\nunit per 50 videos) and stores them in the manifest. Each video\'s views at its first check after 48 hours\n(views_48h) score the search phrase that found its topic, and the Scout tries the best-scoring phrases first.\nOnce a day it posts a short performance report to Telegram.\n"""\nimport html\nimport json\nimport os\nfrom datetime import datetime, timedelta, timezone\nfrom zoneinfo import ZoneInfo\n\n# Views are tracked for this many days after upload\nTRACK_DAYS = 14\n# A video\'s views are scored once it has been live this long\nSCORE_HOURS = 48\n# A phrase not used for this long is tried again first, so a phrase that did badly once gets another chance\nSTALE_DAYS = 3\n# Only a phrase\'s most recent scored videos count, so its score follows current trends\nSCORE_WINDOW = 8\nREPORT_DAYS = 7\n\n\ndef parse_time(value):\n    return datetime.fromisoformat(value.replace("Z", "+00:00")) if value else None\n\n\ndef live_since(item):\n    """When the video went public: its scheduled go-live time, or its upload time if it went live at once."""\n    return parse_time(item.get("publish_at")) or parse_time(item.get("uploaded_at"))\n\n\ndef phrase_scores(items):\n    """{phrase: average views_48h of its latest scored videos}."""\n    scored = {}\n    for item in sorted(items, key=lambda i: i.get("discovered_at", "")):\n        if item.get("views_48h") is not None:\n            scored.setdefault(item.get("genre"), []).append(item["views_48h"])\n    return {phrase: sum(v[-SCORE_WINDOW:]) / len(v[-SCORE_WINDOW:]) for phrase, v in scored.items()}\n\n\ndef order_phrases(phrases, items, now=None):\n    """Search phrases in the order the Scout should use them.\n\n    Phrases that are untried, unscored or unused for STALE_DAYS come first (least recently used first), so every\n    phrase keeps getting tested as trends change; then the rest, best average views first.\n    """\n    now = now or datetime.now(timezone.utc)\n    scores = phrase_scores(items)\n    last_used = {}\n    for item in items:\n        found = parse_time(item.get("discovered_at"))\n        if found and (item.get("genre") not in last_used or found > last_used[item.get("genre")]):\n            last_used[item.get("genre")] = found\n    oldest = datetime.min.replace(tzinfo=timezone.utc)\n\n    def explore(phrase):\n        return phrase not in scores or now - last_used.get(phrase, oldest) > timedelta(days=STALE_DAYS)\n\n    fresh = sorted((p for p in phrases if explore(p)), key=lambda p: last_used.get(p, oldest))\n    proven = sorted((p for p in phrases if not explore(p)), key=lambda p: -scores[p])\n    return fresh + proven\n\n\nclass AnalystAgent:\n    def __init__(self, config):\n        self.config = config\n        self.paths = config["storage_paths"]\n        self.state_file = os.path.join(os.path.dirname(self.paths["manifest_file"]), "analyst_state.json")\n\n    def fetch_stats(self, video_ids):\n        from googleapiclient.discovery import build\n        youtube = build("youtube", "v3", developerKey=os.getenv("YOUTUBE_API_KEY"))\n        stats = {}\n        for start in range(0, len(video_ids), 50):\n            response = youtube.videos().list(part="statistics", id=",".join(video_ids[start:start + 50])).execute()\n            stats.update({v["id"]: v.get("statistics", {}) for v in response.get("items", [])})\n        return stats\n\n    def update(self, items, now=None):\n        """Store current stats on every tracked video; returns how many were updated."""\n        now = now or datetime.now(timezone.utc)\n        tracked = {}\n        for item in items:\n            since = live_since(item)\n            if (item.get("status") == "published" and item.get("uploaded_youtube_id") and since\n                    and since <= now and now - since <= timedelta(days=TRACK_DAYS)):\n                tracked[item["uploaded_youtube_id"]] = item\n        if not tracked:\n            return 0\n        stats = self.fetch_stats(list(tracked))\n        for yt_id, item in tracked.items():\n            if yt_id not in stats:\n                continue  # private, removed, or not processed yet\n            s = stats[yt_id]\n            hours = round((now - live_since(item)).total_seconds() / 3600, 1)\n            item["stats"] = {"views": int(s.get("viewCount", 0)), "likes": int(s.get("likeCount", 0)),\n                             "comments": int(s.get("commentCount", 0)), "hours_live": hours,\n                             "checked_at": now.isoformat()}\n            if hours >= SCORE_HOURS and item.get("views_48h") is None:\n                item["views_48h"] = item["stats"]["views"]\n        return len(tracked)\n\n    def report(self, items, profiles, now=None):\n        """Telegram text: last REPORT_DAYS days per channel, best video, best and weakest search phrase."""\n        now = now or datetime.now(timezone.utc)\n        lines = [f"📊 <b>Daily report</b> (videos live in the last {REPORT_DAYS} days)"]\n        for key, profile in profiles.items():\n            recent = [i for i in items if i.get("profile") == key and i.get("stats")\n                      and now - live_since(i) <= timedelta(days=REPORT_DAYS)]\n            if not recent:\n                continue\n            views = sum(i["stats"]["views"] for i in recent)\n            best = max(recent, key=lambda i: i["stats"]["views"])\n            lines.append(f"\\n<b>{html.escape(profile[\'channel_name\'])}</b>: {len(recent)} videos, {views:,} views "\n                         f"(avg {views // len(recent):,})")\n            title = html.escape((best.get("uploaded_title") or best.get("original_title") or "")[:60])\n            lines.append(f"🏆 {title}: "\n                         f"{best[\'stats\'][\'views\']:,} views ({best.get(\'format\', \'short\')})")\n            scores = phrase_scores([i for i in items if i.get("profile") == key])\n            if len(scores) >= 2:\n                top, low = max(scores, key=scores.get), min(scores, key=scores.get)\n                name = {p: html.escape(p.replace("#shorts", "").strip()) for p in (top, low)}\n                lines.append(f"📈 Best topic: {name[top]} ({scores[top]:.0f} views at 48h)")\n                lines.append(f"📉 Weakest: {name[low]} ({scores[low]:.0f})")\n        return "\\n".join(lines) if len(lines) > 1 else None\n\n    def run(self, keys, now=None):\n        now = now or datetime.now(timezone.utc)\n        path = self.paths["manifest_file"]\n        if not os.path.exists(path):\n            return\n        with open(path, "r", encoding="utf-8") as f:\n            items = json.load(f)\n        try:\n            count = self.update([i for i in items if i.get("profile") in keys], now)\n        except Exception as e:\n            print(f"[Agent 8: Analyst] Could not read video statistics: {e}")\n            return\n        with open(path, "w", encoding="utf-8") as f:\n            json.dump(items, f, indent=4, ensure_ascii=False)\n        print(f"[Agent 8: Analyst] Updated views for {count} recent video(s).")\n\n        # One report a day, from the first run of the day in the channels\' timezone\n        profiles = {k: self.config["profiles"][k] for k in keys}\n        tz = ZoneInfo(next(iter(profiles.values()))["schedule"]["timezone"])\n        today = now.astimezone(tz).date().isoformat()\n        state = {}\n        if os.path.exists(self.state_file):\n            with open(self.state_file, "r", encoding="utf-8") as f:\n                state = json.load(f)\n        if state.get("last_report") == today:\n            return\n        text = self.report(items, profiles, now)\n        if text:\n            from agents.agent_7_notifier import send_telegram\n            send_telegram(text)\n        state["last_report"] = today\n        with open(self.state_file, "w", encoding="utf-8") as f:\n            json.dump(state, f, indent=4)\n',
    'execution/execution.py': '"""The single entry point for the YouTube automation pipeline. Read execution/execution.md first.\n\nAnswers to every question live in execution/questions.yaml; this file reads them each time it runs.\n\n    python execution/execution.py                        # run every channel with run: true in questions.yaml\n    python execution/execution.py --channel kids_edu     # run one channel (or --channel all)\n    python execution/execution.py --check                # validate both pages, show the plan, update GitHub schedule\n    python execution/execution.py --list                 # show channels and their posting plans\n    python execution/execution.py --authorize kids_edu   # sign in to YouTube for a channel (once)\n    python execution/execution.py --ask                  # answer the questions interactively for a one-off run\n    python execution/execution.py --learn <youtube link> # analyse a video about getting views (view_techniques.md)\n    python execution/execution.py --inbox                # handle links and requests posted in the Telegram channel\n    python execution/execution.py --hero-art <folder>    # import WonderSprout character pictures (assets/wondersprout)\n\nOne-off overrides for a run: --genre "..." --videos 6 --frequency "30 mins" --first-post "09:00" --dry-run\nGitHub uses: --scheduled --cron "<cron>"  and  --due --cron "<cron>"\n"""\nimport argparse\nimport copy\nimport html\nimport os\nimport re\nimport sys\n\nif hasattr(sys.stdout, "reconfigure"):\n    try:\n        sys.stdout.reconfigure(encoding="utf-8", errors="replace")\n    except Exception:\n        pass\nif hasattr(sys.stderr, "reconfigure"):\n    try:\n        sys.stderr.reconfigure(encoding="utf-8", errors="replace")\n    except Exception:\n        pass\n\nfrom datetime import datetime, timedelta, timezone\nfrom zoneinfo import ZoneInfo\n\nEXECUTION_DIR = os.path.dirname(os.path.abspath(__file__))\nPROJECT_DIR = os.path.dirname(EXECUTION_DIR)\nREPO_DIR = os.path.dirname(PROJECT_DIR)\nWORKFLOW_FILE = os.path.join(REPO_DIR, ".github", "workflows", "daily_youtube_agents.yml")\n\nsys.path.insert(0, PROJECT_DIR)\n# The agents use paths relative to the project folder, wherever this file is started from\nos.chdir(PROJECT_DIR)\n\nfrom brain import (  # noqa: E402\n    DEFAULT_VOICES, FREQUENCIES, LANGUAGES, MAX_VIDEOS_PER_DAY, SPEEDS, YOUTUBE_SCOPES,\n    channel_matches, cron_lines, due_profiles, fetch_time_for_cron, load_brain, parse_time,\n)\n\nSCHEDULE_BEGIN = "# BEGIN CHANNEL SCHEDULE"\nSCHEDULE_END = "# END CHANNEL SCHEDULE"\nRUNNING_ON_GITHUB = os.getenv("GITHUB_ACTIONS") == "true"\nDAILY_UPLOAD_LIMIT = 100\nDAILY_SEARCH_LIMIT = 100\n# Rough GitHub Actions build times, used only for the --check estimate (measured on October 2026 runs)\nGITHUB_SETUP_MINUTES = 2\nMINUTES_PER_SHORT = 3\nMINUTES_PER_LONG = 12\nGITHUB_FREE_MINUTES = 2000\n\nVOICE_CHOICES = {\n    "English": ["en-US-AvaMultilingualNeural", "en-US-EmmaMultilingualNeural", "en-US-BrianMultilingualNeural",\n                "en-US-AndrewMultilingualNeural", "en-US-AndrewNeural", "en-US-ChristopherNeural", "en-US-GuyNeural",\n                "en-US-AriaNeural", "en-US-EmmaNeural", "en-US-AnaNeural", "en-US-JennyNeural", "en-IN-PrabhatNeural",\n                "en-IN-NeerjaNeural"],\n    "Hindi": ["hi-IN-MadhurNeural", "hi-IN-SwaraNeural"],\n    "Telugu": ["te-IN-MohanNeural", "te-IN-ShrutiNeural"],\n}\n\n\n# ---------- prompt helpers (used by --ask and sign-in) ----------\n\ndef ask(question, default=None, validate=None):\n    while True:\n        suffix = f" [{default}]" if default not in (None, "") else ""\n        answer = input(f"{question}{suffix}: ").strip()\n        if not answer and default is not None:\n            answer = str(default)\n        if not answer:\n            print("   Please enter a value.")\n            continue\n        if validate:\n            error = validate(answer)\n            if error:\n                print(f"   {error}")\n                continue\n        return answer\n\n\ndef ask_yes_no(question, default=True):\n    hint = "Y/n" if default else "y/N"\n    while True:\n        answer = input(f"{question} ({hint}): ").strip().lower()\n        if not answer:\n            return default\n        if answer in ("y", "yes"):\n            return True\n        if answer in ("n", "no"):\n            return False\n        print("   Please answer y or n.")\n\n\ndef ask_choice(question, options, default_value=None):\n    print(question)\n    default_index = 1\n    for index, (value, label) in enumerate(options, 1):\n        marker = ""\n        if value == default_value:\n            default_index, marker = index, "  <- current"\n        print(f"   {index:>2}. {label}{marker}")\n\n    def validate(answer):\n        if not answer.isdigit() or not 1 <= int(answer) <= len(options):\n            return f"Enter a number from 1 to {len(options)}."\n        return None\n\n    return options[int(ask("   Choose a number", default_index, validate)) - 1][0]\n\n\ndef ask_int(question, default, low, high):\n    def validate(answer):\n        if not answer.isdigit() or not low <= int(answer) <= high:\n            return f"Enter a whole number from {low} to {high}."\n        return None\n    return int(ask(question, default, validate))\n\n\ndef validate_hhmm(answer):\n    if not re.fullmatch(r"\\d{1,2}:\\d{2}", answer):\n        return "Use 24-hour HH:MM, e.g. 07:00."\n    try:\n        parse_time(answer)\n    except ValueError:\n        return "That is not a real time of day."\n    return None\n\n\ndef split_list(text):\n    return [part.strip() for part in text.split(",") if part.strip()]\n\n\ndef heading(title):\n    print("\\n" + "=" * 60)\n    print(f" {title}")\n    print("=" * 60)\n\n\n# ---------- posting plan ----------\n\ndef apply_overrides(profile, overrides):\n    """Apply one-off command-line or --ask answers on top of questions.yaml (the file itself is not changed)."""\n    if overrides.get("genre"):\n        profile["niche"] = overrides["genre"]\n        profile["search_queries"] = overrides.get("queries") or [f"{overrides[\'genre\']} #shorts"]\n    elif overrides.get("queries"):\n        profile["search_queries"] = overrides["queries"]\n    for key, field in (("videos", "max_videos_per_run"), ("language", "language"), ("voice", "voice"),\n                       ("voice_rate", "voice_rate"), ("privacy", "privacy_status")):\n        if overrides.get(key):\n            profile[field] = overrides[key]\n    if overrides.get("frequency"):\n        profile["posting"]["frequency_minutes"] = FREQUENCIES[overrides["frequency"]]\n    if overrides.get("first_post") or overrides.get("frequency"):\n        # A one-off first time or gap replaces the fixed short_post_times\n        profile["posting"]["post_times"] = []\n    if overrides.get("first_post"):\n        profile["posting"]["first_post_time"] = overrides["first_post"]\n    if overrides.get("videos") and profile["long"]["count"]:\n        # --videos N means at most N of each format\n        profile["long"]["count"] = min(profile["long"]["count"], overrides["videos"])\n    if overrides.get("post_now"):\n        profile["posting"]["first_post_time"] = None\n        profile["posting"]["post_times"] = []\n        profile["long"]["post_times"] = []\n\n\ndef next_occurrences(times, tz, now, count):\n    """The next `count` go-live times (UTC) from a list of daily "HH:MM", at least 30 minutes from now."""\n    earliest = now.astimezone(tz) + timedelta(minutes=30)\n    upcoming = []\n    for days in range(0, count // max(len(times), 1) + 2):\n        for t in times:\n            local = datetime.combine(earliest.date() + timedelta(days=days), parse_time(t), tzinfo=tz)\n            if local >= earliest:\n                upcoming.append(local)\n    return [t.astimezone(timezone.utc) for t in sorted(upcoming)[:count]]\n\n\ndef publish_plan(profile, now=None):\n    """Turn first_post_time and post_frequency into the plan Agent 5 uses to schedule go-live times."""\n    tz = ZoneInfo(profile["schedule"]["timezone"])\n    if profile["posting"].get("post_times"):\n        upcoming = next_occurrences(profile["posting"]["post_times"], tz, now or datetime.now(tz),\n                                    profile["max_videos_per_run"])\n        return {"times_utc": [t.isoformat() for t in upcoming]}\n    first_post = profile["posting"]["first_post_time"]\n    if not first_post:\n        return None\n    today = (now or datetime.now(tz)).astimezone(tz).date()\n    first_local = datetime.combine(today, parse_time(first_post), tzinfo=tz)\n\n    fetch_times = profile["schedule"]["post_times"]\n    if fetch_times and parse_time(first_post) <= parse_time(fetch_times[0]):\n        # e.g. fetch at 23:00 and first post at 07:00 means 07:00 the next morning\n        first_local += timedelta(days=1)\n\n    return {\n        "first_utc": first_local.astimezone(timezone.utc).isoformat(),\n        "interval_minutes": profile["posting"]["frequency_minutes"],\n    }\n\n\ndef long_publish_plan(profile, now=None):\n    """One fixed go-live time per long video (long_post_times); times already past move to the next day."""\n    long = profile["long"]\n    if not long["count"] or not long["post_times"]:\n        return None\n    tz = ZoneInfo(profile["schedule"]["timezone"])\n    now_local = (now or datetime.now(tz)).astimezone(tz)\n    times = []\n    for post_time in long["post_times"][:long["count"]]:\n        local = datetime.combine(now_local.date(), parse_time(post_time), tzinfo=tz)\n        if local <= now_local:\n            local += timedelta(days=1)\n        times.append(local.astimezone(timezone.utc))\n    return {"times_utc": [t.isoformat() for t in sorted(times)]}\n\n\ndef day_slots(profile, day):\n    """Go-live times (local) of one posting day that starts on `day`: (Shorts, long videos).\n\n    A time at or before the day\'s first fetch time belongs to the next morning (e.g. fetch 23:00, post 07:00).\n    """\n    tz = ZoneInfo(profile["schedule"]["timezone"])\n    fetches = sorted(parse_time(t) for t in profile["schedule"]["post_times"])\n\n    def at(value):\n        local = datetime.combine(day, parse_time(value), tzinfo=tz)\n        return local + timedelta(days=1) if fetches and parse_time(value) <= fetches[0] else local\n\n    shorts = []\n    if profile["posting"].get("post_times"):\n        shorts = [at(t) for t in profile["posting"]["post_times"]]\n    elif profile["posting"]["first_post_time"]:\n        first, gap = at(profile["posting"]["first_post_time"]), timedelta(minutes=profile["posting"]["frequency_minutes"])\n        shorts = [first + gap * k for k in range(profile["max_videos_per_run"])]\n    longs = [at(t) for t in profile["long"]["post_times"][:profile["long"]["count"]]]\n    return shorts, longs\n\n\ndef run_window(profile, now=None, fetch=None):\n    """(start, end) local times of this run: from its fetch time up to the channel\'s next fetch time.\n\n    fetch is the fetch time behind a scheduled run, which GitHub may start hours early or late\n    (github_schedule_lead_minutes), so its nearest occurrence is used; manual runs use the window that contains\n    the current time.\n    """\n    tz = ZoneInfo(profile["schedule"]["timezone"])\n    now_local = (now or datetime.now(tz)).astimezone(tz)\n    times = sorted(parse_time(t) for t in profile["schedule"]["post_times"])\n    if not times:\n        return None\n\n    def latest(t):\n        local = datetime.combine(now_local.date(), t, tzinfo=tz)\n        return local - timedelta(days=1) if local > now_local else local\n\n    if fetch in times:\n        start = min((datetime.combine(now_local.date() + timedelta(days=d), fetch, tzinfo=tz) for d in (-1, 0, 1)),\n                    key=lambda local: abs(local - now_local))\n    else:\n        start = max(latest(t) for t in times)\n\n    def following(t):\n        local = datetime.combine(start.date(), t, tzinfo=tz)\n        return local + timedelta(days=1) if local <= start else local\n\n    return start, min(following(t) for t in times)\n\n\ndef run_slots(profile, now=None, fetch=None):\n    """This run\'s go-live times in UTC, (Shorts, long videos): the day\'s slots that fall inside its window."""\n    window = run_window(profile, now, fetch)\n    if not window:\n        return None\n    start, end = window\n    shorts, longs = set(), set()\n    for offset in (-1, 0, 1):\n        day_shorts, day_longs = day_slots(profile, start.date() + timedelta(days=offset))\n        shorts.update(t for t in day_shorts if start <= t < end)\n        longs.update(t for t in day_longs if start <= t < end)\n    return ([t.astimezone(timezone.utc) for t in sorted(shorts)],\n            [t.astimezone(timezone.utc) for t in sorted(longs)])\n\n\ndef plan_run(profile, fetch=None, shared=True, now=None):\n    """Set this run\'s video counts and go-live plans on the profile.\n\n    shared: the day\'s videos are shared between the channel\'s runs (one per fetch time), each run making the\n    videos whose go-live times fall before the next run. Off for one-off runs that set their own counts or times.\n    """\n    profile["publish_plan"] = publish_plan(profile, now)\n    profile["long_publish_plan"] = long_publish_plan(profile, now)\n    slots = run_slots(profile, now, fetch) if shared else None\n    if not slots:\n        return\n    shorts, longs = slots\n    if profile["posting"].get("post_times") or profile["posting"]["first_post_time"]:\n        profile["max_videos_per_run"] = len(shorts)\n        profile["publish_plan"] = {"times_utc": [t.isoformat() for t in shorts]}\n    if profile["long"]["post_times"]:\n        profile["long"]["count"] = len(longs)\n        profile["long_publish_plan"] = {"times_utc": [t.isoformat() for t in longs]} if longs else None\n\n\ndef plan_times(plan, tz):\n    if not plan or "times_utc" not in plan:\n        return []\n    return [datetime.fromisoformat(t).astimezone(ZoneInfo(tz)).strftime("%H:%M") for t in plan["times_utc"]]\n\n\ndef describe_run(profile, formats=("long", "short")):\n    """e.g. \'1 long (12:00) + 2 Shorts (08:00, 11:00)\' for the plan set by plan_run."""\n    tz = profile["schedule"]["timezone"]\n    parts = []\n    if "long" in formats and profile["long"]["count"]:\n        times = plan_times(profile.get("long_publish_plan"), tz)\n        parts.append(f"{profile[\'long\'][\'count\']} long" + (f" ({\', \'.join(times)})" if times else ""))\n    if "short" in formats and profile["max_videos_per_run"]:\n        times = plan_times(profile.get("publish_plan"), tz)\n        count = profile["max_videos_per_run"]\n        parts.append(f"{count} Short{\'s\' if count > 1 else \'\'}"\n                     + (f" ({\', \'.join(times)})" if times else " (live on upload)"))\n    return " + ".join(parts) or "no videos"\n\n\ndef describe_runs(profile):\n    """Each daily run and the videos it makes, e.g. \'06:00 -> 1 long (12:00) + 2 Shorts (08:00, 11:00)\'."""\n    tz = ZoneInfo(profile["schedule"]["timezone"])\n    lines = []\n    for fetch in sorted(parse_time(t) for t in profile["schedule"]["post_times"]):\n        preview = copy.deepcopy(profile)\n        at_fetch = datetime.combine(datetime.now(tz).date(), fetch, tzinfo=tz)\n        plan_run(preview, fetch=fetch, now=at_fetch)\n        lines.append(f"{fetch:%H:%M} -> {describe_run(preview)}")\n    return lines\n\n\ndef run_label(fetch):\n    if fetch is None:\n        return "Manual run"\n    return "Morning run" if fetch.hour < 12 else "Afternoon run" if fetch.hour < 17 else "Evening run"\n\n\ndef describe_long(profile):\n    long = profile["long"]\n    if not long["count"]:\n        return "no long videos"\n    minutes = str(long["minutes"]).replace("-", " to ")\n    return (f"{long[\'count\']} long landscape video(s) of {minutes} min, live at "\n            f"{\', \'.join(f\'{parse_time(t):%H:%M}\' for t in long[\'post_times\'][:long[\'count\']])}")\n\n\ndef describe_plan(profile):\n    posting = profile["posting"]\n    count = profile["max_videos_per_run"]\n    fetch = ", ".join(f"{parse_time(t):%H:%M}" for t in profile["schedule"]["post_times"]) or "manual runs only"\n    if posting.get("post_times"):\n        return f"fetch {fetch} | {count} video(s) live at " + ", ".join(\n            f"{parse_time(t):%H:%M}" for t in posting["post_times"])\n    if not posting["first_post_time"]:\n        return f"fetch {fetch} | {count} video(s), live immediately after upload"\n    freq = next((name for name, minutes in FREQUENCIES.items() if minutes == posting["frequency_minutes"]),\n                f"{posting[\'frequency_minutes\']} mins")\n    first = datetime.combine(datetime(2000, 1, 1), parse_time(posting["first_post_time"]))\n    last = first + timedelta(minutes=posting["frequency_minutes"] * (count - 1))\n    return (f"fetch {fetch} | {count} video(s): first live {first:%H:%M}, every {freq}, "\n            f"last {last:%H:%M}{\' (next day)\' if last.date() > first.date() else \'\'}")\n\n\n# ---------- running ----------\n\ndef token_path(config, key):\n    return os.path.normpath(os.path.join(PROJECT_DIR, config["storage_paths"]["tokens_dir"], f"token_{key}.json"))\n\n\ndef preflight(config, keys, dry_runs):\n    """Return the channels that are ready to run, explaining why any are skipped."""\n    problems = []\n    if not os.path.exists(os.path.join(PROJECT_DIR, ".env")) and not RUNNING_ON_GITHUB:\n        problems.append("No .env file. Copy .env.example to .env and fill in your API keys.")\n    for name in ("YOUTUBE_API_KEY", "GEMINI_API_KEY"):\n        if not os.getenv(name):\n            problems.append(f"{name} is not set (add it to .env, or as a GitHub secret).")\n    footage = config.get("footage") or {}\n    if footage.get("source", "stock") == "stock":\n        from agents.stock_footage import choose_provider\n        if not choose_provider(footage.get("provider", "auto"))[0]:\n            problems.append("No stock footage key is set. Add PIXABAY_API_KEY (free at https://pixabay.com/api/docs/) "\n                            "to .env, or as a GitHub secret.")\n    if problems:\n        print("\\nCannot start:\\n  - " + "\\n  - ".join(problems))\n        return []\n\n    ready = []\n    for key in keys:\n        if dry_runs[key] or os.path.exists(token_path(config, key)):\n            ready.append(key)\n        elif RUNNING_ON_GITHUB or not sys.stdin.isatty():\n            print(f"\\n[Skip] {key}: no YouTube login file. Run \'python execution/execution.py --authorize {key}\' "\n                  "on your laptop and upload the token file to Google Drive: YouTube_Automation/00_tokens/")\n        else:\n            print(f"\\n{key} has no YouTube login yet ({token_path(config, key)}).")\n            if ask_yes_no("Sign in to YouTube for this channel now?", True) and authorize(config, key):\n                ready.append(key)\n    return ready\n\n\ndef notify_start(config, keys, fetches, formats):\n    """Telegram message at the start of a run: which videos each channel is preparing and when they go live."""\n    from agents.agent_7_notifier import send_telegram\n    first = config["profiles"][keys[0]]\n    tz = ZoneInfo(first["schedule"]["timezone"])\n    now = datetime.now(tz)\n    fetch = fetches.get(keys[0])\n    started = f"started {now:%H:%M} {now:%Z}"\n    if fetch:\n        planned_at = min((datetime.combine(now.date() + timedelta(days=d), fetch, tzinfo=tz) for d in (-1, 0, 1)),\n                         key=lambda local: abs(local - now))\n        late = int((now - planned_at).total_seconds() // 60)\n        off = f"{abs(late) // 60}h {abs(late) % 60:02d}m {\'late\' if late > 0 else \'early\'}"\n        started = f"planned {fetch:%H:%M}, {started}" + (f" ({off})" if abs(late) >= 15 else "")\n    lines = [f"🎬 <b>{run_label(fetch)} started</b> ({started})", "Video preparation in progress:"]\n    for key in keys:\n        p = config["profiles"][key]\n        lines.append(f"• <b>{html.escape(p[\'channel_name\'])}</b>: {describe_run(p, formats)}")\n    lines.append("A message per channel follows once its videos are uploaded and scheduled.")\n    send_telegram("\\n".join(lines))\n\n\ndef run_channels(config, instructions, keys, overrides=None, force_dry_run=False, formats=("long", "short"),\n                 cron=None):\n    from dotenv import load_dotenv\n    from agents import ai\n    load_dotenv(os.path.join(PROJECT_DIR, ".env"))\n    ai.configure(config)\n    print(f"Backup AI when Gemini is out of quota: {ai.backup_status()}")\n\n    config = copy.deepcopy(config)\n    for key in keys:\n        apply_overrides(config["profiles"][key], overrides or {})\n    dry_runs = {key: force_dry_run or config["profiles"][key]["test_run"] for key in keys}\n\n    ready = preflight(config, keys, dry_runs)\n    if not ready:\n        return 1\n\n    from orchestrator import OrchestratorAgent\n    orchestrator = OrchestratorAgent(config, instructions)\n    failed, results = [], {}\n    # One-off counts or times replace the shared daily plan for this run\n    shared = not any((overrides or {}).get(k) for k in ("videos", "first_post", "frequency", "post_now"))\n    fetches, planned = {}, {}\n    for key in ready:\n        profile = config["profiles"][key]\n        fetches[key] = fetch_time_for_cron(profile, cron) if cron else None\n        plan_run(profile, fetch=fetches[key], shared=shared)\n        planned[key] = (profile["max_videos_per_run"] if "short" in formats else 0) + \\\n                       (profile["long"]["count"] if "long" in formats else 0)\n    if not all(dry_runs[key] for key in ready):\n        notify_start(config, ready, fetches, formats)\n\n    for key in ready:\n        profile = config["profiles"][key]\n        print(f"\\n>>> {key}: {describe_run(profile, formats)}")\n        if not planned[key]:\n            print(f"[Orchestrator] {key}: no go-live times fall in this run; nothing to make.")\n            continue\n        try:\n            results[key] = orchestrator.execute_pipeline(key, dry_run=dry_runs[key], formats=formats,\n                                                         planned=planned[key])\n            if not dry_runs[key] and results[key] == 0:\n                failed.append(key)\n        except Exception as e:\n            print(f"\\n[Error] {key} failed: {e}")\n            failed.append(key)\n            if not dry_runs[key]:\n                from agents.agent_7_notifier import send_telegram\n                send_telegram(f"❌ <b>{html.escape(profile[\'channel_name\'])}</b>: the run stopped with an error "\n                              f"before uploading.\\n<code>{html.escape(str(e)[:300])}</code>")\n\n    live = [key for key in ready if not dry_runs[key]]\n    if live:\n        # Record how earlier uploads are doing; it decides which search phrases the Scout tries first\n        from agents.agent_8_analyst import AnalystAgent\n        AnalystAgent(config).run(live)\n\n    heading("RESULT")\n    for key in keys:\n        if key not in ready:\n            print(f" {key}: skipped (no YouTube login)")\n        elif dry_runs[key]:\n            print(f" {key}: test run, videos made but not uploaded")\n        else:\n            print(f" {key}: {results.get(key, 0)} of {planned[key]} video(s) uploaded")\n            if RUNNING_ON_GITHUB and 0 < results.get(key, 0) < planned[key]:\n                # Some but not all: the run stays green, with a yellow warning on its summary page\n                print(f"::warning title={key}: {results[key]} of {planned[key]} uploaded::"\n                      f"{planned[key] - results[key]} video(s) were not made or uploaded. Search step 8 for "\n                      "\'[Agent\' lines to see why; they are retried in later runs.")\n    if failed or len(ready) < len(keys):\n        print("\\nSome channels uploaded nothing. Scroll up for the [Agent ...] lines explaining why.")\n        return 1\n    return 0\n\n\n# ---------- schedule, check, login and list ----------\n\ndef read_workflow_schedule():\n    if not os.path.exists(WORKFLOW_FILE):\n        return None, None\n    with open(WORKFLOW_FILE, "r", encoding="utf-8") as f:\n        lines = f.read().split("\\n")\n    begin = next((i for i, line in enumerate(lines) if SCHEDULE_BEGIN in line), None)\n    end = next((i for i, line in enumerate(lines) if SCHEDULE_END in line), None)\n    if begin is None or end is None or end < begin:\n        return lines, None\n    return lines, (begin, end)\n\n\ndef schedule_in_sync(config):\n    lines, markers = read_workflow_schedule()\n    if not markers:\n        return True\n    current = [re.sub(r".*cron:\\s*\'([^\']*)\'.*", r"\\1", line) for line in lines[markers[0] + 1:markers[1]]]\n    return current == cron_lines(config)\n\n\ndef sync_schedule(config):\n    crons = cron_lines(config)\n    lines, markers = read_workflow_schedule()\n    if lines is None or markers is None:\n        print("Could not find the schedule section in the GitHub workflow. Add these lines under \'schedule:\':")\n        print("\\n".join(f"    - cron: \'{c}\'" for c in crons))\n        return False\n    if not crons:\n        print("No channel has a fetch_time, so the GitHub schedule was left unchanged.")\n        return False\n\n    begin, end = markers\n    indent = lines[begin][:len(lines[begin]) - len(lines[begin].lstrip())]\n    lines[begin + 1:end] = [f"{indent}- cron: \'{c}\'" for c in crons]\n    with open(WORKFLOW_FILE, "w", encoding="utf-8", newline="") as f:\n        f.write("\\n".join(lines))\n\n    print("GitHub schedule updated (times shown in UTC):")\n    for c in crons:\n        print(f"   {c}")\n    print("Push to GitHub so the new schedule takes effect.")\n    return True\n\n\ndef list_channels(config):\n    heading("CHANNELS AND POSTING PLANS")\n    for key, p in config["profiles"].items():\n        if not p["has_answers"]:\n            state = "NOT ANSWERED in questions.yaml (will not run)"\n        else:\n            state = "will run" if p["enabled"] else "run: false (paused)"\n        login = "yes" if os.path.exists(token_path(config, key)) else "NO"\n        days = p["schedule"]["days"] if isinstance(p["schedule"]["days"], str) else ",".join(p["schedule"]["days"])\n        print(f" {key}  -  {p[\'channel_name\']}")\n        print(f"    {state} | YouTube login: {login} | {\'TEST RUN\' if p[\'test_run\'] else \'uploads\'}")\n        if p["has_answers"]:\n            print(f"    Shorts: {describe_plan(p)} ({days}, {p[\'schedule\'][\'timezone\']})")\n            print(f"    Long:   {describe_long(p)}")\n            if len(p["schedule"]["post_times"]) > 1:\n                for line in describe_runs(p):\n                    print(f"    Run {line}")\n            print(f"    genre: {p[\'niche\']} | {p[\'language\']} | voice: {p[\'voice\']} {p[\'voice_rate\']}")\n\n\ndef usage_report(config):\n    """Estimate the YouTube API calls the answers use per day, against YouTube\'s daily limits."""\n    # Channels due at the same time share one GitHub run, so setup time is counted once per scheduled time.\n    # videos_per_day and long_videos_per_day are day totals, shared between a channel\'s runs\n    uploads = searches = 0\n    github_minutes = len(cron_lines(config)) * GITHUB_SETUP_MINUTES\n    for p in config["profiles"].values():\n        if not p["enabled"]:\n            continue\n        runs_per_day = len(p["schedule"]["post_times"]) or 1\n        long_count = p["long"]["count"]\n        github_minutes += p["max_videos_per_run"] * MINUTES_PER_SHORT + long_count * MINUTES_PER_LONG\n        if p["test_run"]:\n            continue\n        uploads += p["max_videos_per_run"] + long_count\n        # The Scout searches phrases only until it has enough topics: about one search per video, at most every\n        # phrase in each run\n        phrases = len(p["search_queries"])\n        searches += min(p["max_videos_per_run"], phrases * runs_per_day) + min(long_count, phrases * runs_per_day)\n    print(f"\\nDaily YouTube usage (all channels): {uploads} of {DAILY_UPLOAD_LIMIT} uploads, "\n          f"up to {searches} of {DAILY_SEARCH_LIMIT} searches.")\n    if uploads > DAILY_UPLOAD_LIMIT or searches > DAILY_SEARCH_LIMIT:\n        print("WARNING: over YouTube\'s daily limit. Lower videos_per_day or search_phrases, "\n              "or request more quota in Google Cloud Console.")\n    monthly = github_minutes * 30\n    if config.get("github_repo_public"):\n        print(f"Estimated GitHub Actions time: about {github_minutes} min a day (public repository: unlimited).")\n        return\n    print(f"Estimated GitHub Actions time: about {github_minutes} min a day, {monthly} min a month "\n          f"(private repos get {GITHUB_FREE_MINUTES} free minutes a month; public repos are unlimited).")\n    if monthly > GITHUB_FREE_MINUTES:\n        print("WARNING: likely over GitHub\'s free minutes for a private repo. Make the repo public, lower the "\n              "video counts, or GitHub will stop the runs (or bill you, if a payment method is set) for the rest "\n              "of the month.")\n\n\ndef plan_warnings(config):\n    warnings = []\n    for key, p in config["profiles"].items():\n        if not p["enabled"]:\n            continue\n        fetch, first = p["schedule"]["post_times"], p["posting"]["first_post_time"]\n        if fetch and first:\n            gap = (datetime.combine(datetime(2000, 1, 1), parse_time(first))\n                   - datetime.combine(datetime(2000, 1, 1), parse_time(fetch[0]))).total_seconds() / 60 % 1440\n            if gap < 30:\n                warnings.append(f"{key}: first_post_time is only {int(gap)} min after fetch_time; allow 30+ min "\n                                "to prepare videos (later slots are used automatically if it runs late).")\n        span = p["posting"]["frequency_minutes"] * (p["max_videos_per_run"] - 1)\n        if first and not p["posting"].get("post_times") and span >= 1440:\n            warnings.append(f"{key}: {p[\'max_videos_per_run\']} videos every {p[\'posting\'][\'frequency_minutes\']} min "\n                            "runs past 24 hours and overlaps the next day\'s videos.")\n        # Each run needs time to prepare its videos before the first one goes live\n        tz = ZoneInfo(p["schedule"]["timezone"])\n        for run_time in sorted(parse_time(t) for t in fetch):\n            preview = copy.deepcopy(p)\n            at_fetch = datetime.combine(datetime.now(tz).date(), run_time, tzinfo=tz)\n            plan_run(preview, fetch=run_time, now=at_fetch)\n            times = [datetime.fromisoformat(t) for plan in (preview.get("publish_plan"), preview.get("long_publish_plan"))\n                     for t in (plan or {}).get("times_utc", [])]\n            if times and (min(times) - at_fetch).total_seconds() < 45 * 60:\n                warnings.append(f"{key}: the {run_time:%H:%M} run\'s first video goes live under 45 min after the run "\n                                "starts; it will go live a little later than planned.")\n    return warnings\n\n\ndef check(config):\n    list_channels(config)\n    print("\\nBoth pages are valid.")\n    for warning in plan_warnings(config):\n        print(f"Note: {warning}")\n    usage_report(config)\n    if schedule_in_sync(config):\n        print("GitHub schedule already matches questions.yaml.")\n    else:\n        sync_schedule(config)\n\n\ndef authorize(config, key):\n    client_secret = os.path.join(PROJECT_DIR, "client_secret.json")\n    if key not in config["profiles"]:\n        print(f"\'{key}\' is not on the channel page.")\n        return False\n    if not os.path.exists(client_secret):\n        print(f"client_secret.json not found at {client_secret}. See execution.md, \'One-Time Setup\'.")\n        return False\n    from google_auth_oauthlib.flow import InstalledAppFlow\n    from googleapiclient.discovery import build\n\n    profile = config["profiles"][key]\n    target = token_path(config, key)\n    os.makedirs(os.path.dirname(target), exist_ok=True)\n    print(f"\\nA browser window will open. Sign in with the Google account that owns \'{profile[\'channel_name\']}\'")\n    print(f"and choose that channel ({profile[\'channel_url\']}).")\n    creds = InstalledAppFlow.from_client_secrets_file(client_secret, YOUTUBE_SCOPES).run_local_server(port=0)\n\n    items = build("youtube", "v3", credentials=creds).channels().list(part="snippet", mine=True).execute().get("items", [])\n    if not items:\n        print("That Google account has no YouTube channel. Nothing was saved; try again.")\n        return False\n    channel_id, snippet = items[0]["id"], items[0]["snippet"]\n    if not channel_matches(profile["channel_url"], channel_id, snippet.get("customUrl")):\n        print(f"You signed in to \'{snippet[\'title\']}\' ({snippet.get(\'customUrl\') or channel_id}), "\n              f"but \'{key}\' is {profile[\'channel_url\']}. Nothing was saved; try again and pick the right channel.")\n        return False\n    print(f"Confirmed channel: {snippet[\'title\']}")\n\n    with open(target, "w", encoding="utf-8") as f:\n        f.write(creds.to_json())\n    print(f"Saved YouTube login to: {target}")\n    print("For GitHub runs, upload this file to Google Drive: YouTube_Automation/00_tokens/")\n    return True\n\n\ndef import_hero_art(config, folder):\n    from agents import mascot\n    if not os.path.isdir(folder):\n        print(f"No folder at {folder}")\n        return 2\n    import shutil\n    imported = mascot.import_art(folder)\n    # The owner\'s own intro / outro videos are copied as they are (GitHub refuses files over 100 MB)\n    for name in ("intro.mp4", "outro.mp4", "intro_short.mp4", "outro_short.mp4"):\n        source = os.path.join(folder, name)\n        if os.path.exists(source):\n            megabytes = os.path.getsize(source) / 1e6\n            if megabytes > 50:\n                print(f"Skipped {name}: {megabytes:.0f} MB is too big; export it under 20 MB.")\n                continue\n            # A "WS" badge covers the image AI\'s logo in the corner\n            from agents.agent_4_editor import load_font\n            mascot.cover_corner_logo(source, os.path.join(mascot.ART_DIR, name), load_font, mascot.ART_DIR)\n            imported.append(name)\n    if not imported:\n        print("Nothing to import. Pictures are named after poses (" + ", ".join(mascot.ART_NAMES) +\n              ", each also as <name>_open); videos are intro.mp4 and outro.mp4. See assets/wondersprout/PROMPTS.md.")\n        return 1\n    print(f"Imported {len(imported)} pose(s) into {mascot.ART_DIR}: {\', \'.join(imported)}")\n    root = (config.get("local_media") or {}).get("root")\n    # The preview goes to the Google Drive video folder when it\'s available, else next to the art\n    preview_dir = mascot.ART_DIR\n    if root and os.path.isdir(os.path.dirname(root)):\n        preview_dir = os.path.join(root, "wondersprout_preview")\n    os.makedirs(preview_dir, exist_ok=True)\n    mascot.sheet(os.path.join(preview_dir, "WonderSprout_expressions.png"))\n    print(f"Preview of every expression: {os.path.join(preview_dir, \'WonderSprout_expressions.png\')}")\n    print("Commit and push assets/wondersprout so GitHub runs use the new art.")\n    return 0\n\n\ndef learn_from(config, link):\n    from dotenv import load_dotenv\n    from google import genai\n    from agents import ai\n    from agents.learner import learn\n    load_dotenv(os.path.join(PROJECT_DIR, ".env"))\n    ai.configure(config)\n    for name in ("YOUTUBE_API_KEY", "GEMINI_API_KEY"):\n        if not os.getenv(name):\n            print(f"{name} is not set (add it to .env).")\n            return 2\n    try:\n        found = learn(link, genai.Client(api_key=os.getenv("GEMINI_API_KEY")), config.get("ai_models"))\n    except Exception as e:\n        print(f"[Learn] Failed: {e}")\n        return 1\n    if found:\n        print("Review the entry at the end of execution/view_techniques.md: copy good rules into ACTIVE RULES and "\n              "change its status to reviewed.")\n    return 0\n\n\ndef inbox_from(config):\n    """--inbox: handle the links and requests posted in the Telegram channel (agents/inbox.py)."""\n    from dotenv import load_dotenv\n    from google import genai\n    from agents import ai, inbox\n    load_dotenv(os.path.join(PROJECT_DIR, ".env"))\n    ai.configure(config)\n    for name in ("YOUTUBE_API_KEY", "GEMINI_API_KEY", "TELEGRAM_BOT_TOKEN", "TELEGRAM_CHANNEL_ID"):\n        if not os.getenv(name):\n            print(f"{name} is not set (add it to .env).")\n            return 2\n    inbox.run(config, genai.Client(api_key=os.getenv("GEMINI_API_KEY")))\n    return 0\n\n\n# ---------- --ask: answer the questions interactively for one run ----------\n\ndef ask_mode(config, instructions):\n    answered = {k: p for k, p in config["profiles"].items() if p["has_answers"]}\n    if not answered:\n        print("No channel is answered in questions.yaml yet.")\n        return 1\n\n    heading("ONE-OFF RUN  (questions.yaml is not changed)")\n    print("Each answer starts at the value in questions.yaml. Press Enter to keep it. Ctrl+C cancels.\\n")\n    key = ask_choice("Q1. Which channel should the videos be posted to?",\n                     [(k, f"{p[\'channel_name\']} ({k})") for k, p in answered.items()])\n    p = answered[key]\n    o = {}\n\n    genre = ask("\\nQ3. Genre to source trending videos for", p["niche"])\n    if genre != p["niche"]:\n        o["genre"] = genre\n    default_queries = f"{genre} #shorts" if "genre" in o else ", ".join(p["search_queries"])\n    queries = split_list(ask("Q4. YouTube search phrases, comma-separated", default_queries))\n    if queries != p["search_queries"]:\n        o["queries"] = queries\n\n    o["language"] = ask_choice("\\nQ5. Narration language:", [(lang, lang) for lang in LANGUAGES], p["language"])\n    voices = VOICE_CHOICES[o["language"]]\n    current_voice = p["voice"] if p["voice"] in voices else DEFAULT_VOICES[(o["language"], p["made_for_kids"])]\n    o["voice"] = ask_choice("\\nQ6. Narrator voice:", [(v, v) for v in voices], current_voice)\n    o["voice_rate"] = ask_choice("\\nQ7. Speaking speed:", [\n        ("-15%", "-15%  slow and very clear"), ("-5%", "-5%   clear (recommended)"),\n        ("+0%", "+0%   natural"), ("+10%", "+10%  brisk")], p["voice_rate"] if p["voice_rate"] in SPEEDS else "-5%")\n\n    o["videos"] = ask_int("\\nQ15. How many videos?", p["max_videos_per_run"], 1, MAX_VIDEOS_PER_DAY)\n    when = ask_choice("\\nWhen should they go live?", [\n        ("schedule", "Spaced out: first video at a set time, then one every 15 mins / 30 mins / 1 hour / 3 hours"),\n        ("now", "All immediately after upload")], "schedule" if p["posting"]["first_post_time"] else "now")\n    if when == "schedule":\n        o["first_post"] = ask(f"Q13. First video goes live at (HH:MM, {p[\'schedule\'][\'timezone\']})",\n                              p["posting"]["first_post_time"] or "", validate_hhmm)\n        current_freq = next((n for n, m in FREQUENCIES.items() if m == p["posting"]["frequency_minutes"]), "1 hour")\n        o["frequency"] = ask_choice("\\nQ14. Gap between videos:", [(f, f) for f in FREQUENCIES], current_freq)\n    else:\n        o["post_now"] = True\n    o["privacy"] = ask_choice("\\nQ18. Visibility:", [(v, v) for v in ("public", "unlisted", "private")],\n                              p["privacy_status"])\n    dry_run = ask_yes_no("\\nQ19. Test run? (make the videos but do NOT upload)", p["test_run"])\n\n    heading("SUMMARY")\n    preview = copy.deepcopy(p)\n    apply_overrides(preview, o)\n    print(f" Channel:  {key} ({p[\'channel_name\']})")\n    print(f" Genre:    {preview[\'niche\']}")\n    print(f" Search:   {\', \'.join(preview[\'search_queries\'])}")\n    print(f" Voice:    {preview[\'voice\']} {preview[\'voice_rate\']} ({preview[\'language\']})")\n    print(f" Plan:     {describe_plan(preview).split(\'| \', 1)[-1]}")\n    print(f" Mode:     {\'TEST RUN (no upload)\' if dry_run else \'Upload to YouTube, \' + preview[\'privacy_status\']}")\n    if not ask_yes_no("\\nStart now?", True):\n        print("Cancelled.")\n        return 0\n    return run_channels(config, instructions, [key], o, force_dry_run=dry_run, formats=("short",))\n\n\n# ---------- command line ----------\n\ndef main():\n    parser = argparse.ArgumentParser(\n        description="Run the YouTube automation using the answers in execution/questions.yaml.",\n    )\n    parser.add_argument("--channel", help="Run one channel key, or \'all\' (default: every channel with run: true)")\n    parser.add_argument("--genre", help="One-off genre to source trending videos for")\n    parser.add_argument("--videos", help="One-off number of videos")\n    parser.add_argument("--frequency", help="One-off gap between videos: \'15 mins\', \'30 mins\', \'1 hour\' or \'3 hours\'")\n    parser.add_argument("--first-post", help="One-off time the first video goes live (HH:MM)")\n    parser.add_argument("--post-now", action="store_true", help="One-off: make every video live immediately")\n    parser.add_argument("--visibility", choices=["public", "unlisted", "private"], help="One-off visibility")\n    parser.add_argument("--dry-run", action="store_true", help="Make the videos but do not upload")\n    parser.add_argument("--format", choices=["both", "short", "long"], default="both",\n                        help="Which videos to make: Shorts, long videos, or both (default)")\n    parser.add_argument("--ask", action="store_true", help="Answer the questions interactively for a one-off run")\n    parser.add_argument("--scheduled", action="store_true", help="Run channels due for --cron (used by GitHub)")\n    parser.add_argument("--due", action="store_true", help="Only print channels due for --cron (used by GitHub)")\n    parser.add_argument("--cron", help="The cron expression that triggered a scheduled GitHub run")\n    parser.add_argument("--authorize", metavar="CHANNEL", help="Sign in to YouTube for a channel")\n    parser.add_argument("--hero-art", metavar="FOLDER",\n                        help="Import pictures of the WonderSprout character (see assets/wondersprout/PROMPTS.md)")\n    parser.add_argument("--learn", metavar="LINK",\n                        help="Analyse a YouTube video about getting views; adds its techniques to "\n                             "execution/view_techniques.md for review")\n    parser.add_argument("--inbox", action="store_true",\n                        help="Handle YouTube links and video requests posted in the Telegram channel")\n    parser.add_argument("--check", action="store_true", help="Validate pages, show plan and usage, update schedule")\n    parser.add_argument("--list", action="store_true", help="Show channels and their posting plans")\n    args = parser.parse_args()\n\n    try:\n        config, instructions = load_brain()\n    except (ValueError, FileNotFoundError) as e:\n        print(e)\n        return 2\n\n    if args.due or args.scheduled:\n        if not args.cron:\n            print("--cron is required with --due and --scheduled.")\n            return 2\n        keys = due_profiles(config, args.cron)\n        if args.due:\n            print(" ".join(keys))\n            return 0\n        if not keys:\n            print("No channels are due for this schedule.")\n            return 0\n        return run_channels(config, instructions, keys, force_dry_run=args.dry_run, cron=args.cron)\n\n    if args.check:\n        check(config)\n        return 0\n    if args.list:\n        list_channels(config)\n        return 0\n    if args.authorize:\n        return 0 if authorize(config, args.authorize) else 1\n    if args.learn:\n        return learn_from(config, args.learn)\n    if args.inbox:\n        return inbox_from(config)\n    if args.hero_art:\n        return import_hero_art(config, args.hero_art)\n    if args.ask:\n        return ask_mode(config, instructions)\n\n    # GitHub passes empty strings for form fields left blank, so treat "" as not given\n    overrides = {\n        "genre": args.genre or None,\n        "videos": int(args.videos) if args.videos else None,\n        "frequency": args.frequency or None,\n        "first_post": args.first_post or None,\n        "post_now": args.post_now,\n        "privacy": args.visibility,\n    }\n    if overrides["frequency"] and overrides["frequency"] not in FREQUENCIES:\n        print(f"--frequency must be one of: {\', \'.join(FREQUENCIES)}")\n        return 2\n    if overrides["first_post"] and validate_hhmm(overrides["first_post"]):\n        print(f"--first-post: {validate_hhmm(overrides[\'first_post\'])}")\n        return 2\n    if overrides["videos"] is not None and not 1 <= overrides["videos"] <= MAX_VIDEOS_PER_DAY:\n        print(f"--videos must be from 1 to {MAX_VIDEOS_PER_DAY}")\n        return 2\n\n    if args.channel and args.channel != "all":\n        if args.channel not in config["profiles"]:\n            print(f"\'{args.channel}\' is not on the channel page. Channels: {\', \'.join(config[\'profiles\'])}")\n            return 2\n        if not config["profiles"][args.channel]["has_answers"]:\n            print(f"\'{args.channel}\' has no answers in questions.yaml yet.")\n            return 2\n        keys = [args.channel]\n    else:\n        keys = [k for k, p in config["profiles"].items() if p["enabled"]]\n        if not keys:\n            print("No channel has run: true in questions.yaml.")\n            return 1\n    # Long videos first, so they are ready well before their go-live times\n    formats = ("long", "short") if args.format == "both" else (args.format,)\n    return run_channels(config, instructions, keys, overrides, force_dry_run=args.dry_run, formats=formats)\n\n\nif __name__ == "__main__":\n    try:\n        sys.exit(main())\n    except (KeyboardInterrupt, EOFError):\n        print("\\nCancelled.")\n        sys.exit(1)\n',
    'execution/execution.md': '# Execution Guide\n\nEverything you need to run the YouTube automation lives in this folder:\n\n| File | Purpose |\n|---|---|\n| `execution.py` | **The only file you run.** Works from GitHub, any IDE, a terminal, or Copilot. |\n| `execution.md` | This guide: setup, rules and how to run. |\n| `questions.yaml` | **The answers.** What and when each channel posts: genre, language, voice, how many videos, how often. Options are written beside each question. |\n| `channels.yaml` | **The channel page.** Who each channel is: name, made for kids, watermark, category. |\n\n`BRAIN.md` (one folder up) holds the global rules every channel shares: editing style, storage folders and AI writing instructions. You rarely need to touch it.\n\n---\n\n## Golden Rules\n\n1. **Create each YouTube channel yourself**, then list it in `channels.yaml` and answer its questions in `questions.yaml` under the **same key**.\n2. **`execution.py` always reads `questions.yaml`.** To change what a channel does, change the answers there, not the code.\n3. **Copy options exactly** from the comments: quotes, spaces and capital letters matter (`"1 hour"`, `"Telugu"`, `"-5%"`).\n4. **After any change to either file, run** `python execution/execution.py --check`, **then push to GitHub.** The check validates both files, shows each channel\'s posting plan and daily YouTube usage, and updates the GitHub schedule.\n5. **Every channel needs a YouTube login** (`token_<key>.json`) before it can upload. See *Adding a Channel*, step 4. Sign in with **the Google account that owns the channel**. This can be a different account from the one that owns the Google Cloud project; if the OAuth consent screen is still in Testing mode, add that account under **Test users**.\n6. **Test first:** set `test_run: true` for a new channel. It makes the videos without uploading them.\n7. **Stay within YouTube\'s daily limits:** 100 uploads and 100 searches per day, shared by all channels. `--check` shows your total.\n8. **Never commit secrets.** `.env`, `client_secret.json` and `token_*.json` are git-ignored.\n\n---\n\n## What Happens When the Job Runs\n\n```mermaid\nflowchart TD\n    A[GitHub schedule fires github_schedule_lead_minutes before fetch_time] --> B[Set up: Python, FFmpeg, rclone, keys]\n    B --> C[Pull YouTube logins and manifest from Google Drive]\n    C --> D[execution.py reads channels.yaml + questions.yaml + BRAIN.md]\n    D --> E[Mark lost half-finished videos expired]\n    E --> T[Telegram: run started, agent 7]\n    T --> F{Long videos first, then Shorts}\n    F --> G[Scout, agent 1: owner requests from Telegram first, then a rising same-language topic, best search phrases first, real search phrases]\n    G --> H[Script and voice, agent 3: Gemini or backup Groq writes script, search keyword, title, hashtags, then narration, timings, scenes]\n    H --> I[Footage, agent 2: one matching stock clip per scene]\n    I --> J[Editor, agent 4: FFmpeg montage, watermark, narration, kids music and sound effects, end card]\n    J --> K[Publisher, agent 5: channel check, title, chunked upload with go-live time]\n    K --> F\n    F -->|both formats done| L[Cleanup, agent 6]\n    L --> M[Telegram: one message per channel, agent 7]\n    M -->|all channels done| P[Analyst, agent 8: record views, score search phrases, daily report]\n    P --> N[Sync manifest and unpublished videos back to Google Drive]\n```\n\n### The GitHub job ([daily_youtube_agents.yml](../../.github/workflows/daily_youtube_agents.yml))\n\n| Step | What it does |\n|---|---|\n| 1. Checkout | Gets the latest code from `main` |\n| 2. Python 3.11 | Sets up Python |\n| 3. Decide which channels are due | Scheduled run: the channel(s) whose `fetch_time` matches. Manual run: the channel you typed. Nothing due means the job stops here at almost no cost. |\n| 4. Install FFmpeg & rclone | Video tools and the Google Drive connection |\n| 5. Install dependencies | Everything in `requirements.txt` |\n| 6. Restore API keys | Writes the GitHub secrets into `.env` and `client_secret.json` |\n| 7. Pull from Google Drive | YouTube logins (`00_tokens`), the manifest (`01_manifests`) and any finished-but-unpublished videos |\n| 8. Run the pipeline | `python execution/execution.py --scheduled --cron "<time>"` (or your manual options). See below. |\n| 9. Sync back to Google Drive | Saves the updated manifest, logins and any unpublished videos for the next run. Runs even if step 8 failed. |\n\n### The pipeline (step 8), for each due channel\n\n1. **Clear lost work:** unfinished videos whose files are gone are marked `expired`, because GitHub starts every run on a fresh machine.\n2. **Long videos, then Shorts.** Long videos go first so they are uploaded hours before their go-live times. For each format:\n\n| Agent | Does | Uses |\n|---|---|---|\n| **1. Scout** ([agent_1_scout.py](../agents/agent_1_scout.py)) | Finds trending YouTube videos on your `search_phrases` (Shorts for Shorts, 4 to 20 minute videos for long ones), in your `language`. It ranks them by **views per hour** (what is rising right now), skips sources in another language (other scripts, Hinglish, or a title naming another language), tries the search phrases whose videos got the most views first, and avoids recent or excluded source channels. Only the topic is used, never the video itself. It also collects the **search phrases people type** for each phrase (YouTube\'s autocomplete, free; other-language ones dropped) and the keyword tags of the fastest-rising videos. | YouTube Data API, YouTube autocomplete |\n| **3. Script & Voice** ([agent_3_voiceover.py](../agents/agent_3_voiceover.py)) | Gemini writes an original script, and in the same request the main search keyword (picked from the Scout\'s real search phrases; it leads the title and the first description sentence) and 6 related phrases, the upload title, description, hashtags and 5 footage terms for the whole topic (one request instead of three). Hook first; long videos get 3 to 5 parts, a recap and a comment question. Narrated with your `voice` and `voice_speed`, **sentence by sentence with its own pitch, speed and volume** (`voice_expression`: the hook lifts, questions rise, exclamations pop, plain sentences vary, the ending slows), recording when each sentence is spoken. If the narration is longer than allowed, it\'s shortened and narrated again. Then it\'s split into scenes: about 6 per Short, one about every 8 seconds in long videos. | Gemini (or Groq), edge-tts |\n| **2. Footage** ([agent_2_downloader.py](../agents/agent_2_downloader.py)) | Each scene gets a specific search term (news channels name the person, country, ship or event) plus a generic backup. With `footage_style: "real"` (Frontline) the specific term is first looked up as **real footage of the actual people and events** on Wikimedia Commons; otherwise one clip per scene comes from Pixabay (cartoon or real-life per `footage_style`), and only clips whose tags match the scene\'s **subject** are used (style words like "cartoon", "funny" or "cute" don\'t count, so a random cartoon can\'t stand in for a turtle). On kids channels, when no video shows the subject, a matching Pixabay **cartoon illustration** is used instead, with a slow zoom, before falling back to the generic backup term. The log prints a **sync report**: each scene\'s time range, the footage shown and the words spoken. | Wikimedia Commons, Pixabay |\n| **4. Editor** ([agent_4_editor.py](../agents/agent_4_editor.py)) | On WonderSprout, adds the superhero host (intro, corner host with expressions, outro; see below). FFmpeg cuts every clip to its scene\'s narration time and fits it to 1080×1920 (Short) or 1920×1080 (long); in Shorts, real footage is shown whole on a blurred copy of itself so the people in it aren\'t cropped out. Mixes ducked BGM and cue-triggered cartoon SFX on kids channels. Mastered to broadcast loudness (-20 dB mean across all segments, with hero clips attenuated at 0.28). Overlays the watermark and appends the LIKE → SUBSCRIBE end card. | FFmpeg |\n| **5. Publisher** ([agent_5_publisher.py](../agents/agent_5_publisher.py)) | Confirms the YouTube login is the channel in `channels.yaml`. Uses the title, description and hashtags written with the script, hidden search tags led by the keyword and the real search phrases that fit the video, plus a credits section only for real Wikimedia Commons footage (Frontline); no Pixabay or music credits. If they\'re missing it asks Gemini, and if Gemini is unavailable (quota used up) it uses the source video\'s title so the finished video still goes out. Uploads in 8 MB resumable chunks, scheduled to go live at its slot. | YouTube Data API |\n\n3. **6. Cleanup** ([agent_6_cleanup.py](../agents/agent_6_cleanup.py)): on GitHub, deletes clips, narration and published videos. On a laptop, deletes `YouTube_Auto` day folders older than `keep_days`.\n4. **7. Telegram** ([agent_7_notifier.py](../agents/agent_7_notifier.py)): when a run starts, one message says it\'s preparing videos (and how late GitHub started it). After each channel finishes, one message per channel lists every uploaded video with its title, link and go-live time, and says if any were not uploaded.\n5. **8. Analyst** ([agent_8_analyst.py](../agents/agent_8_analyst.py)): reads the views, likes and comments of every video uploaded in the last 14 days and saves them in the manifest. A video\'s views after 48 hours score the search phrase that found its topic; the Scout uses the best phrases first and re-tries any phrase unused for 3 days. Once a day it posts a Telegram report: videos and views per channel over 7 days, the best video, and the best and weakest topic.\n6. **RESULT:** the log ends with how many videos each channel uploaded. If a channel uploaded nothing, the job is marked failed; if it uploaded some but not all, the run stays green with a yellow warning.\n\n**Gemini usage:** 1 request per Short (script, title, hashtags and each scene\'s footage terms together) and 2 per long video (script, then per-scene footage terms for its ~20 scenes): about 20 a day for both channels. The free tier allows 20 requests a day **per model**, reset at 12:30 IST, so the 4 models in `ai_models` share the load. Requests are spaced 4 seconds apart. If every model is rate-limited, the run waits one minute and tries again; if they\'re still limited, the daily quota is used up, so the rest of the run skips Gemini (footage falls back to the topic terms, titles to the source video\'s title).\n\n**Backup AI:** when every Gemini model is out of quota or busy, the same request goes straight to **Groq** (free, no card, about 1,000 requests a day per model; `openai/gpt-oss-120b`, then `qwen/qwen3.8-27b`), so videos are still made. The log shows `[AI] Gemini unavailable; written by groq ...`, and the start of every run logs whether the Groq key is set. Change or add backups under `ai_fallbacks` in `BRAIN.md`. Gemini still writes Hindi and Telugu best, so it stays first.\n\n### A typical day\n\nBoth channels run together three times a day: 13 videos in all. Each run sends a Telegram "run started" message, then one message per channel when its videos are uploaded, and once a day the Analyst\'s performance report.\n\n| Run (IST) | Frontline Ledger (8 a day) | WonderSprout (5 a day: long videos do better there) |\n|---|---|---|\n| 06:00 morning | long 12:00, Shorts 08:00 and 10:00 | long 11:30, Short 09:00 |\n| 13:00 afternoon | long 16:30, Shorts 14:00 and 16:00 | long 16:00, Short 14:30 |\n| 17:00 evening | Shorts 18:00 and 19:00 | long 18:30 |\n\nYouTube publishes each video at its time even though the GitHub job finished hours earlier.\n\n**Start times:** GitHub starts scheduled runs late (4 to 5 hours in October 2026), so `github_schedule_lead_minutes` in `BRAIN.md` (265) makes the GitHub schedule fire that much earlier: 01:35, 08:35 and 12:35 IST, so runs start near 06:00, 13:00 and 17:00. If GitHub is ever on time, the run simply starts early; the videos still go live at their times. The start message shows how early or late each run was; if it drifts, change the lead and run `--check`. A go-live time that has already passed by upload time goes live 10 minutes after upload instead, 30 minutes apart.\n\n**Hashtags:** each video gets up to 12 hashtags in its description. YouTube shows the first three above the title, so they are the two hashtags the **fastest-rising videos in the niche are using right now** (counted by the Scout across ~15 trending videos, weighted by views per hour) and the strongest topic hashtag. Then `#shorts` for Shorts, the other topic hashtags from the AI (2 broad, 3 specific to the story), the remaining trending ones, and the source video\'s own. Generic tags (#viral, #fyp, #trending) and other channels\' names are left out. The same words, plus the footage topic terms, go into the video\'s search tags. The Telegram message lists them.\n\n---\n\n## How Posting Works\n\nFor each channel, every day it is scheduled (`days`):\n\n1. **At `fetch_time`**, GitHub starts the pipeline:\n   - It finds trending topics for your `genre` and `search_phrases` on YouTube.\n   - It downloads matching **free stock clips from Pixabay** (or Pexels). YouTube blocks downloading its videos from cloud servers like GitHub\'s, and stock footage also avoids copyright claims.\n   - It writes a script in your `language`, narrates it with your `voice` at your `voice_speed`, and edits the clips into a montage.\n2. **It uploads all `videos_per_day` videos at once**, each with its own go-live time: the first at `first_post_time`, then one every `post_frequency`.\n3. **YouTube publishes each video exactly at its time**, even though GitHub has already finished.\n\nExample: `fetch_time "06:00"`, `first_post_time "07:00"`, `post_frequency "1 hour"`, `videos_per_day 12` → videos go live at 07:00, 08:00, 09:00 … 18:00.\n\n**Several runs a day:** give `fetch_time` a list, e.g. `["06:00", "13:00"]`. `videos_per_day` and `long_videos_per_day` stay day totals; each run makes the videos whose go-live time falls between its fetch time and the next one. `--check` prints each run\'s share, e.g. `Run 06:00 -> 1 long (12:00) + 2 Shorts (08:00, 11:00)`. A one-off run with `--videos`, `--first-post`, `--frequency` or `--post-now` ignores the split and uses the numbers you typed.\n\n| `post_frequency` | 12 videos starting 07:00 go live |\n|---|---|\n| `"15 mins"` | 07:00, 07:15 … 09:45 |\n| `"30 mins"` | 07:00, 07:30 … 12:30 |\n| `"1 hour"` | 07:00, 08:00 … 18:00 |\n| `"3 hours"` | 07:00, 10:00 … 16:00 the next day (too long, so `--check` warns you) |\n\n**Long videos (Q22 to Q24)** are made in the same run, **before** the Shorts, so they\'re ready well ahead of their go-live times. Their length never exceeds the upper number of `long_video_minutes`: if the narration runs long, the script is shortened and narrated again.\n\n| | Shorts | Long videos |\n|---|---|---|\n| Shape | Vertical 1080×1920 | Landscape 1920×1080 |\n| Length | `video_length_seconds` (15 to 60 s) | `long_video_minutes` (Frontline 5 to 7 min, WonderSprout 5 to 7 min plus her intro and outro) |\n| Topics from | Trending Shorts | Trending 4 to 20 minute videos on the same search phrases |\n| Script | Hook plus one idea | Hook, 3 to 5 parts, recap and a question for comments |\n| Footage | About 6 scenes (`clips_per_video`), one matching clip each | One matching clip about every 8 seconds (`long_scene_seconds`), about 30 to 50 |\n| Goes live | `first_post_time`, then every `post_frequency` | At each `long_post_times` entry |\n\nA long video takes roughly 12 minutes to build on GitHub (videos are assembled with FFmpeg for speed). `--check` estimates the monthly GitHub time for all your answers.\n\n**Every video looks and sounds the same way:**\n- **Audio:** only the AI narration; the source video\'s own sound is removed.\n- **Watermark:** in the bottom-right corner.\n- **End card:** a 3-second closing card with the channel name in large text, a **LIKE** button first, then **SUBSCRIBE**.\n  - Change the card\'s length or wording, or turn it off, under `end_card` in `BRAIN.md`.\n  - To also show a logo, set `show_logo: true` there. The logo is the channel\'s YouTube profile picture, saved in `GDrive_Mount/YouTube_Automation/00_branding/`, or the image set as `logo_file` in `channels.yaml`.\n\nIf preparing the videos takes longer than planned, a passed go-live time is replaced by one shortly after upload. Allow at least 30 minutes between `fetch_time` and `first_post_time` (about 3 minutes per Short, 12 per long video).\n\n---\n\n## The Questions (`questions.yaml`)\n\n| # | Question | Field | Options |\n|---|---|---|---|\n| Q1 | Channel to post to | the key (e.g. `kids_edu`) | Any key from `channels.yaml` |\n| Q2 | Include this channel? | `run` | `true` \\| `false` |\n| Q3 | Genre to source trending videos for | `genre` | Any text |\n| Q4 | YouTube searches that find trending Shorts | `search_phrases` | 1 to 5 lines; add `#shorts` to each |\n| Q5 | Narration language | `language` | `"English"` \\| `"Hindi"` \\| `"Telugu"` |\n| Q6 | Narrator voice | `voice` | See voices below; must match the language |\n| Q7 | Speaking speed | `voice_speed` | `"-15%"` slow and very clear \\| `"-5%"` clear (recommended) \\| `"+0%"` natural \\| `"+10%"` brisk |\n| Q7b | How lively the voice is | `voice_expression` | `"lively"` (kids: big highs and lows) \\| `"measured"` (news: subtle emphasis) \\| `"off"` (one even tone, the old way). Default: lively for made-for-kids channels, measured for others |\n| Q8 | Narration style | `tone` | Any text |\n| Q9 | Length of each video | `video_length_seconds` | `15` \\| `30` \\| `45` \\| `60` |\n| Q10 | Words the script must never use | `avoid_words` | `[]` or `["word1", "word2"]` |\n| Q11 | Use trending videos from the last N days | `lookback_days` | `1` to `30` |\n| Q12 | When to fetch and prepare videos | `fetch_time` | `"HH:MM"` (24-hour), or a list like `["06:00", "13:00"]` for several runs a day |\n| Q13 | When each Short goes live | `short_post_times` | A list like `["08:00", "10:00"]`, one per Short. Or leave it out and use Q13 to Q15 below |\n| Q13 | When the first Short goes live | `first_post_time` | `"HH:MM"` |\n| Q14 | Gap between Shorts | `post_frequency` | `"15 mins"` \\| `"30 mins"` \\| `"1 hour"` \\| `"3 hours"` |\n| Q15 | Shorts to post each day (all runs together) | `videos_per_day` | `1` to `50` |\n| Q16 | Which days | `days` | `"daily"` \\| `"weekdays"` \\| `"weekends"` \\| `[mon, wed, fri]` |\n| Q17 | Timezone for all times | `timezone` | `"Asia/Kolkata"`, `"America/New_York"`, `"Europe/London"`, … |\n| Q18 | Who can see the videos | `visibility` | `"public"` \\| `"unlisted"` \\| `"private"` |\n| Q19 | Make videos without uploading | `test_run` | `true` \\| `false` |\n| Q20 | YouTube channels never to take videos from | `exclude_sources` | `[]` or `["Channel Name 1", "Channel Name 2"]` |\n| Q22 | Long landscape videos per day | `long_videos_per_day` | `0` (none) to `4` |\n| Q23 | Length of each long video | `long_video_minutes` | `4` \\| `5` \\| `6` \\| `7` \\| `"4-5"` \\| `"4-6"` \\| `"5-6"` \\| `"5-7"` \\| `"6-7"` (a range gives each video a different length, never above the upper number) |\n| Q24 | When each long video goes live | `long_post_times` | one `"HH:MM"` per long video, e.g. `["14:00", "20:00"]` |\n| Q21 | Kind of clips used | `footage_style` | `"any"` \\| `"animation"` (cartoon) \\| `"film"` (real-life stock) \\| `"mixed"` (cartoon and real-life alternate) \\| `"real"` (real footage of the actual people and events from Wikimedia Commons first, then real-life stock). Pexels has no cartoon filter. |\n\n**How source videos are picked:** the Scout searches the channel\'s phrases **best first** (the Analyst orders them by how many views their videos got after 48 hours; phrases not used for 3 days are tried again first), and only as many phrases as it needs (about one YouTube search per video). Within a search it ranks videos by **views per hour** (what is rising now) and skips videos in another language. It takes **at most one video per source channel per run**, avoids channels used for any of that channel\'s last 5 videos, and never uses channels in `exclude_sources`. Only the topic is used, never the video itself.\n\nDelete a line to use its default. Defaults: English, a natural voice for the language, `-5%` speed (`-15%` for kids), 30-second videos, last 5 days, 1 video, `"1 hour"`, daily, `Asia/Kolkata`, public, uploads on. If `first_post_time` is left out, videos go live as soon as they are uploaded.\n\n**Voices:**\n\n| Language | Voice | Style |\n|---|---|---|\n| English | `en-US-AvaMultilingualNeural` | Female, expressive, very natural (**WonderSprout**) |\n| English | `en-US-BrianMultilingualNeural` | Male, casual, very natural (**Frontline**) |\n| English | `en-US-EmmaMultilingualNeural` / `en-US-AndrewMultilingualNeural` | Female cheerful / male warm, very natural |\n| English | `en-US-AndrewNeural` | Male, warm, all-rounder |\n| English | `en-US-ChristopherNeural` | Male, authoritative, news |\n| English | `en-US-GuyNeural` | Male, energetic, sports |\n| English | `en-US-AriaNeural` | Female, confident, news |\n| English | `en-US-EmmaNeural` | Female, cheerful, kids and education |\n| English | `en-US-AnaNeural` | **Child voice** (young girl); best for kids channels |\n| English | `en-US-JennyNeural` | Female, friendly, calm |\n| English | `en-IN-PrabhatNeural` / `en-IN-NeerjaNeural` | Indian English, male / female |\n| Hindi | `hi-IN-MadhurNeural` / `hi-IN-SwaraNeural` | Male / female |\n| Telugu | `te-IN-MohanNeural` / `te-IN-ShrutiNeural` | Male / female |\n\nFor Hindi and Telugu, scripts, titles and descriptions are written in the native script. Write `search_phrases` in whichever language finds the best trending videos for your genre.\n\n---\n\n## The Channel Page (`channels.yaml`)\n\n| Field | Required | Options |\n|---|---|---|\n| *key* | yes | Lowercase letters, numbers, underscores; starts with a letter; unique |\n| `channel_name` | yes | Exactly as on YouTube |\n| `channel_url` | yes | The channel link: `https://www.youtube.com/@handle` or `https://www.youtube.com/channel/UC...`. Sign-in and every upload check that the YouTube login is this exact channel, so videos never go to the wrong one. |\n| `made_for_kids` | yes | `true` \\| `false` (`true` only for children under 13: legal COPPA setting, limits ads) |\n| `watermark_text` | no | Default `@` + channel name |\n| `logo_file` | no | Image for the end card, e.g. `"execution/logos/my_logo.png"`. Default: the channel\'s YouTube profile picture |\n| `category_id` | no | `"24"` Entertainment (default), `"25"` News & Politics, `"27"` Education (default for kids), `"17"` Sports, `"28"` Science & Technology. The full list is in the file. |\n\n---\n\n## One-Time Setup\n\n| # | Step | How |\n|---|---|---|\n| 1 | Python environment | `python -m venv C:\\Users\\<you>\\venvs\\yt`, then `C:\\Users\\<you>\\venvs\\yt\\Scripts\\python.exe -m pip install -r requirements.txt`. A short path avoids Windows\' long-path error, and no admin rights are needed. |\n| 2 | API keys | Copy `.env.example` to `.env` and fill in `YOUTUBE_API_KEY`, `GEMINI_API_KEY`, and optionally the Telegram values. |\n| 3 | Upload permission | Save your Google Cloud **OAuth Desktop client** file as `client_secret.json` in `youtube-automation-agents`. On the OAuth consent screen click **Publish app**; otherwise logins expire every 7 days. |\n| 4 | Google Drive | Create the folder `YouTube_Automation/00_tokens/`. |\n| 5 | rclone | `rclone config` and create a remote named exactly **`gdrive`** (type: drive). |\n| 6 | Stock footage key | Create a free account at [pixabay.com](https://pixabay.com/accounts/register/), open [pixabay.com/api/docs](https://pixabay.com/api/docs/) while logged in, copy the key shown under **Parameters → key**, and add it to `.env` as `PIXABAY_API_KEY`. (A Pexels key in `PEXELS_API_KEY` also works.) |\n| 7 | GitHub secrets | Repo → Settings → Secrets and variables → Actions. Add the 8 secrets below. |\n\n| Secret | Contents |\n|---|---|\n| `YOUTUBE_API_KEY` | YouTube Data API v3 key |\n| `GEMINI_API_KEY` | Gemini API key |\n| `PIXABAY_API_KEY` | Pixabay API key (free stock footage). To use Pexels instead, add a `PEXELS_API_KEY` secret and pass it in step 6 of the workflow the same way. |\n| `TELEGRAM_BOT_TOKEN` | Telegram bot token |\n| `TELEGRAM_CHANNEL_ID` | Telegram channel ID (starts with `-100`) |\n| `GROQ_API_KEY` | Free backup AI (console.groq.com → API Keys). Optional but recommended |\n| `CLIENT_SECRET_JSON` | Full contents of `client_secret.json` |\n| `RCLONE_CONFIG_GDRIVE` | Full contents of the file shown by `rclone config file` |\n\n---\n\n## Adding a Channel\n\n1. **Create the channel on YouTube:** [youtube.com/channel_switcher](https://www.youtube.com/channel_switcher) → **Create a channel**.\n2. **`channels.yaml`:** copy the TEMPLATE, paste it under `channels:`, remove the `# `, and fill in the 5 lines.\n3. **`questions.yaml`:** copy the TEMPLATE, paste it under `channels:` with the **same key**, remove the `# `, and answer each question by copying an option from its comment.\n4. **Sign in to YouTube:** `python execution/execution.py --authorize <key>`. Upload the token file it prints to Google Drive `YouTube_Automation/00_tokens/`.\n5. **Check:** `python execution/execution.py --check`\n6. **Test:** `python execution/execution.py --channel <key> --dry-run`\n7. **Push to GitHub** so the schedule goes live: `git add -A`, `git commit -m "Add <key>"`, `git push`.\n\nTo pause a channel, set `run: false`. To remove one, delete it from both files. Then run `--check` and push.\n\n---\n\n## Ways to Run\n\n### GitHub (automatic)\n\nNothing to do. Each channel runs at its `fetch_time` on its `days`.\n\n### GitHub (manual)\n\nGitHub → **Actions** → **Daily YouTube Multi-Agent Pipeline** → **Run workflow**. Leave any field blank to use `questions.yaml`.\n\n| Field | Meaning |\n|---|---|\n| `channel` | `all` (every channel with `run: true`) or one channel key |\n| `genre` | One-off genre |\n| `videos` | One-off number of videos |\n| `first_post_time` | One-off first go-live time (`HH:MM`) |\n| `frequency` | One-off gap: 15 mins, 30 mins, 1 hour or 3 hours |\n| `format` | `both` (default), `short` (Shorts only) or `long` (long videos only) |\n| `dry_run` | Tick to make videos without uploading |\n\n### IDE, terminal or Copilot\n\nOpen `execution.py` and press **Run**, or run this from the `youtube-automation-agents` folder:\n\n```bash\nC:\\Users\\<you>\\venvs\\yt\\Scripts\\python.exe execution/execution.py\n```\n\nIt runs **every channel with `run: true`** using its answers in `questions.yaml`. To have Copilot (or any assistant) run it, say:\n\n> Run `python execution/execution.py` from the `youtube-automation-agents` folder using `C:\\Users\\<you>\\venvs\\yt\\Scripts\\python.exe`.\n\n### Interactive one-off (`--ask`)\n\n`python execution/execution.py --ask` asks the questions on screen, starting from your `questions.yaml` answers, and runs once. `questions.yaml` itself is not changed.\n\n---\n\n## Command Reference\n\n| Command | What it does |\n|---|---|\n| `python execution/execution.py` | Run every channel with `run: true`, using `questions.yaml` |\n| `... --channel KEY` | Run one channel |\n| `... --channel all` | Same as no arguments |\n| `... --genre "cricket highlights"` | One-off genre (search becomes `"<genre> #shorts"`) |\n| `... --videos 6` | One-off number of videos |\n| `... --first-post "09:00"` | One-off first go-live time |\n| `... --frequency "30 mins"` | One-off gap: `"15 mins"`, `"30 mins"`, `"1 hour"` or `"3 hours"` |\n| `... --post-now` | One-off: every video goes live as soon as it is uploaded |\n| `... --visibility unlisted` | One-off visibility: `public`, `unlisted` or `private` |\n| `... --dry-run` | Make videos, don\'t upload |\n| `... --format short` / `--format long` | Make only Shorts, or only long videos (default: both) |\n| `python execution/execution.py --ask` | Answer the questions on screen for a one-off run |\n| `python execution/execution.py --check` | Validate both files, show plans and YouTube usage, update the GitHub schedule |\n| `python execution/execution.py --list` | Show channels, plans and YouTube login status |\n| `python execution/execution.py --authorize KEY` | Sign in to YouTube for a channel |\n| `python execution/execution.py --hero-art FOLDER` | Import pictures of the WonderSprout character into `assets/wondersprout/` (see [PROMPTS.md](../assets/wondersprout/PROMPTS.md)) |\n| `python execution/execution.py --learn LINK` | Analyse a YouTube video about getting views and add its techniques to [view_techniques.md](view_techniques.md) as a proposal to review (uses the subtitles, or Gemini watches the video) |\n| `python execution/execution.py --inbox` | Handle the links and requests posted in the Telegram channel (what the hourly Telegram Inbox workflow runs) |\n\n---\n\n## Telegram Inbox: Share a Video or Ask for One\n\nPost in the Telegram alerts channel (the one the bot posts to; only channel admins can post there). The\n**Telegram Inbox** workflow ([telegram_inbox.yml](../../.github/workflows/telegram_inbox.yml)) checks it every hour\n(GitHub may start it late; Telegram keeps unread posts for 24 hours), and the bot replies in the channel.\n\n| You post | What happens |\n|---|---|\n| A **YouTube link** to a video about getting views | Gemini watches it and adds a "proposed" entry to [view_techniques.md](view_techniques.md). The bot lists the proposed rules. |\n| `approve S5` / `approve S5 1,3` / `reject S5` | Adds all (or only rules 1 and 3) of S5\'s proposed rules to ACTIVE RULES, so every video from the next run follows them; or drops them. |\n| A **YouTube link** to a video you\'d like more of (add "kids" or "frontline" to choose the channel) | Gemini watches it, picks the channel, and notes what makes it work. It\'s queued in [video_requests.json](video_requests.json): that channel\'s next Short (or long video, if it is one) is an original video like it (same topic and format, never its words, characters, music or footage), and its trend\'s search phrases lead the Scout\'s searches for 7 days. |\n| A request, e.g. `make a kids video about how octopuses hide` or `frontline long video on the India Russia oil deal` | The AI works out the channel, format and topic (and checks it\'s safe for kids on WonderSprout) and queues it the same way. |\n| `queue` | Lists the requests of the last 14 days. |\n| `cancel Q3` | Drops a request. |\n\nA queued request takes one of its channel\'s normal slots in the next run (the day\'s number of videos doesn\'t change);\nthe upload message marks it with 📌. Instagram, TikTok and Facebook links can\'t be opened from GitHub (they need a\nlogin). The workflow commits view_techniques.md and video_requests.json to `main` when they change.\n\n## Getting More Views\n\n[view_techniques.md](view_techniques.md) holds what we\'ve learned about views:\n- **ACTIVE RULES** are sent to Gemini with every script, title and hashtag (trends first, stay in the niche, write for retention, honest click-worthy titles).\n- **HOW THE PIPELINE APPLIES THEM** lists what the code does (rising topics, same-language sources, the Analyst\'s feedback loop, the fixed schedule) and what the owner does by hand (thumbnails after phone verification, checking view duration and click-through rate in Studio).\n- **SOURCES** records every video analysed and what was adopted or rejected.\n\nTo learn from a new video, post its link in the Telegram channel (see Telegram Inbox above), run `python execution/execution.py --learn <link>`, or give the link to Claude. It adds a "proposed" entry; nothing changes until good rules are copied into ACTIVE RULES. Anything that fakes engagement, misleads viewers or re-uploads other people\'s content is rejected: it breaks YouTube\'s policies.\n\n## WonderSprout, the Kids Channel\'s Superhero Host\n\nWonderSprout is the kids channel\'s superhero host and narrator (`mascot: "wondersprout"` in `channels.yaml`, made-for-kids channels only). The AI writes each script as her, in the first person, in the channel\'s voice (Ava).\n\n| Part | What viewers see and hear | Setting (`editing_rules.mascot` in `BRAIN.md`) |\n|---|---|---|\n| Intro (long videos) | She swoops in through a sky of drifting clouds with a whoosh, hovers, waves and says `intro_line` ("Hey kids! This is Wonder Sprout, your fun and learning superhero!"); her name pops up with a sparkle chime, over a soft wind sound (about 6 s) | `intro_long`, `intro_line` |\n| Host | In the bottom-left corner throughout: amazed ("Whoa!"), thinking ("Can you guess…?"), asking (questions), happy, waving, talking, sentence by sentence; her mouth moves with the voice | `host` |\n| Shorts opening | She swoops into her corner during the first second while the hook plays (a separate intro makes Shorts viewers swipe away; `intro_shorts: true` adds it anyway) | `intro_shorts` |\n| Outro | In the sky she waves and says `outro_line` ("Wonder Sprout signing off, kids! We\'ll meet next time!"), then flies off into the distance with a whoosh and a sparkle trail, before the LIKE / SUBSCRIBE card (about 6 s) | `outro`, `outro_line` |\n\nThe intro and outro add about 12 seconds; long kids videos can therefore run a little past `long_video_minutes` (agreed by the owner: up to 7 to 8 minutes is fine).\n\n**Your own intro and outro videos.** If `assets/wondersprout/intro.mp4` / `outro.mp4` exist (optional vertical `intro_short.mp4` / `outro_short.mp4` for Shorts), every video uses them instead of the generated ones, fitted to the video\'s shape without stretching (a clip without sound gets silence). What to provide: [assets/wondersprout/PROMPTS.md](../assets/wondersprout/PROMPTS.md); drop files in Google Drive `YouTube_Auto/wondersprout_assets/`.\n\n**Status:** the owner\'s character (9 poses) and intro/outro videos were imported on 2026-10-24 and are in `assets/wondersprout/` (kept in git, so GitHub runs use them; `setup_project.py` holds only text files, so copy that folder too when moving the project).\n\n**Her look.** Until pictures of the real character are added, the pipeline draws a simple cartoon version ([mascot.py](../agents/mascot.py)). The real character (from the owner\'s reference image) needs 9 pictures of her in different poses, because one picture can\'t change expression or talk:\n1. Make them with the free Gemini app or ChatGPT from the reference image, using the prompts in [assets/wondersprout/PROMPTS.md](../assets/wondersprout/PROMPTS.md) (plain magenta background).\n2. Run `python execution/execution.py --hero-art "<folder with the pictures>"`. It cuts out the background (or keeps a transparent one), keeps only her (an image AI\'s corner logo such as "Grok" is dropped), cleans any magenta fringe from her hair, crops and resizes the pictures into `assets/wondersprout/`, imports `intro.mp4` / `outro.mp4` with a small green "WS" badge covering the image AI\'s logo in the bottom-right corner, and saves a preview sheet.\n3. Commit and push, so GitHub\'s runs use them. From then on she replaces the drawing everywhere; a missing pose borrows the closest one.\n\n(The Gemini API\'s free tier can\'t generate images, so this step is done by hand once; with billing on, it could be automated for under $1.)\n\n### Audio Standards & Sound Design (Calibrated 2026-10-31)\n\nTo ensure seamless viewing without jarring volume jumps or ear fatigue, all videos follow broadcast audio leveling standards:\n\n| Component | Target Loudness | Leveling / Filter | Purpose |\n|---|---|---|---|\n| **Hero Intro Clip** | -20.0 dB mean (max -5.5 dB) | `-af volume=0.28` | Attenuates raw 0 dBFS 3D render audio down by ~10.9 dB to match speech |\n| **Main Narration** | -20.5 dB mean (max -3.4 dB) | `volume=1.15` in `amix` | Clear, energetic voiceover without clipping |\n| **Background Music (BGM)** | Ducked under speech | `volume=0.12`, fade in 1.5s, fade out 2.0s | Tracks in `assets/audio/kids_bgm`, rotated per video |\n| **Sound Effects (SFX)** | Accents actions | `volume=0.35`, timed via `adelay` | Cartoon SFX (`[BOING]`, `[POP]`, `[TICK]`, `[TADA]`) triggered by script tags. Tags are never spoken; the sound plays where the tag sits in the sentence, and repeated tags (`[TICK] [TICK] [TICK]`) play 0.6 s apart |\n| **Hero Outro Clip** | -20.2 dB mean (max -5.6 dB) | `-af volume=0.28` | Matches the outro greeting smoothly to the preceding narration |\n\n**Critical FFmpeg `amix` Rule:** When combining multiple audio tracks in `mix_soundtrack`, the FFmpeg `amix` filter must ALWAYS include `:normalize=0` (`amix=inputs=...:duration=first:dropout_transition=2:normalize=0`). Without `normalize=0`, FFmpeg automatically scales down audio by 1/N for each additional track, which previously suppressed narration down to -34 dB. Setting `normalize=0` keeps speech at full volume while BGM and SFX are blended underneath.\n\n## Where the Footage Comes From\n\nSet under `footage` in `BRAIN.md`:\n\n| `source` | What it does | Works on GitHub? |\n|---|---|---|\n| `"stock"` (default) | The script is written and narrated first, and the narration is split into scenes using the voice\'s sentence timings (about `clips_per_video` scenes in a Short, one about every `long_scene_seconds` in a long video). Gemini picks a search term from **each scene\'s own words**, one matching clip per scene is downloaded from Pixabay or Pexels (`provider`), and each clip plays exactly while its scene is narrated. Contributors are recorded in the manifest; descriptions don\'t credit stock sites (owner\'s decision, 2026-10-31). | Yes |\n| `"youtube"` | Re-uses the trending video itself. | **No.** YouTube blocks downloads from cloud servers ("Sign in to confirm you\'re not a bot"). Works only when run from your laptop. |\n\n`clips_per_video` (6) sets how many clips a Short uses and `long_scene_seconds` (8) how often a long video changes clip; faster changes hold attention better. The free limits (Pixabay: 100 requests a minute; Pexels: 200 an hour) are enough; searches are paced.\n\n**Real footage (`footage_style: "real"`, Frontline):** for each scene that names a person, country, ship or event, the pipeline searches **Wikimedia Commons** for real video of it (official government channels such as the White House, US military, Kremlin.ru, the Ukrainian president\'s office and the EU publish there, often within days). Rules:\n- **Licences:** only public domain, CC0 and CC BY are used; share-alike, non-commercial and no-derivatives licences are skipped because they don\'t allow use in a monetised video.\n- **Match:** every name word of the scene\'s term must be in the clip\'s title (a Zelensky scene gets Zelensky footage); longer terms are retried with just the name ("Narendra Modi summit" → "Narendra Modi").\n- **Only the needed seconds** are fetched, from about a quarter into the video (skipping intros), so long speeches aren\'t downloaded whole. A matching video already used is reused from a later moment.\n- **Credit:** each clip\'s author, licence and link are listed in the description.\n- **No video of it? A real photo:** when Commons has no matching video, a freely licensed real photo of the person, place or event is used instead: shown whole on a blurred copy of itself (faces are never cropped) with a slow zoom.\n- Scenes with no real video or photo use real-life Pixabay clips.\n\nNews-agency footage (Reuters, AP, ANI, broadcasters\' YouTube channels) is **not** used: it\'s copyrighted, would bring Content ID claims and copyright strikes, and can get a channel removed.\n\n## Where Video Files Are Kept\n\n| Run from | Downloaded videos | Narration and final (uploaded) videos | Deleted |\n|---|---|---|---|\n| Your laptop / IDE / Copilot | `H:\\My Drive\\YouTube_Auto\\<YYYY-MM-DD>\\download\\` (Google Drive) | `H:\\My Drive\\YouTube_Auto\\<YYYY-MM-DD>\\upload\\` | Whole day folders older than 2 days, automatically at the end of each run |\n| GitHub | Temporary folders on GitHub\'s machine | Temporary folders on GitHub\'s machine | Right after upload; the machine is wiped after every run |\n\nChange the folder or the number of days under `local_media` in `BRAIN.md` (`root`, `keep_days`). If Google Drive for Desktop isn\'t running (no `H:` drive), that run uses `C:\\Users\\<you>\\YouTube_Auto` instead. Files in the Google Drive folder count toward your Drive storage, so the 2-day limit also keeps Drive from filling up. To clear space by hand, delete any day folder you no longer need; videos from that day that weren\'t uploaded yet are skipped automatically.\n\nThe manifest, YouTube logins and logos always stay in `GDrive_Mount/YouTube_Automation/`, because GitHub runs share them through Google Drive.\n\nA second workflow, **Telegram Inbox** ([telegram_inbox.yml](../../.github/workflows/telegram_inbox.yml)), runs every hour on its own: it\nreads your posts in the Telegram channel, replies, and commits `view_techniques.md` and `video_requests.json` to `main`\nwhen they change. See *Telegram Inbox* below.\n\n## Good to Know\n\n- **GitHub may start a scheduled run hours after its scheduled time** (4 to 5 hours in October 2026). `github_schedule_lead_minutes` in `BRAIN.md` compensates (see "A typical day"). Future go-live times are always exact, because YouTube publishes them.\n- **Public repository:** Actions minutes are unlimited and secrets stay hidden (GitHub never shows them, masks them in logs, and doesn\'t give them to pull requests from forks). Run logs are public, so they must never print key values; the code masks them.\n- **The workflow file stores times in UTC**, so 06:00 IST appears as `30 0 * * *`. `--check` handles this.\n- **Daylight saving:** India has none. For timezones that do, run `--check` and push after each clock change.\n- **GitHub free minutes:** private repos get 2,000 a month. A Short takes about 3 minutes to build and a long video about 12. Run `--check` to see the estimate for your answers. If it\'s near or over 2,000, lower the counts or make the repository public; public repos have unlimited free minutes, and your keys stay safe in GitHub secrets either way.\n- **Test-run videos are kept** at "edited" and are uploaded by that channel\'s next real run.\n\n## Troubleshooting\n\n| Problem | Fix |\n|---|---|\n| "Please fix these problems" | Each line names the file, channel and field. Copy the correct option from the comment beside it. |\n| "No YouTube login file" | `--authorize <key>`, then upload the token to Drive `YouTube_Automation/00_tokens/`. |\n| "You signed in to \'...\' but \'<key>\' is ..." | You picked a different channel in the browser. Run `--authorize <key>` again and choose the channel matching `channel_url`. |\n| "Access blocked" / "app has not completed verification" when signing in | The account that owns the channel isn\'t a test user. Google Cloud Console → OAuth consent screen → add it under **Test users**, or click **Publish app**. |\n| "login is missing or expired" on GitHub | Same as above. If it happens weekly, publish the OAuth consent screen (One-Time Setup, step 3). |\n| "Cannot start: No .env file" | Copy `.env.example` to `.env` and fill in the keys. |\n| `--check` warns about YouTube usage | Lower `videos_per_day` or the number of `search_phrases`, or request more quota in Google Cloud Console. |\n| `pip` says "filename too long" | Use a short-path venv (One-Time Setup, step 1). |\n| "429 RESOURCE_EXHAUSTED" from Gemini | The Gemini quota is used up (free tier: 20 requests a day per model, reset at 12:30 IST). Groq takes over automatically if `GROQ_API_KEY` is set (check the run log line "Backup AI when Gemini is out of quota: groq (key set)"). If both are out, finished videos still upload with the source video\'s title. |\n| "The user has exceeded the number of videos they may upload" | YouTube\'s daily upload limit for that channel (low for new, unverified channels). Verify the channel by phone at youtube.com/verify. The video stays queued and uploads on a later run. |\n| Runs start far from 06:00 / 13:00 / 17:00 | GitHub\'s delay changed. The Telegram start message shows how early or late; change `github_schedule_lead_minutes` in `BRAIN.md`, run `--check` and push. |\n| The bot doesn\'t reply to a post in Telegram | Actions → **Telegram Inbox** → the latest run\'s step 4 log. GitHub may start the hourly run late; Telegram keeps unread posts for 24 hours. The bot must stay an admin of the channel, and only YouTube links can be watched. |\n| Telegram Inbox fails at step 5 (push) | Settings → Actions → General → Workflow permissions → **Read and write permissions**, then re-run it. |\n| Narration fails | The free voice service occasionally changes. Run `pip install -U edge-tts`. Videos stay queued and retry on the next run. |\n',
    'execution/channels.yaml': '# =====================================================================\n#  CHANNEL PAGE  -  who each channel is\n#  Create the channel on YouTube yourself first, then list it here.\n#  What and when each channel posts is answered in: execution/questions.yaml\n#  Full rules: execution/execution.md\n# =====================================================================\n#\n#  RULES\n#    - The channel key (e.g. geopolitics_war) must be lowercase letters,\n#      numbers and underscores, start with a letter, and be unique.\n#      Use the SAME key in questions.yaml.\n#    - Indent with spaces, never tabs.\n#    - After any change run:  python execution/execution.py --check\n# =====================================================================\n\nchannels:\n\n  geopolitics_war:\n    channel_name: "Frontline Ledger TT83"                            # REQUIRED: exactly as on YouTube\n    channel_url: "https://www.youtube.com/@frontline-ledger-tt83"    # REQUIRED: channel link; uploads only go ahead if the YouTube login matches it\n    made_for_kids: false                                             # REQUIRED: true | false  (true only for children under 13, legal COPPA setting)\n    watermark_text: "@frontline-ledger-tt83"                         # optional: default is @ + channel name\n    category_id: "25"                                                # optional: see category list below (default "24", or "27" for kids)\n\n  kids_edu:\n    channel_name: "WonderSprout Kids TT83"\n    channel_url: "https://www.youtube.com/channel/UCf9u1ZaejKPPA-oOD8oXVfg"\n    made_for_kids: true\n    watermark_text: "WonderSprout Kids"\n    mascot: "wondersprout"                 # superhero host in every video (kids channels only); leave out for none\n    category_id: "27"\n\n# =====================================================================\n#  TEMPLATE  (copy, paste under "channels:", remove the "# ")\n# =====================================================================\n#\n#  my_channel_key:\n#    channel_name: "Exact Channel Name On YouTube"\n#    channel_url: "https://www.youtube.com/@myhandle"     # or https://www.youtube.com/channel/UC...\n#    made_for_kids: false\n#    watermark_text: "@MyHandle"\n#    category_id: "24"\n#    logo_file: "execution/logos/my_logo.png"   # optional: end-card logo; default is the channel\'s YouTube profile picture\n#\n#  CATEGORY OPTIONS (category_id):\n#    "1" Film & Animation   "2" Autos & Vehicles   "10" Music        "15" Pets & Animals\n#    "17" Sports            "19" Travel & Events   "20" Gaming       "22" People & Blogs\n#    "23" Comedy            "24" Entertainment     "25" News & Politics\n#    "26" Howto & Style     "27" Education         "28" Science & Technology\n',
    'execution/questions.yaml': '# =====================================================================\n#  EXECUTION QUESTIONS  -  what and when each channel posts\n#\n#  execution.py reads this file every time it runs: from GitHub, from an\n#  IDE, from a terminal, or when you ask Copilot to "run execution.py".\n#  Answer the questions once per channel. The options for each question\n#  are in the comment beside it: copy one option and paste it as the value.\n#\n#  HOW POSTING WORKS\n#    At fetch_time the pipeline finds trending videos, writes and narrates\n#    a script for each, edits them, and uploads them all to YouTube with a\n#    go-live time: the first at first_post_time, then one every\n#    post_frequency, until videos_per_day are scheduled.\n#    Example: fetch_time "06:00", first_post_time "07:00", post_frequency\n#    "1 hour", videos_per_day 12  ->  videos go live 07:00, 08:00 ... 18:00.\n#\n#    SEVERAL RUNS A DAY: give fetch_time a list, e.g. ["06:00", "13:00"].\n#    The day\'s videos (Shorts and long) are shared between the runs: each\n#    run makes the videos whose go-live time falls before the next run.\n#    Example: fetch ["06:00", "13:00", "17:00"],\n#    short_post_times ["08:00", "10:00", "14:00", "16:00", "18:00", "19:00"],\n#    long_post_times ["12:00", "16:30"]\n#      ->  06:00 run: Shorts 08:00 and 10:00, long 12:00\n#          13:00 run: Shorts 14:00 and 16:00, long 16:30\n#          17:00 run: Shorts 18:00 and 19:00 (no long video in its window)\n#    fetch_time is when you want a run to START. GitHub starts scheduled\n#    runs hours late, so the GitHub schedule fires earlier by\n#    github_schedule_lead_minutes (BRAIN.md). A go-live time that has\n#    already passed by upload time goes live soon after upload instead.\n#    Every run sends a Telegram message when it starts, then one message\n#    per channel listing the uploaded videos and their go-live times.\n#\n#  RULES\n#    - Channel keys must match execution/channels.yaml exactly.\n#    - Put text and times in quotes. Times are 24-hour "HH:MM".\n#    - Leave a question out (delete the line) to use its default.\n#    - After any change run:  python execution/execution.py --check\n#      then push to GitHub so the schedule updates.\n#    - YouTube allows 100 uploads and 100 searches per day in total across\n#      ALL channels. --check shows how much of that your answers use.\n#\n#  VOICE OPTIONS (copy the voice name that matches the language)\n#    English: "en-US-AndrewNeural"      male, warm, all-rounder\n#             "en-US-ChristopherNeural" male, authoritative, news\n#             "en-US-GuyNeural"         male, energetic, sports\n#             "en-US-AriaNeural"        female, confident, news\n#             "en-US-EmmaNeural"        female, cheerful, kids and education\n#             "en-US-AnaNeural"         CHILD voice (young girl), best for kids channels\n#             "en-US-AvaMultilingualNeural"   female, expressive, very natural (WonderSprout, chosen 2026-10-24)\n#             "en-US-EmmaMultilingualNeural"  female, cheerful, very natural\n#             "en-US-BrianMultilingualNeural" male, casual, very natural (Frontline, chosen 2026-10-24)\n#             "en-US-AndrewMultilingualNeural" male, warm, very natural\n#             "en-US-JennyNeural"       female, friendly, calm\n#             "en-IN-PrabhatNeural"     male, Indian English\n#             "en-IN-NeerjaNeural"      female, Indian English\n#    Hindi:   "hi-IN-MadhurNeural"      male\n#             "hi-IN-SwaraNeural"       female\n#    Telugu:  "te-IN-MohanNeural"       male\n#             "te-IN-ShrutiNeural"      female\n# =====================================================================\n\nchannels:\n\n  geopolitics_war:                         # Q1. Channel to post to (key from channels.yaml)\n    run: true                              # Q2. Include this channel?            Options: true | false\n    genre: "Geopolitics of India, Europe, Russia and America, and current and ongoing wars"\n                                           # Q3. Genre to source trending videos for (any text)\n    search_phrases:                        # Q4. YouTube searches that find trending Shorts (1 to 5 lines; each run starts from the next phrase)\n      - "India foreign policy geopolitics news #shorts"\n      - "Russia Ukraine war update #shorts"\n      - "Europe NATO news #shorts"\n      - "America US foreign policy news #shorts"\n      - "Middle East war update #shorts"\n    language: "English"                    # Q5. Narration language                Options: "English" | "Hindi" | "Telugu"\n    voice: "en-US-BrianMultilingualNeural"       # Q6. Narrator voice                    Options: see VOICE OPTIONS above (must match the language)\n    voice_speed: "-5%"                     # Q7. Speaking speed                    Options: "-15%" slow & very clear | "-5%" clear (recommended) | "+0%" natural | "+10%" brisk\n    voice_expression: "measured"           # Q7b. How lively the voice is        Options: "lively" (big highs and lows) | "measured" (subtle emphasis, news) | "off" (one even tone)\n    tone: "Serious, objective, analytical intelligence briefing."\n                                           # Q8. Narration style (any text)\n    video_length_seconds: 30               # Q9. Length of each video              Options: 15 | 30 | 45 | 60\n    avoid_words: ["dead", "killed", "blood", "massacre"]\n                                           # Q10. Words the script must never use  Options: [] for none, or ["word1", "word2"]\n    lookback_days: 5                       # Q11. Use trending videos from the last N days   Options: 1 to 30\n    fetch_time: ["06:00", "13:00", "17:00"]  # Q12. When each run starts           Options: "HH:MM" for one run a day, or ["HH:MM", ...] for several (videos are shared between them)\n    short_post_times: ["08:00", "10:00", "14:00", "16:00", "18:00", "19:00"]\n                                           # Q13. When each Short goes live (one per Short; replaces Q13 to Q15 below)   Options: list of "HH:MM"\n    # first_post_time: "08:00"             # Q13. Instead of short_post_times: first Short\'s go-live time\n    # post_frequency: "3 hours"            # Q14. ...then one every            Options: "15 mins" | "30 mins" | "1 hour" | "3 hours"\n    # videos_per_day: 4                    # Q15. ...this many Shorts a day    Options: 1 to 50\n    days: "daily"                          # Q16. Which days to post               Options: "daily" | "weekdays" | "weekends" | [mon, wed, fri]\n    timezone: "Asia/Kolkata"               # Q17. Timezone for all times above     Options: "Asia/Kolkata" | "America/New_York" | "Europe/London" | ...\n    visibility: "public"                   # Q18. Who can see the videos           Options: "public" | "unlisted" | "private"\n    test_run: false                        # Q19. Make videos without uploading    Options: true | false\n    exclude_sources: []                    # Q20. YouTube channels never to take videos from   Options: [] | ["Channel Name 1", "Channel Name 2"]\n    footage_style: "real"                  # Q21. Kind of clips   Options: "any" | "animation" (cartoon) | "film" (real-life stock) | "mixed" (alternate) | "real" (real footage of the actual people and events first, then stock)\n    long_videos_per_day: 2                 # Q22. Long landscape videos per day (all runs together)   Options: 0 (none) to 4\n    long_video_minutes: "5-7"              # Q23. Length of each long video         Options: 4 | 5 | 6 | 7 | "4-5" | "4-6" | "5-6" | "5-7" | "6-7" (a range varies each video; never longer than its upper number)\n    long_post_times: ["12:00", "16:30"]    # Q24. When each long video goes live    Options: one "HH:MM" per long video, e.g. ["12:00", "20:00"]\n\n  kids_edu:                                # Q1\n    run: true                              # Q2.  Options: true | false\n    genre: "Kids entertainment and game-show education: interactive animal mysteries, amazing creature superpowers, and guess-the-animal challenges"\n    search_phrases:\n      - "guess the animal for kids #shorts"\n      - "amazing animal superpowers kids #shorts"\n      - "which animal is this kids quiz #shorts"\n      - "wild animal fun facts for kids #shorts"\n      - "animal sound challenge kids #shorts"\n    language: "English"                    # Q5.  Options: "English" | "Hindi" | "Telugu"\n    voice: "en-US-AvaMultilingualNeural"        # Q6.  Options: see VOICE OPTIONS above\n    voice_speed: "+0%"                     # Q7.  Options: "-15%" | "-5%" | "+0%" | "+10%"\n    voice_expression: "lively"             # Q7b. Options: "lively" | "measured" | "off"\n    tone: "An enthusiastic, joyful kids game-show host! High energy, playful, full of interactive questions, 3-second countdowns, cheering reveals, and amazing animal mysteries. Speaks directly to the kids watching."\n    video_length_seconds: 30               # Q9.  Options: 15 | 30 | 45 | 60\n    avoid_words: []                        # Q10. Options: [] | ["word1", "word2"]\n    lookback_days: 5                       # Q11. Options: 1 to 30\n    fetch_time: ["06:00", "13:00", "17:00"]  # Q12. Options: "HH:MM" | ["HH:MM", ...]\n    short_post_times: ["09:00", "14:30"]   # 1 Short in the morning run, 1 in the afternoon run\n                                           # Q13. Options: list of "HH:MM", one per Short\n    days: "daily"                          # Q16. Options: "daily" | "weekdays" | "weekends" | [mon, wed, fri]\n    timezone: "Asia/Kolkata"               # Q17\n    visibility: "public"                   # Q18. Options: "public" | "unlisted" | "private"\n    test_run: false                        # Q19. Options: true | false\n    exclude_sources: []                    # Q20. Options: [] | ["Channel Name 1", "Channel Name 2"]\n    footage_style: "film"                  # Q21. Options: "any" | "animation" (cartoon) | "film" (real-life stock: animals, nature) | "mixed" | "real" (Wikimedia Commons news footage first: not for kids)\n    long_videos_per_day: 3                 # Q22. Options: 0 (none) to 4\n    long_video_minutes: "5-7"              # Q23. Options: 4 | 5 | 6 | 7 | "4-5" | "4-6" | "5-6" | "5-7" | "6-7"\n    long_post_times: ["11:30", "16:00", "18:30"]  # Q24. One per run: morning, afternoon, evening\n\n# =====================================================================\n#  TEMPLATE  (copy, paste under "channels:", remove the "# ", answer each)\n# =====================================================================\n#\n#  my_channel_key:                         # Q1. same key as in channels.yaml\n#    run: true                             # Q2. true | false\n#    genre: "cricket highlights"           # Q3. any text\n#    search_phrases:                       # Q4. 1 to 5 lines\n#      - "cricket highlights #shorts"\n#      - "ipl best moments #shorts"\n#    language: "Telugu"                    # Q5. "English" | "Hindi" | "Telugu"\n#    voice: "te-IN-MohanNeural"            # Q6. see VOICE OPTIONS (must match language)\n#    voice_speed: "-5%"                    # Q7. "-15%" | "-5%" | "+0%" | "+10%"\n#    voice_expression: "measured"          # Q7b. "lively" | "measured" | "off"\n#    tone: "Energetic sports commentary."  # Q8. any text\n#    video_length_seconds: 30              # Q9. 15 | 30 | 45 | 60\n#    avoid_words: []                       # Q10. [] | ["word1", "word2"]\n#    lookback_days: 3                      # Q11. 1 to 30\n#    fetch_time: "06:00"                   # Q12. "HH:MM" | ["HH:MM", "HH:MM"]\n#    short_post_times: []                  # Q13. list of "HH:MM" (one per Short), or leave out and use the next 3 lines\n#    first_post_time: "07:00"              # Q13. "HH:MM"\n#    post_frequency: "1 hour"              # Q14. "15 mins" | "30 mins" | "1 hour" | "3 hours"\n#    videos_per_day: 8                     # Q15. 1 to 50\n#    days: "daily"                         # Q16. "daily" | "weekdays" | "weekends" | [mon, wed, fri]\n#    timezone: "Asia/Kolkata"              # Q17. timezone name\n#    visibility: "public"                  # Q18. "public" | "unlisted" | "private"\n#    test_run: false                       # Q19. true | false\n#    exclude_sources: []                   # Q20. [] | ["Channel Name 1", "Channel Name 2"]\n#    footage_style: "any"                  # Q21. "any" | "animation" | "film" | "mixed" | "real"\n#    long_videos_per_day: 0                # Q22. 0 to 4\n#    long_video_minutes: 6                 # Q23. 4 | 5 | 6 | 7 | "4-5" | "4-6" | "5-6" | "5-7" | "6-7"\n#    long_post_times: []                   # Q24. one "HH:MM" per long video, e.g. ["14:00", "20:00"]\n',
    'execution/view_techniques.md': '# View Techniques\n\nWhat we have learned about getting more views, and the rules every video follows because of it.\n\n- **ACTIVE RULES** (below) are sent to Gemini with every script, title and hashtag request. Keep them short: every\n  word is sent with every request.\n- **HOW THE PIPELINE APPLIES THEM** lists the rules that are built into the code instead (topic choice, schedule,\n  measurement). Changing those needs a code change.\n- **SOURCES** records every video analysed, what it teaches, and what we adopted, did manually, or rejected.\n\n**To analyse a new video:** post its link in the Telegram alerts channel (the bot replies; "approve S5" adopts\nits rules), or run `python execution/execution.py --learn <youtube link>`. It reads the video\'s\ntitle, description, statistics and transcript, asks Gemini for the techniques, and adds an entry at the end of\nSOURCES marked "proposed". Nothing changes until a proposal is reviewed: copy the good rules into ACTIVE RULES (or\nask Claude to), and mark the entry "reviewed". Never adopt anything that fakes engagement, misleads viewers or reuses\nother people\'s videos; it breaks YouTube\'s policies and can get a channel removed.\n\n## ACTIVE RULES\n1. Ride the trend: open with what is new right now in this topic (today\'s development, the newest fact, the moment\n   people are talking about), and name it in the title. A current topic beats a polished evergreen one. [S1]\n2. Stay inside the channel\'s niche and speak to its core audience every time. If the source topic is off-niche,\n   take the angle that fits the niche; never drift to an unrelated subject. [S1]\n3. Write for retention (target: viewers stay for at least 30% of a long video and most of a Short) [S1]:\n   - No greeting, intro or channel name at the start; the first sentence is the hook.\n   - Make a promise in the first 5 seconds and pay it off only near the end.\n   - Long videos: every 30 to 45 seconds add a new fact, twist or question; tease what is coming ("in a moment...").\n   - Shorts: one idea, no filler; the last line should lead naturally back into the first so the Short loops.\n4. Title for clicks without misleading [S1]: put the topic keyword people search for in the first 3 to 5 words,\n   add curiosity or a number, stay under 60 characters (70 for long videos), and only promise what the video\n   delivers.\n\n## HOW THE PIPELINE APPLIES THEM\n| Technique | Where | What it does |\n|---|---|---|\n| Trends [S1] | Agent 1, Scout | Ranks trending source videos by **views per hour since upload** (what is rising now), not total views. |\n| One audience per channel [S1] | Agent 1, Scout | Skips source videos that aren\'t in the channel\'s language (an English channel no longer takes Hindi topics), unless nothing else is found. |\n| Consistency [S1] | Schedule | Fixed daily go-live times in `questions.yaml`; finished videos that miss their run are uploaded in the next one. |\n| Learn from results [S1] | Agent 8, Analyst | Records every uploaded video\'s views. Each channel\'s search phrases are ordered by the views their videos got after 48 hours (phrases not tried for 3 days are tried again first), and a daily Telegram report shows what works. |\n| Retention and title rules [S1] | ACTIVE RULES above | Sent to Gemini with every script and title. |\n| Real, current footage [S2] | Agent 2, Footage | Frontline (`footage_style: "real"`) shows real footage of the actual people, places and events from Wikimedia Commons (public domain, CC0, CC BY only), shown whole in Shorts. |\n| Picture matches the words [S2] | Agent 2, Footage | Stock clips are only used if their tags match the scene\'s subject (not just "cartoon"); kids scenes with no matching video get a matching cartoon illustration; otherwise the backup term is tried. |\n| Faster cuts [S2] | BRAIN.md `footage` | About 6 clips per Short (was 3) and a new clip about every 8 seconds in long videos (was 15). |\n| A human-sounding voice [S2] | Agent 3, `expressive_voice.py` | Each sentence gets its own pitch, speed and volume (`voice_expression`: lively for kids, measured for news). |\n| Fun, hooky kids stories [S2] | BRAIN.md Agent 3 instructions | Named heroes with a funny trait, a silly problem, three escalating tries, a twist; sound words; the viewer is asked something every 20 to 30 seconds. |\n| A recognisable host for kids [S2] | Agent 4, `mascot.py` | WonderSprout, a woman superhero, narrates and reacts on screen (intro, expressions, outro); a recurring character gives kids a reason to come back. |\n| Trending hashtags for reach [S2] | Agents 1 and 5 | The hashtags the fastest-rising niche videos use right now lead each description, followed by the topic\'s own (up to 12). |\n| Search keywords people actually type [S3] | Agents 1, 3, 5 and 7 | The Scout collects real search phrases for each niche phrase (YouTube autocomplete, free and outside the API quota; other-language ones dropped) and the keyword tags of the fastest-rising videos (already fetched, no extra quota). The script AI picks one main KEYWORD from them, puts it in the first words of the title and the first description sentence, and writes 6 close variations (same request). The upload\'s hidden tags lead with the keyword, its variations and the real phrases whose every word is in the video (no stuffing, no other channels\' names). Telegram shows the keyword (🔎). |\n\n**Not automated yet (owner):**\n- Custom thumbnails strongly affect click-through, but YouTube only allows them on phone-verified channels\n  (youtube.com/verify). Verify first; generating thumbnails could be added after.\n- Average view duration and click-through rate are only in YouTube Analytics (Studio → Analytics), which this\n  pipeline\'s login can\'t read yet. Check them weekly against the targets: about 30% average view duration on long\n  videos and 5 to 10% click-through rate.\n- Patience: the source\'s channel took 9 months of consistent uploads before it grew.\n\n## SOURCES\n\n### S1. "Why Your Views STOP After 48 Hours (learn how to fix it)" by Danny Why\n- Link: https://youtu.be/-bIvqlrCBNI\n- When analysed: 2026-10-22, by Claude from the full transcript (11:37 long; 1.2M views, 36K likes, 8.6K comments;\n  published 2025-12-27)\n- Status: reviewed\n\n**What it teaches:**\n1. **Trends beat polish.** His video with a lower click-through rate and shorter view duration got 3x the views of\n   a "better" one, because it was about something people were talking about that week.\n   → Adopted: ACTIVE RULES 1, Scout ranks by views per hour.\n2. **One niche per channel.** YouTube shows a new video first to the audience of your previous videos; a different\n   topic reaches the wrong people, gets low watch time and stops being pushed.\n   → Adopted: ACTIVE RULES 2, Scout skips other-language sources. Note: WonderSprout mixes stories, animal facts and\n   science facts; all are for the same kids audience, so it stays one niche.\n3. **Consistency builds trust** with viewers and the algorithm (the "shop that is always open").\n   → Already done: fixed daily schedule.\n4. **Benchmarks** (his experience, not a YouTube rule): a 10-minute video needs about 30% average view duration to\n   keep growing; once past about 100K impressions, click-through rate must stay at 5 to 10%.\n   → Adopted as targets: ACTIVE RULES 3 and 4; the owner checks them in Studio (see "Not automated yet").\n5. **Give it time;** growth often comes after months of steady uploads.\n   → Noted for the owner.\n6. Sponsor segments (a clipping tool, a paid community) are adverts, not techniques. → Skipped.\n\n### S2. Owner\'s feedback from real viewers (2026-10-24)\n- Source: the owner showed the channels to real viewers and reported their feedback; YouTube stats at the time:\n  WonderSprout Shorts weren\'t engaging, a few WonderSprout long videos reached about 200 views, Frontline had almost\n  no views.\n- Status: reviewed\n\n**What it teaches:**\n1. **Frontline isn\'t interactive or "real-time":** narration over generic stock scenery doesn\'t feel like news, and\n   the pictures often didn\'t match the words.\n   → Adopted: real footage of the actual people and events (Wikimedia Commons), tag-matched stock clips, faster cuts.\n   Copyrighted news-agency footage is not used (Content ID claims, copyright strikes).\n2. **The voice sounds robotic** (one flat tone).\n   → Adopted: sentence-by-sentence expression; voice samples in Google Drive `YouTube_Auto/voice_samples` for the\n   owner to choose more natural voices (Ava, Emma, Andrew, Brian).\n3. **Kids need fun and hooks, and long videos work better than Shorts** on WonderSprout.\n   → Adopted: new kids writing rules; WonderSprout moved to 3 long videos and 2 Shorts a day (was 2 and 6).\n4. **More reach from trending hashtags** in each niche.\n   → Adopted: trending niche hashtags first in every description.\n\n### S3. Owner\'s observation: keywords plus hashtags (2026-10-31)\n- Source: the owner saw a video on Instagram or YouTube (link not kept) showing that videos reach more people when\n  they use proper search keywords together with hashtags.\n- Status: reviewed\n\n**What it teaches:**\n1. **Use the words people actually search**, not only hashtags: YouTube matches searches against the title,\n   description and tags.\n   → Adopted: real search phrases (YouTube autocomplete and rising videos\' keyword tags) go to the script AI, which\n   puts one main keyword in the title\'s first words and the first description sentence (ACTIVE RULE 4 already asked\n   for this; now it has real data instead of a guess).\n2. **Keywords and hashtags together.**\n   → Adopted: the hidden upload tags lead with the keyword and its variations; the trending hashtags are unchanged.\n3. Rejected: keyword stuffing (lists of keywords in the description, unrelated popular phrases or other channels\'\n   names in tags). It\'s against YouTube\'s spam and misleading-metadata policies; only phrases the video is about are\n   used.\n',
    'execution/video_requests.json': '{\n  "next_id": 1,\n  "requests": []\n}\n',
    '../.github/workflows/daily_youtube_agents.yml': 'name: Daily YouTube Multi-Agent Pipeline\n\non:\n  schedule:\n    # BEGIN CHANNEL SCHEDULE (fetch times from execution/questions.yaml, updated by: python execution/execution.py --check)\n    - cron: \'5 3 * * *\'\n    - cron: \'5 7 * * *\'\n    - cron: \'5 20 * * *\'\n    # END CHANNEL SCHEDULE\n  workflow_dispatch:\n    inputs:\n      channel:\n        description: \'Channel key, or "all" for every channel with run: true. Blank fields below use execution/questions.yaml\'\n        required: true\n        default: \'all\'\n        type: string\n      genre:\n        description: \'One-off genre to source trending videos for\'\n        required: false\n        type: string\n      videos:\n        description: \'One-off number of videos (1 to 50)\'\n        required: false\n        type: string\n      first_post_time:\n        description: \'One-off time the first video goes live, HH:MM in the channel timezone\'\n        required: false\n        type: string\n      frequency:\n        description: \'One-off gap between videos\'\n        required: false\n        default: \'from questions.yaml\'\n        type: choice\n        options:\n          - \'from questions.yaml\'\n          - \'15 mins\'\n          - \'30 mins\'\n          - \'1 hour\'\n          - \'3 hours\'\n      format:\n        description: \'Which videos to make\'\n        required: false\n        default: \'both\'\n        type: choice\n        options:\n          - \'both\'\n          - \'short\'\n          - \'long\'\n      dry_run:\n        description: \'Test run: make the videos but do not upload\'\n        required: false\n        default: false\n        type: boolean\n\nconcurrency:\n  group: youtube-pipeline\n  cancel-in-progress: false\n\njobs:\n  run-youtube-agents:\n    runs-on: ubuntu-latest\n    timeout-minutes: 240\n    defaults:\n      run:\n        working-directory: youtube-automation-agents\n\n    steps:\n      - name: 1. Checkout Repository Code\n        uses: actions/checkout@v7\n\n      - name: 2. Set Up Python 3.11\n        uses: actions/setup-python@v7\n        with:\n          python-version: \'3.11\'\n          cache: \'pip\'\n          cache-dependency-path: youtube-automation-agents/requirements.txt\n\n      - name: 3. Decide Which Channels Are Due\n        id: plan\n        env:\n          REQUESTED_CHANNEL: ${{ github.event.inputs.channel }}\n          TRIGGER_CRON: ${{ github.event.schedule }}\n        run: |\n          pip install pyyaml\n          if [ -n "$REQUESTED_CHANNEL" ]; then\n            CHANNELS="$REQUESTED_CHANNEL"\n          else\n            CHANNELS="$(python execution/execution.py --due --cron "$TRIGGER_CRON")"\n          fi\n          echo "Channels to run: ${CHANNELS:-none}"\n          echo "channels=$CHANNELS" >> "$GITHUB_OUTPUT"\n\n      - name: 4. Install FFmpeg & Rclone\n        if: steps.plan.outputs.channels != \'\'\n        run: |\n          sudo apt-get update\n          sudo apt-get install -y ffmpeg rclone\n\n      - name: 5. Install Python Dependencies\n        if: steps.plan.outputs.channels != \'\'\n        run: pip install -r requirements.txt\n\n      - name: 6. Restore API Keys\n        if: steps.plan.outputs.channels != \'\'\n        env:\n          YOUTUBE_API_KEY: ${{ secrets.YOUTUBE_API_KEY }}\n          GEMINI_API_KEY: ${{ secrets.GEMINI_API_KEY }}\n          # Stock footage. To use Pexels instead, add a PEXELS_API_KEY secret and pass it here the same way\n          PIXABAY_API_KEY: ${{ secrets.PIXABAY_API_KEY }}\n          # Free backup AI used when Gemini\'s daily quota runs out\n          GROQ_API_KEY: ${{ secrets.GROQ_API_KEY }}\n          TELEGRAM_BOT_TOKEN: ${{ secrets.TELEGRAM_BOT_TOKEN }}\n          TELEGRAM_CHANNEL_ID: ${{ secrets.TELEGRAM_CHANNEL_ID }}\n          CLIENT_SECRET_JSON: ${{ secrets.CLIENT_SECRET_JSON }}\n        run: |\n          echo "YOUTUBE_API_KEY=${YOUTUBE_API_KEY}" >> .env\n          echo "GEMINI_API_KEY=${GEMINI_API_KEY}" >> .env\n          echo "PIXABAY_API_KEY=${PIXABAY_API_KEY}" >> .env\n          echo "GROQ_API_KEY=${GROQ_API_KEY}" >> .env\n          echo "TELEGRAM_BOT_TOKEN=${TELEGRAM_BOT_TOKEN}" >> .env\n          echo "TELEGRAM_CHANNEL_ID=${TELEGRAM_CHANNEL_ID}" >> .env\n          echo "${CLIENT_SECRET_JSON}" > client_secret.json\n\n      - name: 7. Pull Channel Logins, Manifest & Prior Edited Videos from Google Drive\n        if: steps.plan.outputs.channels != \'\'\n        env:\n          # Not named RCLONE_CONFIG: rclone reads that variable as the config file\'s path, not its contents\n          GDRIVE_RCLONE_CONF: ${{ secrets.RCLONE_CONFIG_GDRIVE }}\n        run: |\n          mkdir -p ~/.config/rclone\n          printf \'%s\\n\' "${GDRIVE_RCLONE_CONF}" > ~/.config/rclone/rclone.conf\n          chmod 600 ~/.config/rclone/rclone.conf\n          mkdir -p ./GDrive_Mount/YouTube_Automation/00_tokens\n          mkdir -p ./GDrive_Mount/YouTube_Automation/01_manifests\n          mkdir -p ./GDrive_Mount/YouTube_Automation/03_edited_videos\n          rclone copy gdrive:YouTube_Automation/00_tokens ./GDrive_Mount/YouTube_Automation/00_tokens\n          rclone copy gdrive:YouTube_Automation/01_manifests ./GDrive_Mount/YouTube_Automation/01_manifests || true\n          rclone copy gdrive:YouTube_Automation/03_edited_videos ./GDrive_Mount/YouTube_Automation/03_edited_videos || true\n\n      - name: 8. Run the Pipeline (execution/execution.py)\n        if: steps.plan.outputs.channels != \'\'\n        env:\n          EVENT_NAME: ${{ github.event_name }}\n          TRIGGER_CRON: ${{ github.event.schedule }}\n          CHANNEL: ${{ github.event.inputs.channel }}\n          GENRE: ${{ github.event.inputs.genre }}\n          VIDEOS: ${{ github.event.inputs.videos }}\n          FIRST_POST: ${{ github.event.inputs.first_post_time }}\n          FREQUENCY: ${{ github.event.inputs.frequency }}\n          FORMAT: ${{ github.event.inputs.format }}\n          DRY_RUN: ${{ github.event.inputs.dry_run }}\n        run: |\n          if [ "$EVENT_NAME" = "workflow_dispatch" ]; then\n            EXTRA=""\n            if [ "$DRY_RUN" = "true" ]; then EXTRA="--dry-run"; fi\n            if [ "$FREQUENCY" = "from questions.yaml" ]; then FREQUENCY=""; fi\n            python execution/execution.py --channel "$CHANNEL" --genre "$GENRE" --videos "$VIDEOS" \\\n              --first-post "$FIRST_POST" --frequency "$FREQUENCY" --format "${FORMAT:-both}" $EXTRA\n          else\n            python execution/execution.py --scheduled --cron "$TRIGGER_CRON"\n          fi\n\n      - name: 9. Sync Cleaned Folders, Logins & Updated Manifest Back to Google Drive\n        if: always() && steps.plan.outputs.channels != \'\'\n        run: |\n          rclone copy ./GDrive_Mount/YouTube_Automation/00_tokens gdrive:YouTube_Automation/00_tokens\n          rclone copy ./GDrive_Mount/YouTube_Automation/01_manifests gdrive:YouTube_Automation/01_manifests\n          rclone sync ./GDrive_Mount/YouTube_Automation/03_edited_videos gdrive:YouTube_Automation/03_edited_videos\n          rclone delete gdrive:YouTube_Automation/02_raw_videos || true\n          rclone delete gdrive:YouTube_Automation/02_audio_voiceovers || true\n',
    '../.github/workflows/telegram_inbox.yml': 'name: Telegram Inbox (learn from shared videos and requests)\n\n# Reads the posts in the Telegram alerts channel (agents/inbox.py): YouTube links to learn from or make videos\n# like, "make a ... video about ..." requests, and approve / reject / cancel / queue replies. Adopted rules\n# (execution/view_techniques.md) and queued requests (execution/video_requests.json) are committed to main, so\n# the next daily run uses them. Telegram keeps unread posts for 24 hours; GitHub may start a scheduled run late.\non:\n  schedule:\n    - cron: \'17 * * * *\'\n  workflow_dispatch:\n\npermissions:\n  contents: write\n\nconcurrency:\n  group: telegram-inbox\n  cancel-in-progress: false\n\njobs:\n  inbox:\n    runs-on: ubuntu-latest\n    timeout-minutes: 20\n    defaults:\n      run:\n        working-directory: youtube-automation-agents\n\n    steps:\n      - name: 1. Checkout Repository Code\n        uses: actions/checkout@v7\n\n      - name: 2. Set Up Python 3.11\n        uses: actions/setup-python@v7\n        with:\n          python-version: \'3.11\'\n          cache: \'pip\'\n          cache-dependency-path: youtube-automation-agents/requirements.txt\n\n      - name: 3. Install Python Dependencies\n        run: pip install -r requirements.txt\n\n      - name: 4. Handle Telegram Posts\n        env:\n          YOUTUBE_API_KEY: ${{ secrets.YOUTUBE_API_KEY }}\n          GEMINI_API_KEY: ${{ secrets.GEMINI_API_KEY }}\n          GROQ_API_KEY: ${{ secrets.GROQ_API_KEY }}\n          TELEGRAM_BOT_TOKEN: ${{ secrets.TELEGRAM_BOT_TOKEN }}\n          TELEGRAM_CHANNEL_ID: ${{ secrets.TELEGRAM_CHANNEL_ID }}\n        run: python execution/execution.py --inbox\n\n      - name: 5. Save Adopted Rules and Queued Requests\n        run: |\n          if git diff --quiet -- execution/view_techniques.md execution/video_requests.json; then\n            echo "Nothing to save."\n            exit 0\n          fi\n          git config user.name "github-actions[bot]"\n          git config user.email "41898282+github-actions[bot]@users.noreply.github.com"\n          git add execution/view_techniques.md execution/video_requests.json\n          git commit -m "Telegram inbox: learned rules and video requests"\n          git pull --rebase origin main\n          git push origin HEAD:main\n',
}


def build_project():
    for filepath, content in FILES.items():
        dir_name = os.path.dirname(filepath)
        if dir_name:
            os.makedirs(dir_name, exist_ok=True)
        with open(filepath, "w", encoding="utf-8", newline="") as f:
            f.write(content)
        print(f"[+] Created: {filepath}")

    os.makedirs("./GDrive_Mount/YouTube_Automation/00_tokens", exist_ok=True)
    print()
    print("[SUCCESS] Entire Multi-Agent Project & GitHub Action Workflow generated!")


if __name__ == "__main__":
    build_project()
